def _soft_lbfgs(h0, deadline, beta, maxiter=150):
    return _lbfgs_custom(h0, lambda h: _fun_grad_soft(h, beta),
                         deadline, maxiter=maxiter)


def _upsample(h, n):
    x_old = np.linspace(0.0, 1.0, h.size)
    x_new = np.linspace(0.0, 1.0, n)
    up = np.interp(x_new, x_old, h)
    return _rescale(np.clip(up, 0, None))


def _polish(h, deadline, maxiter=200, soft_betas=(200.0, 800.0)):
    """Full L-BFGS then a couple of soft-max passes to widen the plateau."""
    h = _rescale(h)
    r = R_of(h)
    t = min(deadline - 0.3, time.process_time() + 4.0)
    hc = _full_lbfgs(h, t, maxiter=maxiter)
    rc = R_of(hc)
    if rc > r:
        h, r = hc, rc
    for beta in soft_betas:
        if time.process_time() >= deadline - 0.5:
            break
        t = min(deadline - 0.3, time.process_time() + 2.0)
        hs = _soft_lbfgs(h, t, beta, maxiter=maxiter)
        rs = R_of(hs)
        if rs > r:
            h, r = hs, rs
        t = min(deadline - 0.3, time.process_time() + 2.0)
        hc = _full_lbfgs(h, t, maxiter=maxiter)
        rc = R_of(hc)
        if rc > r:
            h, r = hc, rc
    return h, r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    best = None
    bestR = 0.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            s = _rescale(s)
            best = s
            bestR = R_of(s)

    # Upsample the start and polish through the resolution ladder.
    if best is not None:
        base = best.copy()
    else:
        n0 = 4096
        x = np.linspace(0, 1, n0)
        base = _rescale(np.clip(np.sin(np.pi * x) + 0.05, 1e-6, None))
        best = base
        bestR = R_of(base)

    # Ladder: work through increasing resolutions, polishing each.
    n = base.size
    targets = []
    while n < 200000:
        n = int(n * 1.5) + 64
        targets.append(min(n, 200000))
    targets = targets[-6:] if len(targets) > 6 else targets

    for n_t in targets:
        if time.process_time() >= deadline - 2.0:
            break
        hup = _upsample(best, n_t)
        r_up = R_of(hup)
        if r_up > bestR:
            best, bestR = hup, r_up
        tlim = min(deadline - 1.0, time.process_time() + 5.0)
        h, r = _polish(best, tlim, maxiter=200)
        if r > bestR:
            best, bestR = h, r

    # Remaining budget: keep polishing at current resolution with soft betas.
    beta_cycle = [200.0, 800.0, 3000.0]
    k = 0
    while time.process_time() < deadline - 1.0:
        tlim = min(deadline - 0.5, time.process_time() + 3.0)
        h, r = _polish(best, tlim, maxiter=200,
                       soft_betas=(beta_cycle[k % len(beta_cycle)],))
        if r > bestR:
            best, bestR = h, r
        k += 1
        if k > 30:
            break

    best = _rescale(np.clip(best, 0, None))
    if best.sum() <= 0:
        best = np.ones(50)

    result = {"best": best, "alternative": best}
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            rs = R_of(s)
            if rs >= bestR and best.size != s.size:
                result = {"best": s, "alternative": best}
            elif rs >= bestR:
                result = {"best": s, "alternative": best}
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // 8)
    hi = min(n, int(c) + pad + n // 8)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


# ---- refinement on the peak constraint: maximize ||f*f||_2^2 with fixed max ----

def _fun_grad_proj(h):
    """Maximize num subject to fixed max, projecting out the two constraint
    gradients (mass and tie-averaged max)."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    dnum = _backprop(dq, h)
    dmax = np.zeros_like(Lf)
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    dmax[idx] = 1.0 / idx.size
    dmax_h = _backprop(dmax, h)
    dmass = np.ones(h.size)
    # Gram-Schmidt against dmass, dmax_h
    v = dnum.copy()
    for c in (dmass, dmax_h):
        nv = np.dot(c, c)
        if nv > 1e-30:
            v = v - (np.dot(v, c) / nv) * c
    # we minimize -num
    return -num, -v


def _lbfgs_proj(h0, deadline, maxiter=200):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = _fun_grad_proj(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _coarsen(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(Nc)
    edges = np.linspace(0.0, total, Nc + 1)
    vals = np.interp(edges, np.linspace(0.0, total, n + 1), c)
    hc = np.diff(vals)
    return np.clip(hc, 0.0, None)


def _prolong(hc, N):
    Nc = hc.size
    if Nc == N:
        return hc.copy()
    c = np.concatenate(([0.0], np.cumsum(hc)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    edges = np.linspace(0.0, total, N + 1)
    vals = np.interp(edges, np.linspace(0.0, total, Nc + 1), c)
    hf = np.diff(vals)
    return np.clip(hf, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.9f (N=%d)" % (bestR, N))

    # Phase A: peak-window polish (cheap, exact tie objective)
    cand = best.copy()
    candR = bestR
    for pad in (3, 6, 12):
        if time.process_time() > t0 + budget_seconds * 0.25:
            break
        ht = _peak_window_polish(cand, deadline, pad=pad)
        r = R_of(ht)
        if r > candR + 1e-15:
            cand, candR = ht, r
    print("after peak polish R=%.9f" % candR)

    # Phase B: projected refinement (maximize num with fixed max) then accept
    proj_end = t0 + budget_seconds * 0.55
    if time.process_time() < proj_end - 2.0:
        hp = _lbfgs_proj(cand, proj_end, maxiter=200)
        rp = R_of(hp)
        print("projected refine R=%.9f" % rp)
        if rp > candR + 1e-15:
            cand, candR = hp, rp

    # Phase C: full tie L-BFGS
    if time.process_time() < deadline - 3.0:
        ht = _full_lbfgs(cand, deadline - 1.0, maxiter=300)
        rt = R_of(ht)
        if rt > candR + 1e-15:
            cand, candR = ht, rt
            print("full tie ACCEPT R=%.9f" % candR)

    # Phase D: cvar smoothing ladder to escape near-tie plateaus
    cvar_end = t0 + budget_seconds * 0.85
    for alpha in (0.02, 0.01, 0.005, 0.002):
        if time.process_time() >= cvar_end - 1.5:
            break
        hc = _lbfgs_custom(cand, lambda hh, a=alpha: _fun_grad_cvar(hh, a),
                           cvar_end - 0.5, maxiter=120)
        rc = R_of(hc)
        if rc > candR + 1e-15:
            cand, candR = hc, rc
            print("cvar a=%.3f ACCEPT R=%.9f" % (alpha, candR))
            ht = _full_lbfgs(cand, cvar_end - 0.3, maxiter=150)
            rt = R_of(ht)
            if rt > candR + 1e-15:
                cand, candR = ht, rt

    # Phase E: final peak-window + full polish
    if time.process_time() < deadline - 2.0:
        ht = _peak_window_polish(cand, deadline - 1.0, pad=6)
        rt = R_of(ht)
        if rt > candR + 1e-15:
            cand, candR = ht, rt
    if time.process_time() < deadline - 1.5:
        ht = _full_lbfgs(cand, deadline - 0.3, maxiter=200)
        rt = R_of(ht)
        if rt > candR + 1e-15:
            cand, candR = ht, rt
            print("final tie ACCEPT R=%.9f" % candR)

    print("candidate R=%.9f (start %.9f)" % (candR, startR))

    if candR > startR + 1e-15:
        print("GAIN R=%.9f" % candR)
        return {"best": cand}
    else:
        print("no gain")
        return {"best": best, "alternative": cand}

