    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 1e-30, None)
    x0 = np.log(h)

    def f(x):
        hh = np.exp(x)
        val, g = _fun_grad_tie(hh)
        return val, g * hh

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(res.x))


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_repeat(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-12, atol=1e-15):
            hr = np.repeat(c, p)
            if abs(R_of(hr) - R_of(h)) <= 1e-12:
                return p, c
    return 1, h


def _jitter(c, rng):
    n = c.size
    c2 = c.copy()
    nblocks = rng.integers(1, 4)
    for _ in range(nblocks):
        L = int(rng.integers(2, 65))
        if L >= n:
            L = n
        st = int(rng.integers(0, n - L + 1))
        fac = np.exp(rng.normal(0.0, 0.02, size=L))
        c2[st:st + L] *= fac
    return c2


def _interp_lift(c):
    n = c.size
    c2 = np.empty(2 * n)
    c2[0::2] = c
    c2[1:-1:2] = 0.5 * (c[:-1] + c[1:])
    c2[-1] = c[-1]
    return c2


def _coarse(c_in, m):
    n = c_in.size
    if m == n:
        return c_in.copy()
    x = np.linspace(0.0, n, m, endpoint=False) + 0.5 * (n / m)
    xi = np.arange(n, dtype=float) + 0.5
    return np.interp(x, xi, c_in)


def _prolong(c_coarse, m_out):
    m = c_coarse.size
    if m_out == m:
        return c_coarse.copy()
    x = np.linspace(0.0, m, m_out, endpoint=False) + 0.5 * (m_out / m)
    xi = np.arange(m, dtype=float) + 0.5
    return np.interp(x, xi, c_coarse)


def _polish_c(c, p, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return c, R_of(np.repeat(c, p))
    h = _rescale(np.repeat(c, p))
    h2 = _lbfgs_block(h, np.arange(h.size), maxiter, deadline)
    c2 = h2.reshape(-1, p).mean(axis=1)
    return c2, R_of(np.repeat(c2, p))


# --- NEW: block-invariant optimisation.  The construction is organised as
# blocks of width p; we treat the block profile c as the variable, and
# optimise R(repeat(c,p)) directly using the fact that the gradient of the
# full h lifted back to c is just the block-summed gradient.  This is a
# different parametrisation from the previous program (which only used
# block-invariance for coarse search and then optimised full h). ---

def _fun_grad_c(c, p):
    h = np.repeat(c, p)
    val, g = _fun_grad_tie(h)
    gc = g.reshape(-1, p).sum(axis=1)
    return val, gc


def _lbfgs_c(c0, p, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return c0
    c = np.clip(c0, 1e-30, None)
    x0 = np.log(c)

    def f(x):
        cc = np.exp(x)
        val, g = _fun_grad_c(cc, p)
        return val, g * cc

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    c2 = np.exp(res.x)
    # rescale so that max knot of repeat(c2,p) = 1
    h = np.repeat(c2, p)
    return c2 / np.sqrt(_knots(h).max())


def _vcycle_c(c, p, deadline, levels, best, bestR):
    n_c = c.size
    coarse_list = [(n_c, c.copy())]
    cur = c
    for m in levels[1:]:
        cur = _coarse(cur, m)
        coarse_list.append((m, cur.copy()))
    m, cc = coarse_list[-1]
    cc = _lbfgs_c(cc, p, 120, min(deadline, time.process_time() + 2.0))
    r = R_of(np.repeat(cc, p))
    print("  vc level=%d R=%.9f" % (m, r))
    if r > bestR + 1e-15:
        best, bestR = _rescale(np.repeat(cc, p)), r
    for i in range(len(coarse_list) - 2, -1, -1):
        m_out, _ = coarse_list[i]
        cc = _prolong(cc, m_out)
        cc = _lbfgs_c(cc, p, 150,
                      min(deadline, time.process_time() + 2.5))
        coarse_list[i] = (m_out, cc)
        r = R_of(np.repeat(cc, p))
        print("  vc level=%d R=%.9f" % (m_out, r))
        if r > bestR + 1e-15:
            best, bestR = _rescale(np.repeat(cc, p)), r
    return best, bestR, cc


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    span = deadline - t0

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    p, c = _detect_repeat(best)
    print("repeat p=%d n_c=%d" % (p, c.size))

    # ---- Phase C1: block-invariant V-cycles (new parametrisation) ----
    c_end = t0 + span * 0.55
    if p > 1 and c.size >= 8 and time.process_time() < c_end - 2.0:
        levels = [c.size]
        m = c.size
        while len(levels) < 4 and m > 16:
            m = max(16, m // 2)
            if m >= levels[-1]:
                break
            levels.append(m)
        print("vc levels=%s" % levels)
        cycle = 0
        while time.process_time() < c_end - 2.0:
            cycle += 1
            best, bestR, c = _vcycle_c(c, p, c_end, levels, best, bestR)
            print("vc cycle=%d bestR=%.9f" % (cycle, bestR))
            if cycle >= 3 and time.process_time() > c_end - 4.0:
                break

    # ---- Phase C2: direct block refinement on full profile ----
    c_end2 = t0 + span * 0.72
    if p > 1 and time.process_time() < c_end2 - 1.0:
        for _ in range(6):
            if time.process_time() >= c_end2 - 0.5:
                break
            c2 = _jitter(c, np.random.default_rng(int(time.process_time() * 1e6) & 0xffff))
            c2 = _lbfgs_c(c2, p, 300,
                          min(c_end2 - 0.3, time.process_time() + 2.0))
            r = R_of(np.repeat(c2, p))
            if r > bestR + 1e-15:
                best = _rescale(np.repeat(c2, p))
                bestR, c = r, c2
                print("block refine R=%.9f" % bestR)

    # ---- Phase E: peak-window polish on full N ----
    pad_seq = (0.10, 0.06, 0.04, 0.025, 0.015, 0.008, 0.004, 0.002)
    for pad in pad_seq:
        if time.process_time() >= deadline - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 500,
                          min(deadline - 0.5, time.process_time() + 4.0))
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        print("peak pad=%.3f R=%.9f" % (pad, bestR))

    # ---- Phase F: full log polish ----
    if time.process_time() < deadline - 1.5:
        ht = _lbfgs_log(best, 300, deadline - 1.0)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
        print("final log polish R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_soft(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    zmax = z.max()
    e = np.exp(z - zmax)
    Z = e.sum()
    w = e / Z
    softmax_val = M + (np.log(Z) + zmax) / beta
    gLf = -dq / num
    gLf += w / softmax_val
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(softmax_val)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _soft_lbfgs(h0, deadline, beta, maxiter=150):
    return _lbfgs_custom(h0, lambda h: _fun_grad_soft(h, beta),
                         deadline, maxiter=maxiter)


def _refine(h, deadline, levels=(2, 3, 4)):
    best = _rescale(h.copy())
    bestR = R_of(best)
    n0 = best.size
    for fac in levels:
        if time.process_time() >= deadline - 0.5:
            break
        n = min(1000000, n0 * fac)
        if n <= best.size:
            continue
        x_old = np.linspace(0.0, 1.0, best.size)
        x_new = np.linspace(0.0, 1.0, n)
        h_up = np.interp(x_new, x_old, best)
        h_up = _rescale(np.clip(h_up, 0, None))
        r_up = R_of(h_up)
        if r_up > bestR:
            best = h_up; bestR = r_up
        tlim = min(deadline - 0.3, time.process_time() + 4.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR:
            best = hc; bestR = rc
    return best, bestR


# ---- block-level helpers ----

def _blocks_from(h, K):
    N = h.size
    if N % K != 0:
        # resample by averaging into K bins
        edges = np.linspace(0, N, K + 1).astype(int)
        a = np.array([h[edges[i]:edges[i + 1]].mean()
                      if edges[i + 1] > edges[i] else 0.0
                      for i in range(K)])
        return a
    m = N // K
    return h.reshape(K, m).mean(axis=1)


def _rasterize(a, N):
    K = a.size
    m = N // K
    out = np.repeat(a, m)
    if out.size < N:
        out = np.concatenate([out, np.full(N - out.size, a[-1])])
    return out[:N]


def _blk_R(a):
    return R_of(np.asarray(a, dtype=float))


def _blk_soft_lbfgs(a0, deadline, beta, maxiter=300):
    return _lbfgs_custom(a0, lambda a: _fun_grad_soft(a, beta),
                         deadline, maxiter=maxiter)


def _blk_tie_lbfgs(a0, deadline, maxiter=300):
    return _lbfgs_custom(a0, _fun_grad_tie, deadline, maxiter=maxiter)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    # Phase 1: polish the given start
    while time.process_time() < deadline - 1.0:
        tlim = min(deadline - 0.5, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("polish R=%.12f" % bestR)
        else:
            break

    # ---- Experiment: block-level multi-start at K=64 (and 128) ----
    alt_best = best.copy()
    altR = bestR

    # Extract K=32 block heights from current best
    a32 = _blocks_from(best, 32)
    a32 = _rescale(a32)
    R32 = _blk_R(a32)
    print("Rblk K=32 = %.12f" % R32)

    rng = np.random.default_rng(12345)

    def _split(a, K):
        """Mass-preserving split of a into K blocks (K multiple of a.size)."""
        k0 = a.size
        fac = K // k0
        out = np.empty(K)
        for i in range(k0):
            # random lognormal split ratios
            r = rng.lognormal(0.0, 0.5, fac)
            r = r / r.sum()
            out[i * fac:(i + 1) * fac] = a[i] * r * fac
        return out

    def _run_K(K, time_share):
        nonlocal alt_best, altR
        if time.process_time() >= deadline - 2.0:
            return
        t_end = min(deadline - 1.0, time.process_time() + time_share)
        inits = []
        # (i) 20 splits of a32
        for _ in range(20):
            inits.append(_split(a32, K))
        # (ii) 60 random lognormal
        for sigma in (0.5, 1.5, 3.0):
            for _ in range(20):
                v = rng.lognormal(0.0, sigma, K)
                inits.append(v)
        # (iii) 40 sparse
        for _ in range(40):
            v = rng.lognormal(0.0, 1.5, K)
            frac = rng.uniform(0.1, 0.3)
            nz = int(round(K * frac))
            idx = rng.choice(K, nz, replace=False)
            mask = np.zeros(K, dtype=bool)
            mask[idx] = True
            v[~mask] = 0.0
            inits.append(v)

        scored = []
        for v in inits:
            if time.process_time() >= t_end:
                break
            v = _rescale(np.clip(v, 0, None))
            if v.sum() <= 0:
                continue
            M = _knots(v).max()
            beta = 50.0 / M if M > 0 else 1.0
            sub_end = min(t_end, time.process_time() + 0.4)
            vc = _blk_soft_lbfgs(v, sub_end, beta, maxiter=300)
            rc = _blk_R(vc)
            scored.append((rc, vc))
        if not scored:
            return
        scored.sort(key=lambda t: -t[0])
        top = scored[:5]
        bestK = top[0][1]
        bestKR = top[0][0]
        # switch to exact tie objective
        for _, v in top:
            if time.process_time() >= t_end:
                break
            sub_end = min(t_end, time.process_time() + 0.6)
            vc = _blk_tie_lbfgs(v, sub_end, maxiter=300)
            rc = _blk_R(vc)
            if rc > bestKR:
                bestK = vc; bestKR = rc
        print("Rblk K=%d = %.12f" % (K, bestKR))
        # rasterize and polish at full resolution
        if time.process_time() < deadline - 1.5:
            N = best.size
            m = N // K
            if m >= 1:
                h_r = _rescale(_rasterize(bestK, N))
                rr = R_of(h_r)
                if rr > bestR:
                    # polish
                    sub_end = min(deadline - 0.5, time.process_time() + 4.0)
                    hc = _full_lbfgs(h_r, sub_end, maxiter=200)
                    rc2 = R_of(hc)
                    if rc2 > rr:
                        h_r = hc; rr = rc2
                    if rr > bestR:
                        best = h_r; bestR = rr
                        print("raster K=%d R=%.12f (N=%d)" % (K, bestR, best.size))
                if rr > altR:
                    alt_best = h_r.copy(); altR = rr

    # allocate time: K=64 gets more, K=128 less
    remain = deadline - time.process_time() - 2.0
    if remain > 3.0:
        _run_K(64, remain * 0.65)
    if time.process_time() < deadline - 2.0:
        _run_K(128, max(0.0, (deadline - time.process_time() - 1.5) * 0.8))

    # Phase 2b: refinement cascade
    if time.process_time() < deadline - 2.0:
        hc, rc = _refine(best, deadline - 0.5)
        if rc > bestR:
            best = hc; bestR = rc
            print("refined R=%.12f (N=%d)" % (bestR, best.size))

    # Phase 3: continue polishing
    while time.process_time() < deadline - 0.5:
        tlim = min(deadline - 0.2, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("polish R=%.12f" % bestR)
        else:
            break

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    alt = alt_best if altR > 0 else best

    print("final R=%.12f (start %.12f, N=%d, altR=%.12f)"
          % (bestR, startR, best.size, altR))

    return {"best": best, "alternative": alt}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_smoothmax(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    z = beta * (Lf - M)
    ez = np.exp(z)
    Z = ez.sum()
    lse = M + np.log(Z) / beta
    w = ez / Z
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + lse
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_smoothmax(h0, deadline, beta, maxiter=200):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = _fun_grad_smoothmax(hh, beta)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18,
                                'maxcor': 25})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _coarsen(h, c):
    n = h.size
    m = (n + c - 1) // c
    pad = m * c - n
    if pad > 0:
        h = np.concatenate([h, np.zeros(pad)])
    return h.reshape(m, c).mean(axis=1)


def _upsample_lin(c, target_sz):
    x = np.arange(c.size)
    xn = np.arange(target_sz) * (c.size - 1) / max(1, target_sz - 1)
    return np.interp(xn, x, c)


def _anneal(h, deadline, betas, maxiter=80, frac=0.55):
    best = h
    bestR = R_of(best)
    for beta in betas:
        if time.process_time() > deadline - 0.3:
            break
        rem = deadline - time.process_time()
        rdl = min(deadline - 0.2, time.process_time() + max(0.5, rem * frac))
        h_new = _lbfgs_smoothmax(best, rdl, beta, maxiter=maxiter)
        r_new = R_of(h_new)
        if r_new > bestR:
            best = h_new
            bestR = r_new
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    start_best = best.copy()
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    N = best.size

    # --- Phase 1: aggressive coarsening + anneal (smooth large-scale structure) ---
    # The current best is already finely optimized; escape local basin by
    # re-solving at much coarser resolution where smoothmax is easier.
    t_phase1 = t0 + (deadline - t0) * 0.30
    for cf in [max(1, N // 2000), max(1, N // 600), max(1, N // 200)]:
        if time.process_time() > t_phase1 - 0.5:
            break
        c = _rescale(_coarsen(best, cf))
        cR = R_of(c)
        c = _anneal(c, t_phase1, [20.0, 100.0, 500.0, 2500.0], maxiter=120)
        # grow back toward N in steps
        while c.size < N and time.process_time() < t_phase1 - 0.5:
            target = min(N, c.size * 2)
            cand = _rescale(_upsample_lin(c, target))
            cand = _anneal(cand, t_phase1, [100.0, 500.0, 2500.0], maxiter=80)
            if R_of(cand) >= R_of(c) - 1e-9:
                c = cand
            else:
                break
        if c.size < N:
            c = _rescale(_upsample_lin(c, N))
        r_c = R_of(c)
        if r_c > bestR:
            best = c; bestR = r_c
            print("phase1 improve R=%.12f" % bestR)

    # --- Phase 2: fine full-resolution anneal from best ---
    if time.process_time() < deadline - 1.0:
        best = _anneal(best, deadline - 0.6,
                       [200.0, 1000.0, 5000.0, 25000.0], maxiter=120)
        bestR = R_of(best)
        print("phase2 R=%.12f" % bestR)

    # --- Phase 3: perturbation + re-anneal with adaptive scale ---
    rng = np.random.RandomState(1234567)
    pert_scale = 0.002
    n_fail = 0
    while time.process_time() < deadline - 1.2:
        rem = deadline - time.process_time()
        noise = rng.standard_normal(best.size) * pert_scale
        h_pert = _rescale(np.clip(best * np.exp(noise), 0, None))
        rdl = min(deadline - 0.4, time.process_time() + max(1.5, rem * 0.6))
        h_cand = h_pert
        for beta in [100.0, 1000.0, 10000.0]:
            if time.process_time() > rdl - 0.2:
                break
            h_cand = _lbfgs_smoothmax(h_cand, rdl, beta, maxiter=60)
        r_cand = R_of(h_cand)
        if r_cand > bestR + 1e-13:
            best = h_cand; bestR = r_cand
            n_fail = 0
            pert_scale = max(5e-4, pert_scale * 0.75)
            print("pert improve R=%.12f" % bestR)
        else:
            n_fail += 1
            if n_fail >= 3:
                pert_scale = min(0.03, pert_scale * 1.7)
                n_fail = 0

    # --- Phase 4: final high-beta polish ---
    if time.process_time() < deadline - 0.4:
        rdl = deadline - 0.15
        h_fin = _lbfgs_smoothmax(best, rdl, beta=5e4, maxiter=150)
        rf = R_of(h_fin)
        if rf > bestR:
            best = h_fin; bestR = rf

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    if bestR < startR - 1e-13:
        return {"best": start_best, "alternative": best}
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def _R_of(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)) or np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    m = L.max()
    if m <= 0:
        return -1.0
    return num / (s * s * m)


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _prolongate_mass(h, N):
    n = h.size
    if n == N:
        return h.copy()
    c = np.concatenate([[0.0], np.cumsum(h)])
    x_old = np.arange(n + 1) / n
    x_new = np.arange(N + 1) / N
    cm = np.interp(x_new, x_old, c)
    out = np.diff(cm) * (N / n)
    return np.maximum(out, 0.0)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    L = Lf[1:-1]
    m = L.max()
    if m <= 0:
        return 1e18, np.zeros(h.size)
    w = np.exp(beta * (L - m))
    W = w.sum()
    sm = m + np.log(W) / beta
    dsm = np.zeros_like(Lf)
    dsm[1:-1] = w / W
    gLf = -dq / num + dsm / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


class _TO(Exception):
    pass


def _lbfgs(h0, fun_grad, deadline, maxiter=200, idx=None):
    h = np.clip(np.asarray(h0, dtype=float), 0, None)
    if h.sum() <= 0:
        return h0
    if idx is None:
        idx = np.flatnonzero(h > 0)
    if idx.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        if time.process_time() > deadline - 0.3:
            raise _TO()
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[idx] * hh[idx]

    def cb(xk):
        if time.process_time() > deadline - 0.3:
            raise _TO()

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (_TO, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _peak_window_polish(h, deadline, frac=0.15, extra=8, maxiter=120):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    half = max(2, int(frac * n))
    lo = max(0, int(c) - half)
    hi = min(n, int(c) + half + extra)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    return _lbfgs(h, _fun_grad_tie, deadline, maxiter=maxiter, idx=idx)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        if h.size == 0 or not np.all(np.isfinite(h)) or h.sum() <= 0:
            h = np.ones(64)
    else:
        h = np.ones(64)
    h = _rescale(np.maximum(h, 0))

    best_h = h.copy()
    best_R = _R_of(h)
    print("start R=%.6f N=%d" % (best_R, h.size))

    # Grow resolution and round-trip through prolongation + polish.
    sizes = [s for s in (8192, 16384, 32768) if s > h.size]
    if h.size > 8192:
        sizes = []
    cur_h = h.copy()
    cur_R = best_R

    for N in sizes:
        if time.process_time() > deadline - 8.0:
            break
        hp = _prolongate_mass(cur_h, N)
        hp = _rescale(hp)
        Rp = _R_of(hp)
        print("prolongate N=%d R=%.6f" % (N, Rp))
        if Rp > cur_R:
            cur_h, cur_R = hp, Rp
        # quick exact polish at new resolution
        h2 = _lbfgs(cur_h, _fun_grad_tie, deadline, maxiter=120)
        R2 = _R_of(h2)
        if R2 > cur_R:
            cur_h, cur_R = h2, R2
        if cur_R > best_R:
            best_R, best_h = cur_R, cur_h.copy()

    # Homotopy of smoothing betas on the exact objective, then exact polish.
    for beta in (64, 256, 1024, 4096):
        if time.process_time() > deadline - 5.0:
            break
        h2 = _lbfgs(cur_h, lambda hh: _fun_grad_sm(hh, beta), deadline, maxiter=150)
        R2 = _R_of(h2)
        if R2 > cur_R:
            cur_h, cur_R = h2, R2
        h3 = _lbfgs(cur_h, _fun_grad_tie, deadline, maxiter=120)
        R3 = _R_of(h3)
        if R3 > cur_R:
            cur_h, cur_R = h3, R3
        if cur_R > best_R:
            best_R, best_h = cur_R, cur_h.copy()
        print("beta=%d R=%.6f best=%.6f" % (beta, cur_R, best_R))

    # Alternating peak-window polish + full polish to the deadline.
    fracs = (0.30, 0.15, 0.07, 0.03)
    ai = 0
    while time.process_time() < deadline - 3.0:
        frac = fracs[ai % len(fracs)]
        ai += 1
        h2 = _peak_window_polish(cur_h, deadline, frac=frac, extra=8, maxiter=150)
        R2 = _R_of(h2)
        if R2 > cur_R:
            cur_h, cur_R = h2, R2
        if time.process_time() > deadline - 3.0:
            break
        h3 = _lbfgs(cur_h, _fun_grad_tie, deadline, maxiter=100)
        R3 = _R_of(h3)
        if R3 > cur_R:
            cur_h, cur_R = h3, R3
        if cur_R > best_R:
            best_R, best_h = cur_R, cur_h.copy()
        print("  polish frac=%.2f R=%.6f best=%.6f" % (frac, cur_R, best_R))

    print("final R=%.6f N=%d" % (best_R, best_h.size))

    if start is not None:
        s = np.asarray(start, dtype=float)
        sR = _R_of(s)
        if sR >= best_R:
            return {"best": s, "alternative": best_h}
    return {"best": best_h, "alternative": best_h}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _prolongate_mass(h, N):
    n = h.size
    if n == N:
        return h.copy()
    c = np.concatenate([[0.0], np.cumsum(h)])
    x_old = np.arange(n + 1) / n
    x_new = np.arange(N + 1) / N
    cm = np.interp(x_new, x_old, c)
    out = np.diff(cm) * (N / n)
    return np.maximum(out, 0.0)


def _peak_window(h, frac, pad=0.05):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish_peak(h, frac, deadline, maxiter=300):
    h = np.asarray(h, dtype=float)
    if h.size < 8:
        return h
    free = _peak_window(h, frac)
    return _lbfgs_block(h, free, maxiter, deadline, beta=0.0)


def _resample_upsample(h, N):
    """Upsample by linear interpolation to N (keeps shape, adds resolution)."""
    n = h.size
    if n >= N:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, n)
    x_new = np.linspace(0.0, 1.0, N)
    out = np.interp(x_new, x_old, h)
    return _rescale(np.clip(out, 0.0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        if h.size == 0 or not np.all(np.isfinite(h)) or h.sum() <= 0:
            h = np.ones(64)
    else:
        h = np.ones(64)
    h = _rescale(np.maximum(h, 0))

    best_h = h.copy()
    best_R = R_of(h)
    start_R = best_R
    print("start R=%.6f N=%d" % (best_R, h.size))

    N_work = h.size
    if N_work < 2048:
        N_work = 8192
        h = _rescale(_prolongate_mass(h, N_work))
        R = R_of(h)
        if R > best_R:
            best_R, best_h = R, h.copy()
        print("prolonged N=%d R=%.6f" % (N_work, R))

    cur_h = h.copy()
    cur_R = R_of(cur_h)

    # Phase 1: logsumexp homotopy at current size.
    for beta in (16, 32, 64, 128, 256, 512):
        if time.process_time() > deadline - 3.0:
            break
        h2 = _lbfgs_log(cur_h, 400, deadline, beta=beta)
        R2 = R_of(h2)
        if R2 > cur_R:
            cur_h, cur_R = h2, R2
        if cur_R > best_R:
            best_R, best_h = cur_R, cur_h.copy()

    # Phase 2: exact-max polish.
    if time.process_time() < deadline - 2.0:
        h2 = _lbfgs_log(cur_h, 500, deadline, beta=0.0)
        R2 = R_of(h2)
        if R2 > cur_R:
            cur_h, cur_R = h2, R2
        if cur_R > best_R:
            best_R, best_h = cur_R, cur_h.copy()

    # Phase 3: peak-window polish.
    for frac in (0.30, 0.15, 0.08, 0.04):
        if time.process_time() > deadline - 2.0:
            break
        h2 = _polish_peak(cur_h, frac, deadline, maxiter=250)
        R2 = R_of(h2)
        if R2 > cur_R:
            cur_h, cur_R = h2, R2
        if cur_R > best_R:
            best_R, best_h = cur_R, cur_h.copy()

    print("phase3 R=%.6f N=%d" % (best_R, best_h.size))

    # Phase 4: alternate global and peak-window polish until deadline.
    betas = (1024, 512, 256, 128)
    ai = 0
    while time.process_time() < deadline - 1.5:
        beta = betas[ai % len(betas)]
        ai += 1
        h2 = _lbfgs_log(cur_h, 200, deadline, beta=beta)
        R2 = R_of(h2)
        if R2 > cur_R:
            cur_h, cur_R = h2, R2
        if time.process_time() > deadline - 1.5:
            break
        frac = (0.05, 0.10, 0.20)[ai % 3]
        h2 = _polish_peak(cur_h, frac, deadline, maxiter=200)
        R2 = R_of(h2)
        if R2 > cur_R:
            cur_h, cur_R = h2, R2
        if cur_R > best_R:
            best_R, best_h = cur_R, cur_h.copy()

    print("final R=%.6f N=%d" % (best_R, best_h.size))

    # NEW: if the run didn't beat start, try a resolution-richer alternative.
    # Upsample the current best and re-optimise a bit; this is a genuinely
    # different construction (new idea) to offer as the alternative.
    alt_h = best_h.copy()
    if best_R <= start_R + 1e-9 and best_h.size < 40000:
        if time.process_time() < deadline - 0.5:
            N_up = min(40000, best_h.size * 4)
            hu = _resample_upsample(best_h, N_up)
            Ru = R_of(hu)
            if Ru > best_R:
                best_R = Ru
                alt_h = hu.copy()
            # Brief polish of the upsampled version.
            hu2 = _lbfgs_log(hu, 120, deadline, beta=256)
            Ru2 = R_of(hu2)
            if Ru2 > best_R:
                best_R = Ru2
                alt_h = hu2.copy()
            print("upsample alt R=%.6f N=%d" % (best_R, alt_h.size))

    if start is not None:
        s = np.asarray(start, dtype=float)
        sR = R_of(s)
        if sR >= best_R:
            return {"best": s, "alternative": alt_h}
    return {"best": best_h, "alternative": alt_h}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 1e-30, None)
    x0 = np.log(h)

    def f(x):
        hh = np.exp(x)
        val, g = _fun_grad_tie(hh)
        return val, g * hh

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(res.x))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_repeat(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-12, atol=1e-15):
            hr = np.repeat(c, p)
            if abs(R_of(hr) - R_of(h)) <= 1e-12:
                return p, c
    return 1, h


def _interp_lift(c):
    n = c.size
    c2 = np.empty(2 * n)
    c2[0::2] = c
    c2[1:-1:2] = 0.5 * (c[:-1] + c[1:])
    c2[-1] = c[-1]
    return c2


def _coarse(c_in, m):
    n = c_in.size
    if m == n:
        return c_in.copy()
    x = np.linspace(0.0, n, m, endpoint=False) + 0.5 * (n / m)
    xi = np.arange(n, dtype=float) + 0.5
    return np.interp(x, xi, c_in)


def _prolong(c_coarse, m_out):
    m = c_coarse.size
    if m_out == m:
        return c_coarse.copy()
    x = np.linspace(0.0, m, m_out, endpoint=False) + 0.5 * (m_out / m)
    xi = np.arange(m, dtype=float) + 0.5
    return np.interp(x, xi, c_coarse)


def _polish_c(c, p, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return c, R_of(np.repeat(c, p))
    h = _rescale(np.repeat(c, p))
    h2 = _lbfgs_block(h, np.arange(h.size), maxiter, deadline)
    c2 = h2.reshape(-1, p).mean(axis=1)
    hr = np.repeat(c2, p)
    return c2, R_of(hr)


def _vcycle(best, bestR, p, c, deadline, levels):
    n_c = c.size
    coarse_list = [(n_c, c.copy())]
    cur = c
    for m in levels[1:]:
        cur = _coarse(cur, m)
        coarse_list.append((m, cur.copy()))
    m, cc = coarse_list[-1]
    cc, r = _polish_c(cc, p, 80, min(deadline, time.process_time() + 3.0))
    coarse_list[-1] = (m, cc)
    if r > bestR + 1e-15:
        best = _rescale(np.repeat(cc, p)); bestR = r
    for i in range(len(coarse_list) - 2, -1, -1):
        m_out, _ = coarse_list[i]
        cc = _prolong(cc, m_out)
        cc, r = _polish_c(cc, p, 100,
                          min(deadline, time.process_time() + 4.0))
        coarse_list[i] = (m_out, cc)
        if r > bestR + 1e-15:
            best = _rescale(np.repeat(cc, p)); bestR = r
    return best, bestR, cc


def _block_R(w, c, p):
    h = np.repeat(c, p) * np.repeat(w, c.size)
    return R_of(h)


def _opt_block_w(c, p, w0, deadline, maxiter=200):
    if time.process_time() >= deadline - 0.3:
        return w0, _block_R(w0, c, p)
    n_c = c.size
    hbase = np.repeat(c, p)
    blk = np.repeat(np.arange(p), n_c).astype(int)

    def f(x):
        w = np.exp(x)
        h = hbase * np.repeat(w, n_c)
        s = h.sum()
        if s <= 0:
            return 1e18, np.zeros(p)
        num, dq, Lf = _num_and_dq(h)
        mx = Lf.max()
        gLf = -dq / num
        idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
        gLf[idx] += (1.0 / idx.size) / mx
        gh = _backprop(gLf, h) + 2.0 / s
        gw = np.bincount(blk, weights=gh * h, minlength=p)
        val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
        return val, gw

    x0 = np.log(np.clip(w0, 1e-12, None))
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return w0, _block_R(w0, c, p)
    if res is None or not np.all(np.isfinite(res.x)):
        return w0, _block_R(w0, c, p)
    w = np.exp(res.x)
    return w, _block_R(w, c, p)


def _smooth_penalty_polish(h, deadline, beta, maxiter=400):
    if time.process_time() >= deadline - 0.3:
        return h
    h0 = _rescale(h)
    h1 = _lbfgs_block(h0, np.arange(h0.size), maxiter,
                      min(deadline, time.process_time() + 6.0), beta=beta)
    r0 = R_of(h0); r1 = R_of(h1)
    return h1 if r1 > r0 else h0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    p, c = _detect_repeat(best)
    print("repeat p=%d n_c=%d" % (p, c.size))

    # ---- Phase B: interpolating lift ladder ----
    b_end = t0 + (deadline - t0) * 0.35 + t0
    cur = c.copy()
    curR = R_of(np.repeat(cur, p)) if p > 1 else R_of(cur)
    for step in range(6):
        if time.process_time() >= b_end - 1.0:
            break
        if cur.size * 2 > 400000:
            break
        lifted = _interp_lift(cur)
        lifted = _lbfgs_log(lifted, 250, min(b_end - 0.5,
                                             time.process_time() + 8.0))
        rl = R_of(lifted)
        win = _peak_window(lifted, pad_frac=0.03, extra=64)
        polished = _lbfgs_block(lifted, win, 250,
                                min(b_end - 0.3,
                                    time.process_time() + 3.0))
        rp = R_of(polished)
        if rp > rl:
            lifted, rl = polished, rp
        print("lift step=%d n=%d R=%.9f (cur %.9f)" % (step, lifted.size, rl, curR))
        if rl > curR + 1e-15:
            cur, curR = lifted, rl
        else:
            break

    # ---- Phase C: lift back to full N and accept if better ----
    n_target = best.size
    if cur.size != n_target:
        if n_target % cur.size == 0:
            full = np.repeat(cur, n_target // cur.size)
        else:
            full = np.interp(np.linspace(0, cur.size - 1, n_target),
                             np.arange(cur.size), cur)
    else:
        full = cur
    full = _rescale(full)
    rfull = R_of(full)
    if rfull > bestR + 1e-15:
        best, bestR = full.copy(), rfull
        print("lift ACCEPT R=%.9f" % bestR)

    # ---- Phase S: beta-smoothed escape + peak polish ----
    s_end = t0 + (deadline - t0) * 0.58 + t0
    if time.process_time() < s_end - 1.0:
        for beta in (30.0, 100.0, 300.0, 1000.0, 3000.0):
            if time.process_time() >= s_end - 0.8:
                break
            hb = _smooth_penalty_polish(best, min(s_end - 0.5,
                                                 time.process_time() + 5.0),
                                        beta)
            rb = R_of(hb)
            if rb > bestR + 1e-15:
                best, bestR = hb.copy(), rb
            win = _peak_window(hb, pad_frac=0.05, extra=96)
            hp = _lbfgs_block(hb, win, 250,
                              min(s_end - 0.3,
                                  time.process_time() + 3.0))
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp.copy(), rp
        print("smooth+peak R=%.9f" % bestR)

    # ---- Phase W: block-weight optimization on the repeat structure ----
    w_end = t0 + (deadline - t0) * 0.70 + t0
    if p > 1 and time.process_time() < w_end - 1.0:
        _, c_now = _detect_repeat(best)
        if c_now.size * p == best.size:
            w0 = np.ones(p)
            w, rw = _opt_block_w(c_now, p, w0, min(w_end - 0.5,
                                                  time.process_time() + 6.0))
            if rw > bestR + 1e-15:
                hnew = _rescale(np.repeat(c_now, p) * np.repeat(w, c_now.size))
                best, bestR = hnew, rw
                print("blockW ACCEPT R=%.9f" % bestR)

    # ---- Phase E: final peak + beta polish, plus v-cycle on reduced vector ----
    c_end = deadline
    beta_cycle = (300.0, 1000.0, 3000.0)
    it = 0
    while time.process_time() < c_end - 1.0:
        it += 1
        pad = (0.06, 0.03, 0.015, 0.008)[it % 4]
        win = _peak_window(best, pad_frac=pad, extra=96)
        ht = _lbfgs_block(best, win, 300,
                          min(c_end - 0.5, time.process_time() + 3.0))
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        if time.process_time() < c_end - 1.0:
            beta = beta_cycle[it % len(beta_cycle)]
            hb = _smooth_penalty_polish(best, min(c_end - 0.5,
                                                 time.process_time() + 4.0),
                                        beta)
            rb = R_of(hb)
            if rb > bestR + 1e-15:
                best, bestR = hb.copy(), rb
        # occasionally run a full-vector log-lbfgs to escape local minima
        if it % 3 == 0 and time.process_time() < c_end - 1.5:
            hl = _lbfgs_log(best, 120, min(c_end - 0.5,
                                           time.process_time() + 4.0))
            rl = R_of(hl)
            if rl > bestR + 1e-15:
                best, bestR = hl.copy(), rl
        print("E it=%d pad=%.3f R=%.9f" % (it, pad, bestR))

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

