        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _smooth(h, k):
    if k <= 1:
        return h
    ker = np.ones(k) / k
    hs = np.convolve(h, ker, mode='same')
    return np.clip(hs, 0.0, None)


def _perturb(h, rng, scale):
    h2 = h.copy()
    nz = np.flatnonzero(h2 > 0)
    if nz.size == 0:
        return h2
    factors = np.exp(rng.normal(0.0, scale, nz.size))
    h2[nz] *= factors
    return h2


def _peak_window(h, frac, pad):
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    half = max(4, int(frac * n)) + pad
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _smoothstep_seed(N):
    x = np.linspace(0, 1, N)
    return (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)


def _refine_and_accept(cur, cur_r, best, best_r, deadline):
    """Upsample to a finer grid, polish, accept if coarsened/mapped-back improves."""
    if cur.size >= 300000 or time.process_time() >= deadline - 25.0:
        return cur, cur_r, best, best_r, None
    N_up = min(cur.size * 2, 400000)
    up = _rescale(_prolongate(cur, N_up))
    up = _lbfgs_log(up, maxiter=500, deadline=deadline - 20.0)
    for frac, pad in ((0.05, 4), (0.15, 10)):
        if time.process_time() >= deadline - 18.0:
            break
        win = _peak_window(up, frac, pad)
        cand = _lbfgs_block(up, win, maxiter=400, deadline=deadline - 18.0)
        if R_of(cand) > R_of(up):
            up = cand
    up_r = R_of(up)
    alt = None
    back = _rescale(_coarsen(up, cur.size))
    back_r = R_of(back)
    if back_r > best_r:
        best, best_r = back.copy(), back_r
        cur, cur_r = back.copy(), back_r
    elif up_r > best_r:
        best, best_r = up.copy(), up_r
        cur, cur_r = up.copy(), up_r
    else:
        alt = up.copy()
    return cur, cur_r, best, best_r, alt


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0
    rng = np.random.default_rng(20240607)

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = _smoothstep_seed(512)
        best_r = R_of(best)

    cur = _rescale(best.copy())
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r

    print("start R = %.6f, N = %d" % (cur_r, cur.size))

    alt_returned = None

    # ---- Primary idea: refine on a finer grid; accept if mapped-back improves. ----
    cur, cur_r, best, best_r, alt = _refine_and_accept(
        cur, cur_r, best, best_r, deadline)
    if alt is not None:
        alt_returned = alt

    # ---- Region-restricted polish of the current best on its own grid. ----
    if time.process_time() < deadline - 8.0:
        for frac, pad in ((0.02, 2), (0.05, 4), (0.12, 8)):
            if time.process_time() >= deadline - 8.0:
                break
            win = _peak_window(cur, frac, pad)
            cand = _lbfgs_block(cur, win, maxiter=600, deadline=deadline - 8.0)
            rc = R_of(cand)
            if rc > cur_r:
                cur, cur_r = cand, rc
                if cur_r > best_r:
                    best, best_r = cur.copy(), cur_r

    # ---- Smoothing continuation ----
    for beta in (4, 16, 64):
        if time.process_time() >= deadline - 4.0:
            break
        c2 = _lbfgs_log(cur, maxiter=200, deadline=deadline, beta=beta)
        r2 = R_of(c2)
        if r2 > cur_r:
            cur, cur_r = c2, r2
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        print("  beta=%d R=%.6f" % (beta, cur_r))

    # ---- Main loop: alternate full and windowed polish, restart on stall. ----
    restart_tries = 0
    no_improve = 0
    last_r = cur_r
    refine_round = 0
    while time.process_time() < deadline - 1.0:
        cand = _lbfgs_log(cur, maxiter=1200, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 1.0:
            break

        for frac, pad in ((0.05, 4), (0.15, 10), (0.30, 20)):
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(cur, frac, pad)
            cand = _lbfgs_block(cur, win, maxiter=500, deadline=deadline)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

        # Periodically attempt another refine step (grid doubling).
        if (cur_r <= last_r + 1e-9 and no_improve >= 1
                and refine_round < 2
                and time.process_time() < deadline - 20.0):
            refine_round += 1
            cur, cur_r, best, best_r, alt = _refine_and_accept(
                cur, cur_r, best, best_r, deadline)
            if alt is not None and alt_returned is None:
                alt_returned = alt
            if cur_r > last_r + 1e-9:
                no_improve = 0
                last_r = cur_r
                continue

        if cur_r <= last_r + 1e-9:
            no_improve += 1
            if no_improve >= 2 and time.process_time() < deadline - 3.0:
                k = 3 if restart_tries % 2 == 0 else 5
                seed = _rescale(_smooth(cur, k))
                seed = _lbfgs_log(seed, maxiter=800, deadline=deadline)
                rs = R_of(seed)
                if rs > cur_r:
                    cur, cur_r = seed, rs
                    if cur_r > best_r:
                        best, best_r = cur.copy(), cur_r
                    no_improve = 0
                else:
                    scale = 0.02 * (1 + restart_tries)
                    perturbed = _perturb(best, rng, min(scale, 0.2))
                    cand_p = _lbfgs_log(_rescale(perturbed), maxiter=1000,
                                        deadline=deadline)
                    rp = R_of(cand_p)
                    if rp > cur_r:
                        cur, cur_r = cand_p, rp
                        if cur_r > best_r:
                            best, best_r = cur.copy(), cur_r
                        no_improve = 0
                    else:
                        cur = best.copy(); cur_r = best_r
                restart_tries += 1
        else:
            no_improve = 0
        last_r = cur_r

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None:
        out = {"best": best}
        if alt_returned is not None and alt_returned.size != best.size:
            out["alternative"] = alt_returned
        else:
            out["alternative"] = start_arr
        return out
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, pos, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.asarray(pos, dtype=int)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _log_polish(h0, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0, 0.0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0, 0.0
    h2 = _lbfgs_block(h, pos, maxiter, deadline)
    return h2, 0.0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    start_best = best.copy()
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    rng = np.random.RandomState(999)
    n = best.size

    # Detect a common block structure so we can work at block resolution.
    BLK = 1
    for cand in (32, 16, 8, 4, 2):
        if n % cand == 0:
            nb = n // cand
            hb = best.reshape(nb, cand)
            bm = hb.mean(axis=1, keepdims=True)
            if np.allclose(hb, bm, atol=1e-9 * max(best.max(), 1e-30)):
                BLK = cand
                break

    # Main strategy: coordinate-style block sweeps with L-BFGS on overlapping windows.
    # Overlapping windows let the optimizer move mass across block boundaries
    # (the pure block decomposition from the earlier program locked these in).
    if BLK > 1:
        nb = n // BLK
        c = best.reshape(nb, BLK).mean(axis=1)
        best = _rescale(np.repeat(c, BLK))
        bestR = R_of(best)
        print("block-constant: nb=%d BLK=%d" % (nb, BLK))

    # Sweep over windows of the block vector with L-BFGS polish on the full vector.
    win = max(4, min(64, n // 8 if n >= 8 else n))
    step = max(1, win // 2)
    it = 0
    accepted = 0
    trials = 0
    while time.process_time() < deadline - 1.0:
        it += 1
        # Alternate: full polish, then windowed sweeps
        if it % 3 == 0:
            tlim = min(deadline - 0.6, time.process_time() + 3.0)
            cand = _log_polish(best, tlim, maxiter=200)[0]
            r = R_of(cand)
            if r > bestR + 1e-15:
                best = cand; bestR = r; accepted += 1
        # Window sweep
        starts = list(range(0, n - win + 1, step))
        if not starts or starts[-1] + win < n:
            starts.append(max(0, n - win))
        rng.shuffle(starts)
        for s0 in starts:
            if time.process_time() >= deadline - 0.8:
                break
            idx = np.arange(s0, s0 + win)
            trials += 1
            tlim = min(deadline - 0.5, time.process_time() + 0.25)
            cand = _lbfgs_block(best, idx, 8, tlim)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best = cand; bestR = r; accepted += 1
        if time.process_time() >= deadline - 1.0:
            break

    print("window sweeps accepted %d / %d trials (win=%d)" % (accepted, trials, win))

    # Final full polish with remaining time
    if time.process_time() < deadline - 0.5:
        tlim = min(deadline - 0.3, time.process_time() + 4.0)
        pol = _log_polish(best, tlim, maxiter=300)[0]
        rp = R_of(pol)
        if rp > bestR + 1e-15:
            best = pol; bestR = rp

    if bestR < startR:
        best = start_best
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    if bestR > startR + 1e-15:
        return {"best": best, "alternative": best}
    return {"best": best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _fun_grad_al(h, S, lam, rho):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    idxmax = np.flatnonzero(Lf >= M * (1.0 - 1e-10))
    gLf[idxmax] += (1.0 / idxmax.size) / M
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M)
    if S.size > 0:
        Lj = Lf[S]
        r = Lj / M - 1.0
        val += np.sum(lam * r + 0.5 * rho * r * r)
        gLf[S] += (lam + rho * r) / M
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3, frac=0.125):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - int(frac * n))
    hi = min(n, int(c) + pad + int(frac * n))
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 200, 'maxfun': 400,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _upsample_mass(h, factor):
    h = np.asarray(h, dtype=float)
    n = h.size
    N = n * factor
    c = np.concatenate(([0.0], np.cumsum(h)))
    fine = np.arange(N + 1) / factor
    cnew = np.interp(fine, np.arange(n + 1), c)
    out = np.diff(cnew)
    zero_blocks = h <= 0
    if np.any(zero_blocks):
        for i in np.nonzero(zero_blocks)[0]:
            out[i * factor:(i + 1) * factor] = 0.0
    return np.maximum(out, 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard = t0 + budget_seconds - 2.0
    deadline = hard

    best = None
    bestR = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = s.copy()
            bestR = R_of(best)
    if best is None:
        best = np.ones(64)
        bestR = R_of(best)

    base = best.copy()
    baseR = bestR

    def time_left():
        return time.process_time() < deadline

    # Phase 1: refine current shape with sharp log-LBFGS + peak polish
    c = _full_lbfgs(best, deadline, maxiter=200)
    if R_of(c) > bestR:
        best = c; bestR = R_of(c)
    for _ in range(6):
        if not time_left():
            break
        c = _peak_window_polish(best, deadline, frac=0.05)
