        hu = np.clip(hu, 0, None)
        if hu.sum() <= 0:
            continue
        hu = hu / hu.sum() * best.sum()
        c = _full_lbfgs(hu, deadline, maxiter=150)
        if R_of(c) > bestR:
            best = c; bestR = R_of(c)
        for _ in range(3):
            if not time_left():
                break
            c = _peak_window_polish(best, deadline, frac=0.03)
            if R_of(c) > bestR:
                best = c; bestR = R_of(c)

    # Phase 3: CVaR polish to push up near-peak knots
    for alpha in (0.2, 0.1, 0.05):
        if not time_left():
            break
        fg = lambda hh, a=alpha: _fun_grad_cvar(hh, a)
        c = _lbfgs_custom(best, fg, deadline, maxiter=100)
        if R_of(c) > bestR:
            best = c; bestR = R_of(c)

    # Phase 4: alternate full + peak polish until time runs out
    while time_left():
        c = _full_lbfgs(best, deadline, maxiter=100)
        if R_of(c) > bestR:
            best = c; bestR = R_of(c)
        if not time_left():
            break
        c = _peak_window_polish(best, deadline, frac=0.04)
        if R_of(c) > bestR:
            best = c; bestR = R_of(c)

    if bestR <= baseR:
        return {"best": base, "alternative": best}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    u = np.clip(Lf / mx, 0.0, 1.0)
    up = u ** p
    S = up.sum()
    if S <= 0:
        return _fun_grad_tie(h)
    Pm = mx * S ** (1.0 / p)
    w = (u ** (p - 1)) / (S ** ((p - 1.0) / p))
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Pm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150, log=True):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    if log:
        pos = np.flatnonzero(h > 0)
        if pos.size == 0:
            return h0
        floor = max(1e-14 * h.max(), 1e-300)
        u0 = np.log(np.clip(h[pos], floor, None))

        def f(u):
            hh = h.copy()
            hh[pos] = np.exp(u)
            val, g = fun_grad(hh)
            return val, g[pos] * hh[pos]
    else:
        pos = np.arange(h.size)
        u0 = h[pos].copy()

        def f(u):
            hh = h.copy()
            hh[pos] = np.clip(u, 0.0, None)
            val, g = fun_grad(hh)
            return val, g[pos]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size if log else [(0.0, None)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    if log:
        h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    else:
        h2[pos] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.9999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx0, m0, near0))

    bestH = best.copy()
    bestRH = bestR

    # (1) Full log-param lbfgs with tie-averaged max, then p-norm continuation.
    sub = min(deadline - 2.0, time.process_time() + 8.0)
    h = _lbfgs_custom(bestH, _fun_grad_tie, sub, maxiter=200)
    r = R_of(h)
    if r > bestRH:
        bestH, bestRH = h.copy(), r
    print("  full tie R=%.7f" % bestRH)

    # (2) p-norm ladder, repeated
    it = 0
    ladder = (2, 4, 8, 16, 32, 64, 128, 256)
    while time.process_time() < deadline - 2.0:
        improved = False
        for p in ladder:
            if time.process_time() >= deadline - 1.5:
                break
            sub = min(deadline - 1.0, time.process_time() + 3.0)
            fg = (lambda hh, _p=p: _fun_grad_pnorm(hh, _p))
            h = _lbfgs_custom(bestH, fg, sub, maxiter=80)
            r = R_of(h)
            if r > bestRH + 1e-14:
                bestH, bestRH = h.copy(), r
                improved = True
        # Peak-local polish
        if time.process_time() < deadline - 1.0:
            lo, hi = _peak_region(bestH, tol=0.9995)
            span = hi - lo
            pad = max(128, int(span * 0.5))
            lo2 = max(0, lo - pad); hi2 = min(bestH.size - 1, hi + pad)
            if hi2 > lo2:
                sub = min(deadline - 0.5, time.process_time() + 2.0)
                mask = np.zeros(bestH.size, dtype=bool)
                mask[lo2:hi2 + 1] = True
                h = _lbfgs_custom(bestH, _fun_grad_tie, sub, maxiter=60, log=False)
                # only accept if improved (block polish via non-log full)
                r = R_of(h)
                if r > bestRH + 1e-14:
                    bestH, bestRH = h.copy(), r
                    improved = True
        print("  iter %d R=%.7f" % (it, bestRH))
        it += 1
        if not improved and time.process_time() > deadline - 3.0:
            break

    if bestRH > bestR + 1e-13:
        best, bestR = bestH.copy(), bestRH

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d, zeros %.1f%%) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestR, best.size, 100.0 * np.mean(best <= 0), mx, m, near))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = _fun_grad_tie if tie else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _smooth3(h, passes=1):
    h = h.copy()
    for _ in range(passes):
        hp = np.concatenate(([h[0]], h, [h[-1]]))
        h = 0.25 * hp[:-2] + 0.5 * hp[1:-1] + 0.25 * hp[2:]
    return h


def _coarsen(h, factor):
    n = h.size
    m = n // factor
    if m < 1:
        return h.copy()
    hh = h[:m * factor].reshape(m, factor)
    return hh.mean(axis=1)


def _lift(h, factor, n_target):
    hh = np.repeat(h, factor)
    if hh.size < n_target:
        hh = np.concatenate([hh, np.full(n_target - hh.size, hh[-1])])
    elif hh.size > n_target:
        hh = hh[:n_target]
    return hh


def _report(tag, h):
    Lf = _knots(h)
    mx = Lf.max()
    print("%s: R=%.9f max/mean=%.2f ties=%d"
          % (tag, R_of(h), h.max() / max(h.mean(), 1e-30),
             int(np.sum(Lf >= mx * (1 - 1e-10))) if mx > 0 else 0))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d, ties=%d)" % (bestR, best.size, _tie_count(best)))

    alt_best = best.copy()
    altR = bestR

    cur = best.copy()
    curR = bestR

    def consider(h_new, tag):
        nonlocal best, bestR, alt_best, altR, cur, curR
        r = R_of(h_new)
        _report(tag, h_new)
        if r > altR:
            altR = r; alt_best = h_new.copy()
        if r > bestR + 1e-15:
            best, bestR = h_new.copy(), r
        if r > curR + 1e-15:
            cur, curR = h_new.copy(), r
        return r

    N_full = cur.size
    full = np.arange(N_full)

    # ---- Stage A: multi-resolution descent on a coarsened version ----
    # Downsample, optimise the coarse problem fully, then lift back.
    for fac in (8, 4, 2):
        if time.process_time() >= deadline - 6.0:
            break
        if cur.size // fac < 32:
            continue
        hc = _coarsen(cur, fac)
        hc = _rescale(hc)
        cfull = np.arange(hc.size)
        for _ in range(2):
            if time.process_time() >= deadline - 5.0:
                break
            tlim = min(deadline - 4.5, time.process_time() + 3.0)
            hc2 = _lbfgs_block(hc, cfull, 200, tlim, tie=True)
            if R_of(hc2) > R_of(hc):
                hc = hc2
        hl = _lift(hc, fac, cur.size)
        hl = _rescale(hl)
        consider(hl, "coarse fac=%d lift" % fac)
        # then polish at full resolution
        if time.process_time() < deadline - 4.0:
            tlim = min(deadline - 3.5, time.process_time() + 3.0)
            cur = _lbfgs_block(cur, full, 200, tlim, tie=True)
            consider(cur, "  full polish after fac=%d" % fac)

    print("after multires: bestR=%.9f" % bestR)

    # ---- Stage B: smoothing perturbation restarts ----
    for sm_passes in (1, 2, 3):
        if time.process_time() >= deadline - 5.0:
            break
        hs = _smooth3(cur, passes=sm_passes)
        hs = _rescale(hs)
        tlim = min(deadline - 4.5, time.process_time() + 3.0)
        ht = _lbfgs_block(hs, full, 150, tlim, tie=True)
        consider(ht, "smooth passes=%d" % sm_passes)

    print("after smooth: bestR=%.9f" % bestR)

    # ---- Stage C: final tie polish loop until deadline ----
    while time.process_time() < deadline - 1.0:
        tlim = min(deadline - 0.5, time.process_time() + 3.0)
        ht = _lbfgs_block(cur, full, 200, tlim, tie=True)
        r = R_of(ht)
        _report("final tie", ht)
        if r > altR:
            altR = r; alt_best = ht.copy()
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        if r > curR + 1e-15:
            cur, curR = ht, r
        else:
            break

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

