    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_al(h, S, lam, rho):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    idxmax = np.flatnonzero(Lf >= M * (1.0 - 1e-10))
    gLf[idxmax] += (1.0 / idxmax.size) / M
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M)
    if S.size > 0:
        Lj = Lf[S]
        r = Lj / M - 1.0
        val += np.sum(lam * r + 0.5 * rho * r * r)
        gLf[S] += (lam + rho * r) / M
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, fun_grad=_fun_grad_tie):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    N = best.size
    full = np.arange(N)

    # ---- Phase 1: augmented-Lagrangian band shaping on the upper knots ----
    alt_best = None
    altR = -1.0
    al_best = best.copy()
    al_bestR = bestR
    reserve = 6.0
    for alpha, rho in ((0.20, 30.0), (0.35, 30.0), (0.50, 30.0)):
        if time.process_time() >= deadline - reserve:
            break
        Lf = _knots(best)
        M = Lf.max()
        # pick knots in top fraction (below the max) to push up toward max
        thr = M * (1.0 - alpha)
        S = np.flatnonzero((Lf < M * (1.0 - 1e-8)) & (Lf >= thr))
        if S.size == 0:
            continue
        lam = np.zeros(S.size)
        cur = best.copy()
        for it in range(3):
            if time.process_time() >= deadline - reserve:
                break
            tlim = min(deadline - reserve, time.process_time() + 4.0)
            fg = (lambda S=S, lam=lam, rho=rho: (lambda hh: _fun_grad_al(hh, S, lam, rho)))()
            cand = _lbfgs_block(cur, full, 80, tlim, fun_grad=fg)
            if cand is None:
                break
            r = R_of(cand)
            if r > al_bestR + 1e-15:
                al_best, al_bestR = cand.copy(), r
            if r > altR:
                altR, alt_best = r, cand.copy()
            cur = cand
            # update multipliers
            Lc = _knots(cur)
            Mc = Lc.max()
            lam = lam + rho * (Lc[S] / Mc - 1.0)
        print("AL alpha=%.2f R=%.12f (al_best %.12f)" % (alpha, R_of(cur), al_bestR))

    # ---- Phase 2: full-N tie polish from the best candidate ----
    cand = al_best if al_bestR > bestR else best
    if time.process_time() < deadline - 4.0:
        pol = _lbfgs_block(cand, full, 300,
                           min(deadline - 3.0, time.process_time() + 10.0))
        rp = R_of(pol)
        print("full tie polish R=%.12f" % rp)
        if rp > bestR + 1e-15:
            best, bestR = pol.copy(), rp
        if rp > altR:
            altR, alt_best = rp, pol.copy()

    # ---- Phase 3: peak-window tie polish ----
    for pad in (0.10, 0.06, 0.03):
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 300,
                          min(deadline - 0.3, time.process_time() + 3.0))
        r = R_of(ht)
        print("peak polish pad=%.2f R=%.12f" % (pad, r))
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        if r > altR:
            altR, alt_best = r, ht.copy()

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and altR <= startR + 1e-14:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_pos(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_tie(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_pos(_seed_zeros(best), 600, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64), (0.10, 64), (0.25, 128),
              (0.40, 256), (0.60, 512)]
    for frac, extra in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=200, deadline=deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_pos(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _perturb_peak(h, rng, scale):
    Lf = _knots(h)
    mx = Lf.max()
    idx = np.flatnonzero(Lf >= 0.98 * mx)
    if idx.size == 0:
        return h
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = max(1, hi - lo)
    pad = int(scale * span) + 8
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    x = np.arange(lo, hi + 1, dtype=float)
    B = np.zeros_like(x)
    for _ in range(4):
        k = rng.integers(1, 6)
        a = rng.normal(0.0, 0.35)
        phi = rng.uniform(0.0, 1.0)
        B += a * np.cos(2.0 * np.pi * (k * x / max(1, hi - lo) + phi))
    B = np.clip(B, -3.0, 3.0)
    out = h.copy()
    out[lo:hi + 1] = out[lo:hi + 1] * np.exp(B)
    out = np.clip(out, 0.0, None)
    if out.sum() <= 0:
        return h
    out *= h.sum() / out.sum()
    return _rescale(out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(1234567)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    if time.process_time() < deadline - 4.0:
        best, bestR = run_cycle(best, bestR, deadline - 4.0)
        print("cycle R=%.7f" % bestR)

    n_trials = 0
    n_accepted = 0
    while time.process_time() < deadline - 3.0:
        scale = rng.uniform(0.2, 1.5)
        h_try = _perturb_peak(best, rng, scale)
        r_pre = R_of(h_try)
        n_trials += 1
        if r_pre >= bestR - 5e-3:
            win = _peak_window(h_try, pad_frac=0.3, extra=192)
            h_p = _lbfgs_block(h_try, win, 120, deadline - 2.5)
            r_p = R_of(h_p)
            if r_p > bestR + 1e-13:
                best, bestR = h_p.copy(), r_p
                n_accepted += 1
                print("ACCEPT trial %d scale=%.2f pre=%.7f post=%.7f newR=%.7f"
                      % (n_trials, scale, r_pre, r_p, bestR))
        if n_trials % 15 == 0:
            print("  ... %d trials, %d accepted, R=%.7f"
                  % (n_trials, n_accepted, bestR))

    print("perturb phase: %d trials, %d accepted" % (n_trials, n_accepted))

    if time.process_time() < deadline - 1.0:
        best, bestR = run_cycle(best, bestR, deadline - 1.0)
        print("final cycle R=%.7f" % bestR)
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_pos(best, 400, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _local_sweep(h, deadline, passes=6):
    """Coordinate-wise multiplicative jitter search: try scaling each height
    (in blocks) up/down and keep improvements. Cheap and escapes L-BFGS stalls."""
    h = h.copy()
    bestR = R_of(h)
    n = h.size
    if n == 0:
        return h, bestR
    rng = np.random.RandomState(12345)
    factors = np.array([0.9, 0.95, 0.98, 1.02, 1.05, 1.1])
    blk = max(1, n // 200)
    for _ in range(passes):
        if time.process_time() > deadline:
            break
        improved = False
        order = rng.permutation((n + blk - 1) // blk)
        for bi in order:
            if time.process_time() > deadline:
                break
            lo = bi * blk
            hi = min(n, lo + blk)
            cur = h[lo:hi].copy()
            curR = bestR
            bestf = 1.0
            for f in factors:
                h[lo:hi] = cur * f
                r = R_of(h)
                if r > curR:
                    curR = r; bestf = f
            h[lo:hi] = cur * bestf
            if bestf != 1.0:
                bestR = curR
                improved = True
        if not improved:
            break
    return h, bestR


def _upsample(h, n):
    x_old = np.linspace(0.0, 1.0, h.size)
    x_new = np.linspace(0.0, 1.0, n)
    return _rescale(np.clip(np.interp(x_new, x_old, h), 0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    # Phase A: polish start
    while time.process_time() < deadline - 2.0:
        tlim = min(deadline - 1.0, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("polish R=%.12f" % bestR)
        else:
            break

    # Phase B: upsample cascade with polishing, then local sweeps
    alt_best = best.copy()
    altR = bestR
    n0 = best.size
    for n in (n0 * 2, n0 * 3, n0 * 4):
        if time.process_time() > deadline - 3.0:
            break
        n = min(1000000, int(n))
        if n <= best.size:
            continue
        h_up = _upsample(best, n)
        r_up = R_of(h_up)
        if r_up > bestR:
            best = h_up; bestR = r_up
            print("up R=%.12f (N=%d)" % (bestR, best.size))
        tlim = min(deadline - 2.0, time.process_time() + 5.0)
        hc = _full_lbfgs(best, tlim, maxiter=250)
        rc = R_of(hc)
        if rc > bestR:
            best = hc; bestR = rc
            print("polish R=%.12f (N=%d)" % (bestR, best.size))

    # Phase C: local coordinate sweeps to escape stalls
    if time.process_time() < deadline - 2.0:
        hc, rc = _local_sweep(best, deadline - 1.0, passes=10)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("sweep R=%.12f" % bestR)

    # Phase D: final polishing
    while time.process_time() < deadline - 0.5:
        tlim = min(deadline - 0.2, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("polish R=%.12f" % bestR)
        else:
            break

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    alt = alt_best if altR > 0 else best

    print("final R=%.12f (start %.12f, N=%d, altR=%.12f)"
          % (bestR, startR, best.size, altR))

    return {"best": best, "alternative": alt}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _full_lbfgs(h, deadline, maxiter=300):
    ht = h
    for beta in [1e6, 1e7, 0.0]:
        if time.process_time() >= deadline - 0.5:
            break
        ht = _lbfgs_all_pos(ht, maxiter, deadline - 0.3, beta=beta)
    return ht


def _peak_window_polish(h, deadline, pad=3):
    ht = h
    for pf in [0.10, 0.06, 0.04, 0.03]:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(ht, pad_frac=pf, extra=128)
        ht2 = _lbfgs_block(ht, win, 400, deadline - 0.3, beta=1e7)
        if R_of(ht2) > R_of(ht) + 1e-15:
            ht = ht2
    return ht


def _lift2x(h):
    N = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    j = np.arange(2 * N + 1, dtype=float)
    pos = j * 0.5
    C2 = np.interp(pos, np.arange(N + 1, dtype=float), C)
    h2 = np.diff(C2) * 2.0
    return np.clip(h2, 0.0, None)


def _fold2x(h2):
    M = h2.size
    N = M // 2
    C2 = np.concatenate(([0.0], np.cumsum(h2)))
    j = np.arange(N + 1, dtype=float)
    pos = j * 2.0
    Cf = np.interp(pos, np.arange(M + 1, dtype=float), C2)
    hf = np.diff(Cf) * 0.5
    return np.clip(hf, 0.0, None)


def _lift_frac(h, fac):
    """Mass-preserving upsample by integer factor `fac` via cumulative interp."""
    N = h.size
    M = N * fac
    C = np.concatenate(([0.0], np.cumsum(h)))
    pos = np.arange(M + 1, dtype=float) / fac
    C2 = np.interp(pos, np.arange(N + 1, dtype=float), C)
    h2 = np.diff(C2) * fac
    return np.clip(h2, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def _consider(ht, tag):
        nonlocal best, bestR, origin, alt_best, alt_bestR
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR, origin = ht.copy(), r, tag
            print("%s NEW BEST R=%.9f" % (tag, bestR))
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r
        return r

    # ---- Phase A: full L-BFGS polish of the start ----
    h = best.copy()
    phaseA_deadline = min(deadline - 4.0, time.process_time() + 10.0)
    h = _full_lbfgs(h, phaseA_deadline, maxiter=200)
    h = _rescale(h)
    rA = _consider(h, 'phaseA')
    print("Phase A R=%.9f" % rA)

    # ---- Phase B: lift 2x -> polish -> fold back ----
    folds_accepted = 0
    for it in range(3):
        if time.process_time() >= deadline - 4.0:
            break
        h2 = _lift2x(h)
        h2 = _rescale(h2)
        b_deadline = min(deadline - 3.0, time.process_time() + 8.0)
        h2 = _full_lbfgs(h2, b_deadline, maxiter=150)
        hf = _fold2x(h2)
        hf = _rescale(hf)
        r_old = R_of(h)
        r_new = R_of(hf)
        if r_new > r_old + 1e-12:
            h = hf
            folds_accepted += 1
            print("Phase B iter %d FOLD ACCEPT R=%.9f (was %.9f)" % (it, r_new, r_old))
            _consider(h, 'fold%d' % it)
        else:
            print("Phase B iter %d fold rejected (%.9f vs %.9f)" % (it, r_new, r_old))
            if r_new > alt_bestR:
                alt_best, alt_bestR = hf.copy(), r_new

    # ---- Phase C: full polish + peak window polish ----
    if time.process_time() < deadline - 2.0:
        c_deadline = min(deadline - 1.5, time.process_time() + 5.0)
        h = _full_lbfgs(h, c_deadline, maxiter=300)
        h = _rescale(h)
        _consider(h, 'phaseC')
        pk_deadline = min(deadline - 1.0, time.process_time() + 4.0)
        h = _peak_window_polish(h, pk_deadline, pad=3)
        h = _rescale(h)
        _consider(h, 'phaseC_pk')
        print("Phase C R=%.9f" % R_of(h))

    # ---- Phase D: alternate full L-BFGS and peak polish ----
    it = 0
    while time.process_time() < deadline - 1.0:
        it += 1
        if it % 2 == 1:
            d_deadline = min(deadline - 0.8, time.process_time() + 3.0)
            ht = _full_lbfgs(h, d_deadline, maxiter=300)
        else:
            d_deadline = min(deadline - 0.8, time.process_time() + 3.0)
            ht = _peak_window_polish(h, d_deadline, pad=3)
        ht = _rescale(ht)
        r = _consider(ht, 'phaseD%d' % it)
        if r > R_of(h) + 1e-14:
            h = ht
        else:
            h = ht if r >= R_of(h) - 1e-12 else h

    print("folds_accepted=%d phaseD_iters=%d" % (folds_accepted, it))
    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
