def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150, mask=None):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    if mask is None:
        pos = np.flatnonzero(h > 0)
    else:
        pos = np.flatnonzero((h > 0) & mask)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.05)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _coarsen(h, fac):
    n = h.size
    m = n // fac
    if m < 1:
        return h.copy()
    hh = h[:m * fac].reshape(m, fac).sum(axis=1)
    return _rescale(hh)


def _prolongate(hc, n):
    x_old = np.linspace(0.0, 1.0, hc.size)
    x_new = np.linspace(0.0, 1.0, n)
    return _rescale(np.clip(np.interp(x_new, x_old, hc), 0, None))


def _peak_mask(h, frac=0.05, pad=20):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return np.zeros(h.size, dtype=bool)
    idx = np.flatnonzero(L >= mx * (1.0 - frac))
    if idx.size == 0:
        return np.zeros(h.size, dtype=bool)
    # knot index j corresponds to cell j-1 (knots are [0, conv, 0])
    lo = max(0, int(idx[0]) - 1 - pad)
    hi = min(h.size, int(idx[-1]) - 1 + pad + 1)
    mask = np.zeros(h.size, dtype=bool)
    mask[lo:hi] = True
    return mask


def _perturb(h0, rng, kind):
    h = h0.copy()
    n = h.size
    act = np.flatnonzero(h > 0)
    if kind == 0:
        if act.size:
            h[act] = h[act] * np.exp(0.02 * rng.standard_normal(act.size))
    elif kind == 1:
        if act.size:
            h[act] = h[act] * np.exp(0.05 * rng.standard_normal(act.size))
    elif kind == 2:
        k = max(1, int(0.02 * n))
        sel = rng.choice(n, size=min(k, n), replace=False)
        amp = rng.uniform(0.05, 0.3) * h0.mean()
        h[sel] = amp * rng.uniform(0.5, 1.5, sel.size)
    elif kind == 3:
        hc = _coarsen(h, 4)
        h = _prolongate(hc, n)
    return _rescale(np.clip(h, 0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    rng = np.random.default_rng(20240517)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    print("base R=%.12f (N=%d)" % (startR, h0.size))

    # Short race: 4 arms, two rounds
    kinds = [0, 1, 2, 3]
    arms = []
    for kind in kinds:
        hk = _perturb(h0, rng, kind)
        arms.append({"h": hk, "R": R_of(hk), "gain": 0.0, "time": 0.0, "kind": kind})

    race_t0 = time.process_time()
    for per_arm in (0.4, 0.8):
        for a in arms:
            if time.process_time() >= deadline - 5.0:
                break
            t_start = time.process_time()
            tlim = min(deadline - 5.0, t_start + per_arm)
            h_new = _full_lbfgs(a["h"], tlim, maxiter=200)
            r_new = R_of(h_new)
            dt = time.process_time() - t_start
            a["time"] += dt
            if r_new > a["R"] + 1e-15:
                a["gain"] += r_new - a["R"]
                a["h"] = h_new
                a["R"] = r_new
        arms.sort(key=lambda a: -a["R"])
        arms = arms[:2]
        print("race round per_arm=%.2fs best=%.12f" % (per_arm, arms[0]["R"]))
    race_time = time.process_time() - race_t0
    race_gain = max(a["R"] for a in arms) - startR
    print("race done: best=%.12f gain=%.2e time=%.2fs gain/s=%.2e" %
          (arms[0]["R"], race_gain, race_time, race_gain / max(race_time, 1e-9)))

    best = arms[0]["h"].copy()
    bestR = arms[0]["R"]
    second = arms[1]["h"].copy() if len(arms) > 1 else h0.copy()

    long_t0 = time.process_time()
    long_start_R = bestR
    stall = 0
    pass_idx = 0
    while time.process_time() < deadline - 0.5:
        remaining = deadline - time.process_time()
        if remaining < 0.5:
            break
        prevR = bestR
        if pass_idx % 2 == 0:
            # full-array descent
            tlim = min(deadline - 0.3, time.process_time() + remaining * 0.6)
            cand = _full_lbfgs(best, tlim, maxiter=400)
            r_cand = R_of(cand)
            if r_cand > bestR + 1e-15:
                best = cand; bestR = r_cand
                print("full R=%.12f (+%.2e)" % (bestR, bestR - prevR))
        else:
            # peak-window descent
            mask = _peak_mask(best, frac=0.05, pad=20)
            tlim = min(deadline - 0.3, time.process_time() + remaining * 0.6)
            cand = _lbfgs_custom(best, _fun_grad_tie, tlim, maxiter=400, mask=mask)
            r_cand = R_of(cand)
            if r_cand > bestR + 1e-15:
                best = cand; bestR = r_cand
                print("peak R=%.12f (+%.2e)" % (bestR, bestR - prevR))
        if bestR - prevR < 1e-7:
            stall += 1
        else:
            stall = 0
        if stall >= 3:
            # escape: coarsen -> prolongate -> full
            n = best.size
            hc = _coarsen(best, 4)
            cand = _prolongate(hc, n)
            tlim = min(deadline - 0.3, time.process_time() + remaining * 0.5)
            cand = _full_lbfgs(cand, tlim, maxiter=300)
            r_cand = R_of(cand)
            if r_cand > bestR + 1e-15:
                best = cand; bestR = r_cand
                print("escape R=%.12f" % bestR)
            stall = 0
        pass_idx += 1

    long_time = time.process_time() - long_t0
    long_gain = bestR - long_start_R
    print("long run: gain=%.2e time=%.2fs gain/s=%.2e" %
          (long_gain, long_time, long_gain / max(long_time, 1e-9)))

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    alt = second if second.shape == best.shape else h0.copy()
    if alt.shape == best.shape and np.array_equal(alt, best):
        alt = h0.copy()

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))
    return {"best": best, "alternative": alt}

