    lo = max(0, int(c) - pad - n // frac)
    hi = min(n, int(c) + pad + n // frac)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


# ---------- block rasterisers ----------

def _build_sharp_from(u, d, M, m, N):
    a = np.exp(np.clip(u, -40.0, 40.0))
    e = np.empty(M - 1)
    for j in range(M - 1):
        e[j] = (j + 1) * m + d[j]
    for j in range(1, M - 1):
        if e[j] < e[j - 1] + 1.0:
            e[j] = e[j - 1] + 1.0
    for j in range(M - 2, -1, -1):
        if e[j] > e[j + 1] - 1.0:
            e[j] = e[j + 1] - 1.0
    bounds = np.round(e).astype(int)
    bounds = np.clip(bounds, 1, N - 1)
    for j in range(1, M - 1):
        if bounds[j] <= bounds[j - 1]:
            bounds[j] = bounds[j - 1] + 1
    h = np.empty(N)
    prev = 0
    for j in range(M - 1):
        b = bounds[j]
        h[prev:b] = a[j]
        prev = b
    h[prev:] = a[M - 1]
    return h


def _detect_blocks(h, M, tol=1e-9):
    N = h.size
    if N % M != 0:
        return False, 0, None
    m = N // M
    if m <= 0:
        return False, 0, None
    v0 = np.empty(M)
    scale = max(h.max(), 1e-300)
    for j in range(M):
        seg = h[j * m:(j + 1) * m]
        mu = seg.mean()
        if np.max(np.abs(seg - mu)) / scale > tol:
            return False, 0, None
        v0[j] = np.log(max(mu, 1e-300))
    return True, m, v0


def _block_fun_grad(z, M, m, N):
    """Free-boundary block optimiser in (u, d) parameters."""
    u = z[:M]
    d = z[M:]
    h = _build_sharp_from(u, d, M, m, N)
    val, gh = _fun_grad_tie(h)
    a = np.exp(np.clip(u, -40.0, 40.0))
    # block boundaries
    e = np.empty(M - 1)
    for j in range(M - 1):
        e[j] = (j + 1) * m + d[j]
    for j in range(1, M - 1):
        if e[j] < e[j - 1] + 1.0:
            e[j] = e[j - 1] + 1.0
    for j in range(M - 2, -1, -1):
        if e[j] > e[j + 1] - 1.0:
            e[j] = e[j + 1] - 1.0
    bounds = np.round(e).astype(int)
    bounds = np.clip(bounds, 1, N - 1)
    for j in range(1, M - 1):
        if bounds[j] <= bounds[j - 1]:
            bounds[j] = bounds[j - 1] + 1
    g_u = np.zeros(M)
    prev = 0
    for j in range(M - 1):
        b = bounds[j]
        g_u[j] = np.sum(gh[prev:b] * h[prev:b])
        prev = b
    g_u[M - 1] = np.sum(gh[prev:] * h[prev:])
    g_d = np.zeros(M - 1)
    for j in range(M - 1):
        b = bounds[j]
        if b <= 0 or b >= N:
            continue
        g_d[j] = gh[b - 1] * (a[j + 1] - a[j])
    return val, np.concatenate([g_u, g_d])


def _opt_blocks(h0, M, deadline):
    N = h0.size
    ok, m, u0 = _detect_blocks(h0, M, tol=1e-9)
    if not ok:
        # fit best m by trying divisors
        best = h0
        bestR = R_of(h0)
        for m in range(max(1, N // M - 4), N // M + 5):
            if N % m != 0:
                continue
            M2 = N // m
            if M2 < 2 or M2 > 200:
                continue
            # approximate u0 from block means
            uu = np.empty(M2)
            for j in range(M2):
                mu = h0[j * m:(j + 1) * m].mean()
                uu[j] = np.log(max(mu, 1e-300))
            z0 = np.concatenate([uu, np.zeros(M2 - 1)])
            val, g = _block_fun_grad(z0, M2, m, N)
            # single L-BFGS run
            def f(zz):
                return _block_fun_grad(zz, M2, m, N)
            cb = _make_cb(deadline - 0.5)
            try:
                res = minimize(f, z0, jac=True, method='L-BFGS-B',
                               bounds=[(-20.0, 20.0)] * M2 + [(-3.0, 3.0)] * (M2 - 1),
                               callback=cb,
                               options={'maxiter': 200, 'maxfun': 400,
                                        'ftol': 1e-22, 'gtol': 1e-18})
            except (TimeoutError, Exception):
                continue
            if res is None:
                continue
            zr = res.x.copy()
            zr[M2:] = np.clip(zr[M2:], -3.0, 3.0)
            hh = _rescale(_build_sharp_from(zr[:M2], zr[M2:], M2, m, N))
            rr = R_of(hh)
            if rr > bestR:
                best = hh
                bestR = rr
            if time.process_time() > deadline - 1.0:
                break
        return best
    z0 = np.concatenate([u0, np.zeros(M - 1)])

    def f(zz):
        return _block_fun_grad(zz, M, m, N)

    cb = _make_cb(deadline - 0.5)
    try:
        res = minimize(f, z0, jac=True, method='L-BFGS-B',
                       bounds=[(-20.0, 20.0)] * M + [(-3.0, 3.0)] * (M - 1),
                       callback=cb,
                       options={'maxiter': 300, 'maxfun': 600,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    zr = res.x.copy()
    zr[M:] = np.clip(zr[M:], -3.0, 3.0)
    hh = _rescale(_build_sharp_from(zr[:M], zr[M:], M, m, N))
    return hh


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))
        return {"best": h0}

    base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
    if base.size == 0 or base.sum() <= 0:
        return {"best": base}
    h0 = _rescale(base)
    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    N = best.size
    print("base R=%.12f (N=%d)" % (bestR, N))

    alt = None
    altR = -1.0

    # ---- Main new idea: free-boundary block optimisation at several block counts ----
    # The start is a 32-block array. Re-optimise with FREE boundary positions
    # (d != 0) plus a fine full-array polish. Try several M values, keep the best.
    for M in (32, 48, 64, 96, 24, 40, 80, 128):
        if time.process_time() > deadline - 6.0:
            break
        tlim = min(deadline - 4.0, time.process_time() + 4.0)
        hb = _opt_blocks(h0, M, tlim)
        rb = R_of(hb)
        print("blocks M=%d R=%.12f" % (M, rb))
        if rb > bestR + 1e-12:
            # polish with full L-BFGS
            if time.process_time() < deadline - 2.0:
                tlim2 = min(deadline - 1.5, time.process_time() + 2.5)
                hp = _full_lbfgs(hb, tlim2, maxiter=200)
                rp = R_of(hp)
                if rp > rb:
                    hb = hp
                    rb = rp
                if time.process_time() < deadline - 1.0:
                    tlim3 = min(deadline - 1.0, time.process_time() + 1.0)
                    hpk = _peak_window_polish(hb, tlim3, pad=3, frac=8)
                    rpk = R_of(hpk)
                    if rpk > rb:
                        hb = hpk
                        rb = rpk
            print("  ACCEPT M=%d: %.12f" % (M, rb))
            best = hb
            bestR = rb
        elif alt is None or rb > altR:
            alt = hb
            altR = rb

    # ---- Direct full-array L-BFGS polish on best (also try on start) ----
    if time.process_time() < deadline - 2.0:
        tlim = min(deadline - 1.5, time.process_time() + 3.0)
        hp = _full_lbfgs(best, tlim, maxiter=200)
        rp = R_of(hp)
        print("full polish R=%.12f" % rp)
        if rp > bestR:
            best = hp
            bestR = rp

    # ---- CVaR cycling on best ----
    while time.process_time() < deadline - 1.0:
        tlim = min(deadline - 1.0, time.process_time() + 2.5)
        hc = _lbfgs_custom(best, lambda hh: _fun_grad_cvar(hh, 0.18),
                           tlim, maxiter=60)
        if time.process_time() < deadline - 1.0:
            tlim2 = min(deadline - 1.0, time.process_time() + 1.0)
            hc = _peak_window_polish(hc, tlim2, pad=3, frac=8)
        rc = R_of(hc)
        print("cvar R=%.12f (best %.12f)" % (rc, bestR))
        if rc > bestR:
            best = hc
            bestR = rc
        else:
            break

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    if alt is not None and altR > 0 and alt is not best:
        return {"best": best, "alternative": alt}
    return {"best": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_lav(h, k):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    k = max(1, int(k))
    if k <= 1:
        return _fun_grad(h)
    ker = np.ones(k) / k
    sk = np.convolve(Lf, ker, mode='same')
    m = int(np.argmax(sk))
    sm = sk[m]
    if sm <= 0:
        return _fun_grad(h)
    gLf = -dq / num
    half = k // 2
    lo = m - half
    hi = lo + k
    if lo < 0:
        lo = 0; hi = k
    if hi > Lf.size:
        hi = Lf.size; lo = hi - k
    gLf[lo:hi] += (1.0 / sm) * (1.0 / k)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _upsample(h, factor):
    if factor <= 1:
        return h.copy()
    n = h.size
    m = n * factor
    x = np.linspace(0, n, m, endpoint=False)
    xi = np.arange(n)
    return np.interp(x, xi, h)


def _upsample_n(h, newn):
    n = h.size
    x = np.linspace(0, n, newn, endpoint=False)
    xi = np.arange(n)
    return np.interp(x, xi, h)


def _sharpen(h, deadline, iters=120):
    if time.process_time() >= deadline - 1.0:
        return h
    hb = _lbfgs_log(h, iters, deadline,
                    fg=lambda hh: _fun_grad_lav(hh, 9))
    hs = _lbfgs_log(hb, 40, deadline)
    return hs


def _grow(h, deadline, target, alt_tracker):
    """Upsample to a larger N and re-polish. Track best as alternative."""
    cur = h
    curR = R_of(cur)
    while cur.size < target and time.process_time() < deadline - 12.0:
        factor = 2
        n_new = min(cur.size * factor, target)
        if n_new <= cur.size:
            break
        up = _rescale(_upsample_n(cur, n_new))
        r_up = R_of(up)
        cand, rc = up, r_up
        for kk in (9, 5, 3, 1):
            if time.process_time() >= deadline - 10.0:
                break
            fg = (lambda hh, kkk=kk: _fun_grad_lav(hh, kkk))
            hb = _lbfgs_log(cand, 60, deadline, fg=fg)
            hs = _lbfgs_log(hb, 12, deadline)
            rs = R_of(hs)
            hp = _window_polish_peak(hs, deadline, 0.10, 64, maxiter=100)
            rp = R_of(hp)
            if rp > rs:
                hs, rs = hp, rp
            if rs > rc:
                cand, rc = hs, rs
        if rc > alt_tracker[1]:
            alt_tracker[0] = cand.copy()
            alt_tracker[1] = rc
        print("  grow -> N=%d R=%.7f" % (cand.size, rc))
        if rc > curR - 1e-9:
            cur, curR = cand, rc
        else:
            break
    return cur, curR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    mx0, m0, near0 = _stats(best)
    print("base R=%.7f (N=%d) Lmax=%.6e argmax=%d near=%d" %
          (bestR, best.size, mx0, m0, near0))

    cur = best.copy()
    curR = bestR
    alt_tracker = [None, 0.0]

    # ---- Phase 1: sharpen + polish loop on current resolution ----
    stage = 0
    while time.process_time() < deadline - 8.0:
        stage += 1
        improved = False
        for kk in (15, 11, 9, 7, 5, 3, 1):
            if time.process_time() >= deadline - 6.0:
                break
            fg = (lambda hh, kkk=kk: _fun_grad_lav(hh, kkk))
            hb = _lbfgs_log(cur, 60, deadline, fg=fg)
            hs = _lbfgs_log(hb, 12, deadline)
            rs = R_of(hs)
            hp = _window_polish_peak(hs, deadline, 0.12, 48, maxiter=100)
            rp = R_of(hp)
            cand, rc = (hp, rp) if rp > rs else (hs, rs)
            if rc > curR + 1e-13:
                cur, curR = cand, rc
                improved = True
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
                print("  stage %d k=%d R=%.7f" % (stage, kk, curR))
        if not improved:
            break

    # ---- Phase 2: grow resolution as far as budget allows ----
    # Attempt several growth targets; the current start is ~85k so push to ~340k.
    for target in (cur.size * 2, cur.size * 4, 500000, 800000):
        if time.process_time() >= deadline - 12.0:
            break
        if target <= cur.size:
            continue
        if target > 900000:
            target = 900000
        newc, newr = _grow(cur, deadline, target, alt_tracker)
        if newr > curR + 1e-13:
            cur, curR = newc, newr
            if curR > bestR + 1e-13:
                best, bestR = cur.copy(), curR
        else:
            break

    # ---- Phase 3: final extended polish at current resolution ----
    while time.process_time() < deadline - 2.0:
        improved = False
        for (kk, iters) in [(11, 80), (7, 100), (5, 120), (3, 150), (1, 150)]:
            if time.process_time() >= deadline - 3.0:
                break
            fg = (lambda hh, kkk=kk: _fun_grad_lav(hh, kkk))
            hb = _lbfgs_log(cur, iters, deadline, fg=fg)
            hs = _lbfgs_log(hb, 10, deadline)
            rs = R_of(hs)
            hp = _window_polish_peak(hs, deadline, 0.10, 32, maxiter=120)
            rp = R_of(hp)
            cand, rc = (hp, rp) if rp > rs else (hs, rs)
            if rc > curR + 3e-13:
                cur, curR = cand, rc
                improved = True
                if curR > bestR + 1e-13:
                    best, bestR = cur.copy(), curR
                print("  final k=%d R=%.7f" % (kk, curR))
        if not improved:
            break

    if time.process_time() < deadline - 0.5:
        hf = _lbfgs_log(best, 300, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf, rf

    mx, m, near = _stats(best)
    print("final R=%.7f (N=%d) Lmax=%.6e argmax=%d near=%d" %
          (bestR, best.size, mx, m, near))

    alt = alt_tracker[0]
    if bestR > start_bestR + 1e-12:
        if alt is not None and alt.size != best.size and alt_tracker[1] > start_bestR + 1e-12:
            return {"best": best, "alternative": alt}
        return best
    if alt is not None and alt.size != start_best.size:
        return {"best": start_best, "alternative": alt}
    return {"best": start_best,
