import numpy as np
import time

try:
    from scipy.linalg import solve_toeplitz
    from scipy.optimize import minimize
    _HAVE_SCIPY = True
except Exception:
    _HAVE_SCIPY = False


def _R(h):
    h = np.asarray(h, dtype=float)
    if not np.all(np.isfinite(h)):
        return -1.0
    if np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    c = np.convolve(h, h)
    L = np.concatenate(([0.0], c, [0.0]))
    Ln = L[:-1]
    Lp = L[1:]
    num = np.sum(Ln * Ln + Ln * Lp + Lp * Lp) / 3.0
    den = s * s * np.max(L)
    if den <= 0:
        return -1.0
    return num / den


def _autoconv(h):
    return np.convolve(h, h)


def _target(N, plateau_frac=0.9, ramp_frac=0.05):
    """Flat target on [0, plateau_frac*N] with cosine ramp."""
    M = 2 * N - 1
    x = np.arange(M) / float(M - 1)
    g = np.ones(M)
    # ramp down at the tail
    start = plateau_frac
    end = min(1.0, plateau_frac + ramp_frac)
    if end > start:
        mask = x > start
        t = np.clip((x - start) / (end - start), 0, 1)
        g[mask] = 0.5 * (1 + np.cos(np.pi * t[mask]))
    return g


def _deconvolve(N, m0=512, iters=10, plateau_frac=0.9):
    """Volterra deconvolution: f1 = cell averages of x^-1/2 on first m0 cells."""
    f = np.zeros(N)
    # cell averages of x^-1/2 on cells [i, i+1] for i in [0, m0)
    # integral of x^-1/2 from i to i+1 = 2(sqrt(i+1)-sqrt(i))
    i = np.arange(m0)
    f[:m0] = 2.0 * (np.sqrt(i + 1.0) - np.sqrt(i))
    g_target = _target(N, plateau_frac=plateau_frac)

    best = f.copy()
    bestR = _R(best)

    for it in range(iters):
        c = _autoconv(f)
        r = g_target - c
        # solve 2*f1 * delta = r via Toeplitz: (f1 * delta) convolution = r/2
        # We want delta such that f1 (*) delta = r/2 (first N entries)
        rhs = r[:N] / 2.0
        try:
            if _HAVE_SCIPY:
                col = np.zeros(N)
                col[0] = f[0]
                delta = solve_toeplitz((f, col), rhs)
            else:
                # fallback: triangular solve via forward substitution
                delta = np.zeros(N)
                for k in range(N):
                    s = rhs[k]
                    for j in range(k):
                        s -= f[k - j] * delta[j]
                    if f[0] != 0:
                        delta[k] = s / f[0]
                    else:
                        delta[k] = 0.0
        except Exception:
            break
        if not np.all(np.isfinite(delta)):
            break
        f = np.clip(f + delta, 0.0, None)
        # rescale so max of f*f is 1
        c = _autoconv(f)
        mx = np.max(c)
        if mx > 0:
            f = f / np.sqrt(mx)
        Rv = _R(f)
        if Rv > bestR:
            bestR = Rv
            best = f.copy()
    return best, bestR


def _prolongate(h, N_new):
    """Linear interpolation to N_new cells."""
    N = len(h)
    if N == N_new:
        return h.copy()
    x_old = (np.arange(N) + 0.5) / N
    x_new = (np.arange(N_new) + 0.5) / N_new
    return np.interp(x_new, x_old, h)


def _full_lbfgs(h0, time_left, maxiter=200):
    """Short L-BFGS polish on the exact R objective."""
    N = len(h0)
    s0 = h0.sum()
    if s0 <= 0:
        return h0.copy(), _R(h0)
    x0 = h0 / s0  # normalize to unit mass

    def negR(x):
        h = np.abs(x)
        return -_R(h)

    best = h0.copy()
    bestR = _R(h0)
    t_start = time.process_time()
    try:
        res = minimize(negR, x0, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                'ftol': 1e-15, 'gtol': 1e-12})
        h = np.abs(res.x)
        Rv = _R(h)
        if Rv > bestR:
            bestR = Rv
            best = h.copy()
    except Exception:
        pass
    # a few extra restarts if time permits
    while time.process_time() - t_start < time_left * 0.5:
        try:
            x0 = best / best.sum() if best.sum() > 0 else x0
            res = minimize(negR, x0, method='L-BFGS-B',
                           options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                    'ftol': 1e-15, 'gtol': 1e-12})
            h = np.abs(res.x)
            Rv = _R(h)
            if Rv > bestR + 1e-12:
                bestR = Rv
                best = h.copy()
            else:
                break
        except Exception:
            break
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 2.0

    # Baseline: start
    best = None
    bestR = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and np.any(s > 0):
            best = s.copy()
            bestR = _R(best)

    # Main experiment: deconvolution at N=4096
    N0 = 4096
    m0 = 512
    try:
        f_dec, R_dec = _deconvolve(N0, m0=m0, iters=10, plateau_frac=0.9)
    except Exception:
        f_dec, R_dec = None, -1.0

    raw_alt = None
    if f_dec is not None and np.all(np.isfinite(f_dec)) and np.any(f_dec > 0):
        raw_alt = f_dec.copy()
        if R_dec > bestR:
            bestR = R_dec
            best = f_dec.copy()

    # Prolongate to N=16384 and polish
    if f_dec is not None and np.any(f_dec > 0):
        N1 = 16384
        f1 = _prolongate(f_dec, N1)
        R1 = _R(f1)
        if R1 > bestR:
            bestR = R1
            best = f1.copy()
        # time budget for polish
        elapsed = time.process_time() - t0
        remaining = deadline - elapsed
        if remaining > 1.0:
            try:
                f_pol, R_pol = _full_lbfgs(f1, remaining * 0.9, maxiter=300)
                if R_pol > bestR:
                    bestR = R_pol
                    best = f_pol.copy()
            except Exception:
                pass

    # If we still have time, try a slightly different plateau target
    elapsed = time.process_time() - t0
    if elapsed < deadline - 3.0:
        try:
            f2, R2 = _deconvolve(N0, m0=m0, iters=10, plateau_frac=0.85)
            if f2 is not None and np.any(f2 > 0):
                N1 = 16384
                f2p = _prolongate(f2, N1)
                R2p = _R(f2p)
                if R2p > bestR:
                    bestR = R2p
                    best = f2p.copy()
                elapsed = time.process_time() - t0
                remaining = deadline - elapsed
                if remaining > 1.0:
                    f2pol, R2pol = _full_lbfgs(f2p, remaining * 0.9, maxiter=300)
                    if R2pol > bestR:
                        bestR = R2pol
                        best = f2pol.copy()
        except Exception:
            pass

    if best is None:
        best = np.ones(50)

    # Final safety
    if not np.all(np.isfinite(best)) or not np.any(best > 0):
        if start is not None:
            best = np.asarray(start, dtype=float)
        else:
            best = np.ones(50)

    if raw_alt is not None and np.all(np.isfinite(raw_alt)) and np.any(raw_alt > 0):
        return {"best": best, "alternative": raw_alt}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _upsample(h, n):
    x_old = np.linspace(0.0, 1.0, h.size)
    x_new = np.linspace(0.0, 1.0, n)
    return _rescale(np.clip(np.interp(x_new, x_old, h), 0, None))


def _local_sweep(h, deadline, passes=6):
    h = h.copy()
    bestR = R_of(h)
    n = h.size
    if n == 0:
        return h, bestR
    rng = np.random.RandomState(12345)
    factors = np.array([0.9, 0.95, 0.98, 1.02, 1.05, 1.1])
    blk = max(1, n // 200)
    for _ in range(passes):
        if time.process_time() > deadline:
            break
        improved = False
        order = rng.permutation((n + blk - 1) // blk)
        for bi in order:
            if time.process_time() > deadline:
                break
            lo = bi * blk
            hi = min(n, lo + blk)
            cur = h[lo:hi].copy()
            curR = bestR
            bestf = 1.0
            for f in factors:
                h[lo:hi] = cur * f
                r = R_of(h)
                if r > curR:
                    curR = r; bestf = f
            h[lo:hi] = cur * bestf
            if bestf != 1.0:
                bestR = curR
                improved = True
        if not improved:
            break
    return h, bestR


def _modulate(base, coefs, x):
    K = coefs.size // 2
    a = coefs[:K]
    b = coefs[K:]
    phase = 2.0 * np.pi * np.outer(x, np.arange(1, K + 1))
    mod = np.cos(phase) @ a + np.sin(phase) @ b
    return base * np.exp(mod)


def _mod_search(base, deadline, K=24, n_starts=6, sigma=0.05, seed=777):
    n = base.size
    x = np.arange(n, dtype=float) / n
    rng = np.random.RandomState(seed)
    bestR = R_of(base)
    best_coefs = np.zeros(2 * K)

    def negR(coefs):
        if time.process_time() > deadline:
            raise TimeoutError
        h = _modulate(base, coefs, x)
        return -R_of(h)

    for s in range(n_starts):
        if time.process_time() > deadline:
            break
        c0 = rng.randn(2 * K) * sigma
        try:
            res = minimize(negR, c0, method='Powell',
                           options={'maxiter': 400, 'xtol': 1e-6, 'ftol': 1e-10})
        except (TimeoutError, Exception):
            break
        if res is None or not np.all(np.isfinite(res.x)):
            continue
        r = -res.fun
        if r > bestR:
            bestR = r
            best_coefs = res.x.copy()
    return best_coefs, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    baseR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    # --- Experiment: low-dimensional multiplicative Fourier modulation ---
    alt_best = None
    altR = 0.0
    if best.size > 1:
        mod_deadline = min(deadline - 5.0, time.process_time() + budget_seconds * 0.45)
        coefs, modR = _mod_search(best, mod_deadline)
        h_mod = _modulate(best, coefs, np.arange(best.size, dtype=float) / best.size)
        h_mod = _rescale(h_mod)
        r_mod = R_of(h_mod)
        print("modulated R=%.12f (raw %.12f)" % (r_mod, modR))
        if r_mod > bestR:
            # polish the modulated array
            tlim = min(deadline - 2.0, time.process_time() + 8.0)
            h_pol = _full_lbfgs(h_mod, tlim, maxiter=250)
            r_pol = R_of(h_pol)
            print("modulated+polish R=%.12f" % r_pol)
            if r_pol > r_mod:
                h_mod = h_pol
                r_mod = r_pol
            if r_mod > bestR:
                best = h_mod
                bestR = r_mod
        # keep modulated as alternative if it differs meaningfully
        alt_best = h_mod.copy()
        altR = r_mod

    # --- Keep base's polish loop ---
    while time.process_time() < deadline - 2.0:
        tlim = min(deadline - 1.0, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("polish R=%.12f" % bestR)
        else:
            break

    n0 = best.size
    for n in (n0 * 2, n0 * 3, n0 * 4):
        if time.process_time() > deadline - 3.0:
            break
        n = min(1000000, int(n))
        if n <= best.size:
            continue
        h_up = _upsample(best, n)
        r_up = R_of(h_up)
        if r_up > bestR:
            best = h_up; bestR = r_up
            print("up R=%.12f (N=%d)" % (bestR, best.size))
        tlim = min(deadline - 2.0, time.process_time() + 5.0)
        hc = _full_lbfgs(best, tlim, maxiter=250)
        rc = R_of(hc)
        if rc > bestR:
            best = hc; bestR = rc
            print("polish R=%.12f (N=%d)" % (bestR, best.size))

    if time.process_time() < deadline - 2.0:
        hc, rc = _local_sweep(best, deadline - 1.0, passes=10)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("sweep R=%.12f" % bestR)

    while time.process_time() < deadline - 0.5:
        tlim = min(deadline - 0.2, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("polish R=%.12f" % bestR)
        else:
            break

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    if alt_best is None or altR <= 0:
        alt = best
    else:
        alt = alt_best

    print("final R=%.12f (start %.12f, N=%d, altR=%.12f)"
          % (bestR, startR, best.size, altR))

    return {"best": best, "alternative": alt}

