def _flat_plateau_target(h, alpha):
    """Build a target knot profile that is flat (== max) over a stretch of
    length alpha of the support, tapering to zero outside, then fit f via NNLS
    on the autoconvolution relation.  Different shape family from the base."""
    n = h.size
    L = _knots(h)
    mx = L.max()
    t = np.arange(L.size) / (L.size - 1.0)  # knot positions in [0,1]
    c = 0.5
    lo = c - alpha / 2.0
    hi = c + alpha / 2.0
    g = np.ones_like(t)
    left = t < lo
    right = t > hi
    if lo > 0:
        g[left] = (t[left] / lo) ** 2
    if hi < 1:
        g[right] = ((1.0 - t[right]) / (1.0 - hi)) ** 2
    g = g * mx
    return g


def _deconv_nnls(h, Nc, alpha, lam):
    """Downsample h to Nc, build convolution matrix, fit to target plateau via
    NNLS with ridge.  Returns candidate heights (size Nc)."""
    n = h.size
    if n != Nc:
        edges = np.linspace(0, n, Nc + 1).astype(int)
        hc = np.array([h[edges[i]:edges[i+1]].sum() for i in range(Nc)])
    else:
        hc = h.copy()
    # Build A: interior knot k (1..2Nc-1) = sum_i hc_i hc_{k-i}
    A = np.zeros((2 * Nc - 1, Nc))
    for k in range(2 * Nc - 1):
        i_lo = max(0, k - (Nc - 1))
        i_hi = min(Nc - 1, k)
        for i in range(i_lo, i_hi + 1):
            A[k, i] = 1.0
    g = _flat_plateau_target(hc, alpha)
    Af = A @ hc
    scale = (Af @ g) / (g @ g + 1e-12)
    An = np.vstack([A, np.sqrt(lam) * np.eye(Nc)])
    bn = np.concatenate([scale * g, np.zeros(Nc)])
    from scipy.optimize import nnls
    try:
        f, _ = nnls(An, bn, maxiter=300)
    except Exception:
        return None
    if f.sum() <= 0:
        return None
    return _rescale(f)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    # Phase 1: polish start
    while time.process_time() < deadline - 1.0:
        tlim = min(deadline - 0.5, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("polish R=%.12f" % bestR)
        else:
            break

    # Phase 2: flat-plateau deconvolution candidates on coarse grid, then lift
    alt_best = best.copy()
    altR = bestR
    target_n = max(best.size, 104992)
    Nc = 1024
    cands = []
    for alpha in (0.25, 0.35, 0.45, 0.55):
        for lam in (1e-4, 1e-3, 1e-2):
            if time.process_time() >= deadline - 8.0:
                break
            f = _deconv_nnls(best, Nc, alpha, lam)
            if f is None:
                continue
            r = R_of(f)
            cands.append((r, f, alpha, lam))
    cands.sort(key=lambda x: -x[0])
    print("deconv: %d cands, top R=%.12f" % (len(cands), cands[0][0] if cands else 0))

    for r, f, alpha, lam in cands[:4]:
        if time.process_time() >= deadline - 4.0:
            break
        h_up = _upsample(f, target_n)
        r_up = R_of(h_up)
        tlim = min(deadline - 2.0, time.process_time() + 5.0)
        hc = _full_lbfgs(h_up, tlim, maxiter=250)
        rc = R_of(hc)
        if rc > r_up:
            r_up = rc; h_up = hc
        if r_up > altR:
            alt_best = h_up.copy(); altR = r_up
            print("deconv lift alpha=%.2f lam=%.0e R=%.12f" % (alpha, lam, r_up))
        if r_up > bestR:
            best = h_up.copy(); bestR = r_up
            print("deconv new best R=%.12f" % bestR)

    # Phase 3: upsample best to target_n if smaller, then polish
    if best.size < target_n and time.process_time() < deadline - 3.0:
        h_up = _upsample(best, target_n)
        r_up = R_of(h_up)
        tlim = min(deadline - 2.0, time.process_time() + 6.0)
        hc = _full_lbfgs(h_up, tlim, maxiter=250)
        rc = R_of(hc)
        if rc > r_up:
            r_up = rc; h_up = hc
        if r_up > bestR:
            best = h_up; bestR = r_up
            print("upsampled R=%.12f (N=%d)" % (bestR, best.size))

    # Phase 4: keep polishing until near deadline
    while time.process_time() < deadline - 0.5:
        tlim = min(deadline - 0.2, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("polish R=%.12f" % bestR)
        else:
            break

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    alt = alt_best if altR > 0 else best

    print("final R=%.12f (start %.12f, N=%d, altR=%.12f)"
          % (bestR, startR, best.size, altR))

    return {"best": best, "alternative": alt}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 1e-30, None)
    x0 = np.log(h)

    def f(x):
        hh = np.exp(x)
        val, g = _fun_grad_tie(hh)
        return val, g * hh

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.exp(res.x))


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _detect_repeat(h):
    n = h.size
    for p in (32, 16, 8, 4, 2):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        H = h.reshape(m, p)
        c = H.mean(axis=1)
        if np.allclose(H, c[:, None], rtol=1e-12, atol=1e-15):
            hr = np.repeat(c, p)
            if abs(R_of(hr) - R_of(h)) <= 1e-12:
                return p, c
    return 1, h


def _interp_lift(c):
    n = c.size
    c2 = np.empty(2 * n)
    c2[0::2] = c
    c2[1:-1:2] = 0.5 * (c[:-1] + c[1:])
    c2[-1] = c[-1]
    return c2


def _coarse(c_in, m):
    n = c_in.size
    if m == n:
        return c_in.copy()
    x = np.linspace(0.0, n, m, endpoint=False) + 0.5 * (n / m)
    xi = np.arange(n, dtype=float) + 0.5
    return np.interp(x, xi, c_in)


def _prolong(c_coarse, m_out):
    m = c_coarse.size
    if m_out == m:
        return c_coarse.copy()
    x = np.linspace(0.0, m, m_out, endpoint=False) + 0.5 * (m_out / m)
    xi = np.arange(m, dtype=float) + 0.5
    return np.interp(x, xi, c_coarse)


def _smooth_penalty_polish(h, deadline, beta, maxiter=400):
    if time.process_time() >= deadline - 0.3:
        return h
    h0 = _rescale(h)
    h1 = _lbfgs_block(h0, np.arange(h0.size), maxiter,
                      min(deadline, time.process_time() + 6.0), beta=beta)
    r0 = R_of(h0); r1 = R_of(h1)
    return h1 if r1 > r0 else h0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- NEW IDEA: build a fresh candidate on a coarser grid, then upsample.
    # The start is at a very fine grid (105k) but likely has a smooth
    # underlying profile. Optimising a coarser representation first avoids
    # getting stuck in the fine-grid local optimum, then we prolong and
    # polish. This is a genuinely different construction from `start`.
    alt = None
    altR = 0.0

    n_target = best.size
    # pick coarse levels based on n_target
    levels = []
    m = n_target
    for _ in range(4):
        m = max(256, m // 2)
        levels.append(m)
    levels = sorted(set(levels + [1024, 2048, 4096]), reverse=True)
    levels = [m for m in levels if m < n_target and m >= 256]

    if levels:
        # start coarse from a downsampled version of `best`
        cur = _coarse(best, levels[0])
        cur = _rescale(np.clip(cur, 1e-30, None))
        curR = R_of(np.interp(np.linspace(0, cur.size - 1, n_target),
                              np.arange(cur.size), cur))
        print("coarse start m=%d R=%.9f" % (cur.size, curR))

        # V-cycle: refine each coarse level, optimise, then prolong
        for li, m in enumerate(levels):
            if time.process_time() >= deadline * 0.5:
                break
            budget_here = min(deadline * 0.5,
                              time.process_time() + 4.0)
            # optimise at this coarse level
            c = _lbfgs_log(cur, 300, budget_here)
            # also try a beta-smoothed pass to escape ties
            if time.process_time() < budget_here - 0.5:
                c2 = _smooth_penalty_polish(c, budget_here, 200.0)
                if R_of(np.interp(np.linspace(0, c2.size - 1, n_target),
                                  np.arange(c2.size), c2)) > \
                   R_of(np.interp(np.linspace(0, c.size - 1, n_target),
                                  np.arange(c.size), c)):
                    c = c2
            cur = c
            # prolong to next finer level
            if li + 1 < len(levels):
                nxt = levels[li + 1]
            else:
                nxt = n_target
            cur = _prolong(cur, nxt)
            cur = _rescale(np.clip(cur, 1e-30, None))
            rfull = R_of(cur)
            print("coarse m=%d -> %d R=%.9f" % (c.size, nxt, rfull))
            if rfull > altR + 1e-15:
                alt = cur.copy()
                altR = rfull

        # final polish at full size
        if alt is not None and alt.size == n_target:
            if time.process_time() < deadline * 0.75:
                win = _peak_window(alt, pad_frac=0.05, extra=128)
                ap = _lbfgs_block(alt, win, 300,
                                  min(deadline * 0.75,
                                      time.process_time() + 4.0))
                rap = R_of(ap)
                if rap > altR + 1e-15:
                    alt, altR = ap, rap
            if altR > bestR + 1e-15:
                best, bestR = alt.copy(), altR
                print("coarse ACCEPT R=%.9f" % bestR)

    # ---- Phase S: smoothed polish + peak polish on best ----
    s_end = min(deadline, time.process_time() + (deadline - time.process_time()) * 0.35)
    if time.process_time() < s_end - 1.0:
        for beta in (30.0, 100.0, 300.0, 1000.0):
            if time.process_time() >= s_end - 0.8:
                break
            hb = _smooth_penalty_polish(best, min(s_end - 0.5,
                                                 time.process_time() + 4.0),
                                        beta)
            rb = R_of(hb)
            if rb > bestR + 1e-15:
                best, bestR = hb.copy(), rb
            win = _peak_window(hb, pad_frac=0.05, extra=96)
            hp = _lbfgs_block(hb, win, 250,
                              min(s_end - 0.3,
                                  time.process_time() + 3.0))
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp.copy(), rp
        print("smooth+peak R=%.9f" % bestR)

    # ---- Phase E: final peak + beta polish until deadline ----
    c_end = deadline
    beta_cycle = (300.0, 1000.0, 3000.0)
    it = 0
    while time.process_time() < c_end - 0.8:
        it += 1
        pad = (0.06, 0.03, 0.015, 0.008)[it % 4]
        win = _peak_window(best, pad_frac=pad, extra=96)
        ht = _lbfgs_block(best, win, 300,
                          min(c_end - 0.5, time.process_time() + 3.0))
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht.copy(), r
        if time.process_time() < c_end - 0.8:
            beta = beta_cycle[it % len(beta_cycle)]
            hb = _smooth_penalty_polish(best, min(c_end - 0.5,
                                                 time.process_time() + 4.0),
                                        beta)
            rb = R_of(hb)
            if rb > bestR + 1e-15:
                best, bestR = hb.copy(), rb
        print("E it=%d pad=%.3f R=%.9f" % (it, pad, bestR))

    print("final R=%.9f (start %.9f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if start is not None and alt is not None and altR > startR + 1e-14 \
            and altR <= bestR + 1e-14 and alt.size == best.size:
        result["alternative"] = alt
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _upsample(h, n):
    x_old = np.linspace(0.0, 1.0, h.size)
    x_new = np.linspace(0.0, 1.0, n)
    return _rescale(np.clip(np.interp(x_new, x_old, h), 0, None))


def _local_sweep(h, deadline, passes=6):
    h = h.copy()
    bestR = R_of(h)
    n = h.size
    if n == 0:
        return h, bestR
    rng = np.random.RandomState(12345)
    factors = np.array([0.9, 0.95, 0.98, 1.02, 1.05, 1.1])
    blk = max(1, n // 200)
    for _ in range(passes):
        if time.process_time() > deadline:
            break
        improved = False
        order = rng.permutation((n + blk - 1) // blk)
        for bi in order:
            if time.process_time() > deadline:
                break
            lo = bi * blk
            hi = min(n, lo + blk)
            cur = h[lo:hi].copy()
            curR = bestR
            bestf = 1.0
            for f in factors:
                h[lo:hi] = cur * f
                r = R_of(h)
                if r > curR:
                    curR = r; bestf = f
            h[lo:hi] = cur * bestf
            if bestf != 1.0:
                bestR = curR
                improved = True
        if not improved:
            break
    return h, bestR


# ---- Block-vector helpers (32 blocks) ----
def _block_masses(h, K=32):
    n = h.size
    edges = np.linspace(0, n, K + 1).astype(int)
    v = np.zeros(K)
    for i in range(K):
        lo, hi = edges[i], edges[i + 1]
        if hi > lo:
            v[i] = h[lo:hi].sum() / (hi - lo)  # mean height per block
    return v


def _staircase(v, n):
    K = v.size
    edges = np.linspace(0, n, K + 1).astype(int)
    h = np.zeros(n)
    for i in range(K):
        lo, hi = edges[i], edges[i + 1]
        if hi > lo:
            h[lo:hi] = v[i]
    return h


def _low_freq_mod(base, sigma, seed, K=12):
    n = base.size
    x = np.arange(n, dtype=float) / n
    rng = np.random.RandomState(seed)
    mod = np.zeros(n)
    for k in range(1, K + 1):
        a = rng.randn(); b = rng.randn()
        mod += a * np.cos(2 * np.pi * k * x) + b * np.sin(2 * np.pi * k * x)
    mod *= sigma / np.sqrt(K)
    return base * np.exp(mod)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    N = best.size
    K = 32
    v0 = _block_masses(best, K)

    # Build 8 arms
    arms = []
    arms.append(best.copy())  # arm 0
    for sig, sd in zip((0.02, 0.05, 0.10), (1, 2, 3)):
        arms.append(_rescale(_low_freq_mod(best, sig, sd)))
    rng = np.random.RandomState(100)
    for sd in (4, 5, 6):
        jit = v0 * np.exp(rng.uniform(-0.05, 0.05, K))
        arms.append(_rescale(_staircase(jit, N)))
    N7 = 33 * 3281
    arms.append(_upsample(best, N7))

    armR = [R_of(a) for a in arms]

    # Phase 1: 2s polish per arm
    p1_end = min(deadline - 5.0, t0 + budget_seconds * 0.33)
    for i in range(len(arms)):
        if time.process_time() > p1_end:
            break
        tlim = min(p1_end, time.process_time() + 2.0)
        hc = _full_lbfgs(arms[i], tlim, maxiter=120)
        rc = R_of(hc)
        if rc > armR[i]:
            arms[i] = hc; armR[i] = rc
    print("phase1 best arm R=%.12f" % max(armR))

    # Track global best
    gi = int(np.argmax(armR))
    if armR[gi] > bestR:
        best = arms[gi].copy(); bestR = armR[gi]

    # Phase 2: recombination
    p2_end = min(deadline - 4.0, t0 + budget_seconds * 0.75)
    crng = np.random.RandomState(2024)
    while time.process_time() < p2_end - 3.0:
        order = np.argsort(armR)[::-1]
        i1, i2 = order[0], order[1]
        p1, p2 = arms[i1], arms[i2]
        v1 = _block_masses(p1, K)
        v2 = _block_masses(p2, K)
        cx = crng.randint(1, K)
        vc = np.concatenate([v1[:cx], v2[cx:]])
        child = _staircase(vc, N)
        # keep residual fraction from better parent: blend a bit of p1's shape
        child = _rescale(0.5 * child + 0.5 * p1)
        tlim = min(p2_end, time.process_time() + 3.0)
        hc = _full_lbfgs(child, tlim, maxiter=150)
        rc = R_of(hc)
        wi = int(np.argmin(armR))
        if rc > armR[wi]:
            arms[wi] = hc; armR[wi] = rc
        if rc > bestR:
            best = hc.copy(); bestR = rc
            print("child R=%.12f" % bestR)

    # Phase 3: long polish on global best
    gi = int(np.argmax(armR))
    if armR[gi] > bestR:
        best = arms[gi].copy(); bestR = armR[gi]

    while time.process_time() < deadline - 2.0:
        tlim = min(deadline - 1.0, time.process_time() + 4.0)
        hc = _full_lbfgs(best, tlim, maxiter=250)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("polish R=%.12f" % bestR)
        else:
            break

    if time.process_time() < deadline - 1.5:
        hc, rc = _local_sweep(best, deadline - 0.5, passes=4)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("sweep R=%.12f" % bestR)

    while time.process_time() < deadline - 0.5:
        tlim = min(deadline - 0.2, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
        else:
            break

    # alternative: best arm distinct from best
    alt = None
    altR = 0.0
    for i in range(len(arms)):
        if arms[i].size == best.size and np.allclose(arms[i], best):
            continue
        if armR[i] > altR:
            alt = arms[i].copy(); altR = armR[i]
    if alt is None:
        alt = best

    if bestR < startR:
        best = h0.copy(); bestR = startR

    print("final R=%.12f (start %.12f, N=%d, altR=%.12f)"
          % (bestR, startR, best.size, altR))

    return {"best": best, "alternative": alt}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _upsample(h, n):
    x_old = np.linspace(0.0, 1.0, h.size)
    x_new = np.linspace(0.0, 1.0, n)
    return _rescale(np.clip(np.interp(x_new, x_old, h), 0, None))


def _local_sweep(h, deadline, passes=6):
    h = h.copy()
    bestR = R_of(h)
    n = h.size
    if n == 0:
        return h, bestR
    rng = np.random.RandomState(12345)
    factors = np.array([0.9, 0.95, 0.98, 1.02, 1.05, 1.1])
    blk = max(1, n // 200)
    for _ in range(passes):
        if time.process_time() > deadline:
            break
        improved = False
        order = rng.permutation((n + blk - 1) // blk)
        for bi in order:
            if time.process_time() > deadline:
                break
            lo = bi * blk
            hi = min(n, lo + blk)
            cur = h[lo:hi].copy()
            curR = bestR
            bestf = 1.0
            for f in factors:
                h[lo:hi] = cur * f
                r = R_of(h)
                if r > curR:
                    curR = r; bestf = f
            h[lo:hi] = cur * bestf
            if bestf != 1.0:
                bestR = curR
                improved = True
        if not improved:
            break
    return h, bestR


