import numpy as np
import time


def _conv(h):
    return np.convolve(h, h)


def _R_of(h):
    """Compute R from heights h."""
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    g = np.convolve(h, h)
    L = np.empty(g.size + 2)
    L[0] = 0.0
    L[1:-1] = g
    L[-1] = 0.0
    l2 = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    l1 = s * s
    linf = L.max()
    if linf <= 0:
        return -1.0
    return l2 / (l1 * linf)


def _sqrt_seed(n):
    """Capped-inverse-sqrt style seed: a smooth bump."""
    x = (np.arange(n) + 0.5) / n
    h = np.sqrt(np.maximum(0.0, 1.0 - (2*x - 1)**2))
    if h.max() <= 0:
        h = np.ones(n)
    return h


def _volterra(n, deadline, rounds=8):
    """Fixed-point Volterra triangular-solve construction."""
    T = np.ones(n)
    # raised-cosine ramps on target over indices [0.06,0.88]*(2n-2)
    m = 2*n - 1
    idx = np.arange(n)
    lo = 0.06 * (m - 1)
    hi = 0.88 * (m - 1)
    T = np.zeros(n)
    ramp = max(1.0, 0.05 * (hi - lo))
    for k in range(n):
        if k < lo:
            T[k] = 0.0
        elif k <= lo + ramp:
            T[k] = 0.5 * (1 - np.cos(np.pi * (k - lo) / ramp))
        elif k < hi - ramp:
            T[k] = 1.0
        elif k <= hi:
            T[k] = 0.5 * (1 - np.cos(np.pi * (hi - k) / ramp))
        else:
            T[k] = 0.0
    if T.max() > 0:
        T /= T.max()
    T = np.maximum(T, 0.0)

    best_h = None
    best_R = -1.0
    for r in range(rounds):
        if time.process_time() > deadline:
            break
        h = np.zeros(n)
        h[0] = 1.0
        ok = True
        for k in range(1, n):
            if k > 1:
                d = np.dot(h[1:k], h[k-1:0:-1])
            else:
                d = 0.0
            val = (T[k] - d) / (2.0 * h[0])
            if val < 0:
                val = 0.0
            h[k] = val
        # rescale
        g = np.convolve(h, h)
        mx = g.max()
        if mx > 0:
            h = h / np.sqrt(mx)
        R = _R_of(h)
        if R > best_R:
            best_R = R
            best_h = h.copy()
        # multiplicative target update
        g = np.convolve(h, h)
        gmax = g.max()
        if gmax <= 0:
            break
        gs = g[:n] / gmax
        ratio = np.where(gs > 1e-12, T / np.maximum(gs, 1e-12), 1.0)
        ratio = np.clip(ratio, 0.7, 1.4)
        T = T * ratio
        T = np.maximum(T, 0.0)
        if T.max() > 0:
            T /= T.max()
    return best_h, best_R


def _upsample(h, n_new):
    n = h.size
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(n_new) + 0.5) / n_new
    return np.interp(x_new, x_old, h)


def _full_lbfgs(h, deadline, maxiter=200):
    try:
        from scipy.optimize import minimize
    except Exception:
        return h, _R_of(h)

    n = h.size
    x0 = np.log(np.maximum(h, 1e-6))

    def negR(x):
        hh = np.exp(x)
        return -_R_of(hh)

    best_x = x0.copy()
    best_val = negR(x0)
    it = [0]

    def cb(xk):
        it[0] += 1
        if time.process_time() > deadline:
            raise StopIteration

    try:
        res = minimize(negR, x0, method='L-BFGS-B', callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxiter*4})
        if -res.fun > -best_val:
            best_val = res.fun
            best_x = res.x
    except StopIteration:
        pass
    except Exception:
        pass
    return np.exp(best_x), -best_val


def _local_sweep(h, deadline, iters=2000):
    """Coordinate-wise multiplicative perturbation sweep."""
    h = h.copy()
    n = h.size
    R = _R_of(h)
    rng = np.random.default_rng(12345)
    step = 0.05
    for it in range(iters):
        if time.process_time() > deadline:
            break
        if it % 200 == 0 and it > 0:
            step *= 0.7
        k = rng.integers(0, n)
        old = h[k]
        for mult in (1 + step, 1 - step):
            h[k] = old * mult
            Rn = _R_of(h)
            if Rn > R:
                R = Rn
                old = h[k]
                break
            else:
                h[k] = old
    return h, R


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds
    hard_deadline = t0 + 0.93 * budget

    seed = _sqrt_seed(2048)
    seed_R = _R_of(seed)

    # Phase 1: Volterra at n=2048
    d1 = t0 + 0.80 * budget
    h, R = _volterra(2048, d1, rounds=8)

    if h is None or not np.all(np.isfinite(h)) or h.sum() <= 0 or R < seed_R:
        h = seed
        R = seed_R

    best_h = h.copy()
    best_R = R

    # Phase 2: L-BFGS at n=2048
    d2 = min(t0 + 0.55 * budget, hard_deadline)
    if time.process_time() < d2:
        h2, R2 = _full_lbfgs(best_h, d2, maxiter=300)
        if R2 > best_R and np.all(np.isfinite(h2)) and h2.sum() > 0:
            best_h, best_R = h2, R2

    # Phase 3: upsample and polish
    for n_new, frac in ((8192, 0.70), (32768, 0.85)):
        if time.process_time() > hard_deadline:
            break
        h_up = _upsample(best_h, n_new)
        d = min(t0 + frac * budget, hard_deadline)
        h3, R3 = _full_lbfgs(h_up, d, maxiter=150)
        if R3 > best_R and np.all(np.isfinite(h3)) and h3.sum() > 0:
            best_h, best_R = h3, R3

    # Phase 4: local sweep at largest N
    if time.process_time() < hard_deadline:
        d = hard_deadline
        h4, R4 = _local_sweep(best_h, d, iters=3000)
        if R4 > best_R and np.all(np.isfinite(h4)) and h4.sum() > 0:
            best_h, best_R = h4, R4

    # Compare with start
    if start is not None:
        s = np.asarray(start, dtype=float)
        Rs = _R_of(s)
        if Rs > best_R:
            return {"best": s, "alternative": best_h}

    return {"best": best_h, "alternative": seed}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, logit=False):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    if logit:
        hmax = h.max()
        floor = 1e-12 * hmax if hmax > 0 else 1e-12
        x0 = np.log(np.clip(h[active], floor, None))

        def f(x):
            hh = h.copy()
            hh[active] = np.exp(np.clip(x, -40.0, 40.0))
            val, g = _fun_grad_tie(hh)
            return val, g[active] * hh[active]
        bounds = [(-40.0, 40.0)] * active.size
    else:
        x0 = h[active].copy()

        def f(x):
            hh = h.copy()
            hh[active] = np.clip(x, 0.0, None)
            val, g = _fun_grad_tie(hh)
            return val, g[active]
        bounds = [(0.0, None)] * active.size

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=bounds, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    if logit:
        h2[active] = np.exp(np.clip(res.x, -40.0, 40.0))
    else:
        h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _upsample(h, n):
    if h.size == n:
        return h.copy()
    x_old = np.linspace(0.0, 1.0, h.size)
    x_new = np.linspace(0.0, 1.0, n)
    return _rescale(np.clip(np.interp(x_new, x_old, h), 0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    N = best.size
    print("base R=%.12f (N=%d)" % (bestR, N))

    # --- Phase 1: upsample to a denser grid, then full log-space polish ---
    # More steps allow a sharper shape; the peak region gets refined.
    target_N = min(400000, max(N * 3, 200000))
    if time.process_time() < deadline - 8.0:
        cand = _upsample(best, target_N)
        r0 = R_of(cand)
        print("upsampled to N=%d R=%.12f" % (cand.size, r0))
        if r0 > bestR - 1e-9:
            best, bestR = cand, r0

    # --- Phase 2: repeated full-array log-space L-BFGS polish ---
    outer = 0
    while time.process_time() < deadline - 5.0:
        outer += 1
        tlim = min(deadline - 5.0, time.process_time() + 8.0)
        cand = _lbfgs_block(best, np.arange(best.size), 400, tlim, logit=True)
        r = R_of(cand)
        print("full polish %d: R=%.12f" % (outer, r))
        if r > bestR + 1e-15:
            best, bestR = cand, r
        else:
            if outer >= 2:
                break
            best, bestR = cand, r

    # --- Phase 3: window descent on overlapping windows ---
    N = best.size
    W = 256
    if N <= W:
        win_starts = [0]
        W = N
    else:
        win_starts = list(range(0, N - W + 1, max(1, W // 2)))
        if win_starts[-1] + W < N:
            win_starts.append(N - W)

    rng = np.random.RandomState(999)
    accepted = 0
    outer = 0
    while time.process_time() < deadline - 2.0:
        outer += 1
        order = rng.permutation(len(win_starts))
        any_accept = False
        for oi in order:
            if time.process_time() >= deadline - 2.0:
                break
            w0 = win_starts[oi]
            free = np.arange(w0, min(N, w0 + W))
            tlim = min(deadline - 2.0, time.process_time() + 0.4)
            cand = _lbfgs_block(best, free, 50, tlim, logit=False)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best, bestR = cand, r
                accepted += 1
                any_accept = True
        if not any_accept:
            break
    print("window descent accepted=%d outer=%d R=%.12f" % (accepted, outer, bestR))

    # --- Phase 4: peak-window log-space polish ---
    for pad in (0.05, 0.02):
        if time.process_time() >= deadline - 0.3:
            break
        Lf = _knots(best)
        mx = Lf.max()
        idx = np.flatnonzero(Lf >= 0.999 * mx)
        if idx.size == 0:
            continue
        lo = max(0, idx.min() - 1)
        hi = min(best.size - 1, idx.max())
        span = hi - lo
        p = max(128, int(span * pad))
        lo = max(0, lo - p)
        hi = min(best.size - 1, hi + p)
        win = np.arange(lo, hi + 1)
        ht = _lbfgs_block(best, win, 300,
                          min(deadline - 0.2, time.process_time() + 2.0), logit=True)
        r = R_of(ht)
        print("peak polish pad=%.2f R=%.12f" % (pad, r))
        if r > bestR + 1e-15:
            best, bestR = ht, r

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))
    return {"best": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, maxiter, deadline, free=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        active = np.arange(n)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _resample(h, newN):
    n = h.size
    if n == newN:
        return h.copy()
    old_edges = np.arange(n + 1) / n
    new_edges = np.arange(newN + 1) / newN
    cum = np.concatenate(([0.0], np.cumsum(h)))
    cm_new = np.interp(new_edges, old_edges, cum)
    mass = np.diff(cm_new)
    return np.clip(mass * newN, 0.0, None)


def _smooth_resample(h, newN, sigma=0.5):
    """Resample with slight smoothing to reduce staircase artifacts."""
    r = _resample(h, newN)
    if newN > 8 and sigma > 0:
        k = max(1, int(3 * sigma))
        x = np.arange(-k, k + 1)
        w = np.exp(-0.5 * (x / sigma) ** 2)
        w /= w.sum()
        r = np.convolve(r, w, mode='same')
    return np.clip(r, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(1234567)

    def time_left():
        return deadline - time.process_time()

    best = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            best = np.clip(s, 0, None).copy()
            best_R = R_of(best)

    if best is None:
        N = 512
        x = (np.arange(N) + 0.5) / N
        best = np.exp(-((x - 0.5) ** 2) / 0.02) + 0.01
        best = _rescale(best)
        best_R = R_of(best)

    print("Start R:", best_R, "N=", best.size)

    # Phase 1: polish at own resolution
    h = _lbfgs(best, maxiter=500, deadline=deadline)
    if R_of(h) > best_R:
        best, best_R = h, R_of(h)
    print("After polish:", best_R, "N=", best.size)

    # Phase 2: progressive refinement with geometric growth
    n = best.size
    # First, aggressive upsampling: keep pushing N upward
    while time_left() > budget_seconds * 0.15 and n < 200000:
        n = min(int(n * 2), 200000)
        if n > best.size:
            h = _resample(best, n)
            h = _rescale(h)
            h = _lbfgs(h, maxiter=400,
                       deadline=min(deadline, time.process_time() + max(2.0, time_left() * 0.4)))
            r = R_of(h)
            if r > best_R:
                best, best_R = h, r
            print("Refine N=", n, "R=", best_R)

    # Phase 3: multi-scale refinement with smoothing; try to break out
    # of the exact piecewise-constant grid symmetry by working at higher N
    # with different smoothing widths.
    attempts = 0
    while time_left() > 1.5 and attempts < 30:
        attempts += 1
        # Choose a target N: sometimes refine, sometimes stay
        cur_n = best.size
        if cur_n < 40000 and rng.random() < 0.5:
            target_n = min(int(cur_n * rng.uniform(1.3, 2.5)), 100000)
        elif cur_n < 100000 and rng.random() < 0.3:
            target_n = min(int(cur_n * rng.uniform(1.1, 1.6)), 100000)
        else:
            target_n = cur_n

        if target_n != cur_n:
            sigma = rng.uniform(0.0, 0.8)
            h = _smooth_resample(best, target_n, sigma=sigma)
        else:
            h = best.copy()

        h = _rescale(h)
        # random perturbation: jitter heights in a window
        nn = h.size
        if rng.random() < 0.7:
            # jitter near the peak of f*f
            L = _conv(h)
            idx = int(np.argmax(L))
            hi = min(nn, max(1, idx))
            win = max(4, nn // 30)
            lo = max(0, hi - win)
            up = min(nn, hi + win)
            scale = rng.uniform(0.0005, 0.02)
            h[lo:up] *= (1.0 + rng.normal(0, scale, size=up - lo))
        if rng.random() < 0.5:
            k = max(1, nn // 30)
            pos = rng.integers(0, nn, size=k)
            h[pos] *= (1.0 + rng.normal(0, 0.01, size=k))
        h = np.clip(h, 0, None)
        h = _rescale(h)

        # Polish with most of remaining time budget
        frac = rng.uniform(0.3, 0.6)
        h = _lbfgs(h, maxiter=300,
                   deadline=min(deadline, time.process_time() + max(1.0, time_left() * frac)))

        r = R_of(h)
        if r > best_R + 1e-12:
            best, best_R = h, r
            print("Improved R=", best_R, "N=", best.size)

    # Final polish at best resolution
    if time_left() > 0.5:
        h = _lbfgs(best, maxiter=300, deadline=deadline)
        if R_of(h) > best_R:
            best, best_R = h, R_of(h)

    best = np.clip(best, 0, None)
    if best.sum() <= 0:
        best = np.ones(50)

    final_R = R_of(best)
    print("Final R:", final_R, "N=", best.size)

    if start is not None:
        sr = R_of(np.asarray(start, dtype=float))
        if sr > final_R:
            return {"best": np.asarray(start, dtype=float), "alternative": best}
    return best

