    act = np.flatnonzero(h > 0)
    if kind == 0:
        if act.size:
            h[act] = h[act] * np.exp(0.02 * rng.standard_normal(act.size))
    elif kind == 1:
        if act.size:
            h[act] = h[act] * np.exp(0.05 * rng.standard_normal(act.size))
    elif kind == 2:
        k = max(1, int(0.02 * n))
        sel = rng.choice(n, size=min(k, n), replace=False)
        amp = rng.uniform(0.05, 0.3) * h0.mean()
        h[sel] = amp * rng.uniform(0.5, 1.5, sel.size)
    elif kind == 3:
        hc = _coarsen(h, 4)
        h = _prolongate(hc, n)
    return _rescale(np.clip(h, 0, None))


def _window_lbfgs(h, deadline, frac=0.05, pad=20, maxiter=300):
    mask = _peak_mask(h, frac=frac, pad=pad)
    return _lbfgs_custom(h, _fun_grad_tie, deadline, maxiter=maxiter, mask=mask)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(20240517)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    print("base R=%.12f (N=%d)" % (startR, h0.size))

    best = h0.copy()
    bestR = startR
    alt = None

    # Phase 1: quick tie-breaking full descent on start
    tlim = min(deadline - 0.5, time.process_time() + 3.0)
    cand = _full_lbfgs(best, tlim, maxiter=200)
    rc = R_of(cand)
    if rc > bestR + 1e-15:
        best = cand; bestR = rc
        print("seed full R=%.12f" % bestR)

    # Phase 2: alternate full-array and peak-window descents, with
    # occasional coarsen/prolongate escapes. Keep going to the deadline.
    stall = 0
    pass_idx = 0
    while time.process_time() < deadline - 0.3:
        remaining = deadline - time.process_time()
        prevR = bestR
        if pass_idx % 3 == 0:
            tlim = min(deadline - 0.2, time.process_time() + remaining * 0.55)
            cand = _full_lbfgs(best, tlim, maxiter=400)
            tag = "full"
        else:
            # window around peak, varying width to shake free of ties
            frac = 0.03 if pass_idx % 2 == 1 else 0.08
            pad = 20 + 10 * (pass_idx % 3)
            tlim = min(deadline - 0.2, time.process_time() + remaining * 0.55)
            cand = _window_lbfgs(best, tlim, frac=frac, pad=pad, maxiter=400)
            tag = "win%d" % pass_idx
        rc = R_of(cand)
        if rc > bestR + 1e-15:
            best = cand; bestR = rc
            print("%s R=%.12f (+%.2e)" % (tag, bestR, bestR - prevR))
        if bestR - prevR < 1e-8:
            stall += 1
        else:
            stall = 0
        if stall >= 3:
            # escape via coarsen/prolongate
            n = best.size
            hc = _coarsen(best, 4)
            cand = _prolongate(hc, n)
            tlim = min(deadline - 0.2, time.process_time() + remaining * 0.5)
            cand = _full_lbfgs(cand, tlim, maxiter=300)
            rc = R_of(cand)
            if rc > bestR + 1e-15:
                if alt is None or rc > R_of(alt):
                    alt = best.copy()
                best = cand; bestR = rc
                print("escape R=%.12f" % bestR)
            stall = 0
        pass_idx += 1

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    if alt is None:
        # provide a genuinely different alternative: coarsened variant
        n = best.size
        hc = _coarsen(best, 4)
        alt = _prolongate(hc, n)
        if np.array_equal(alt, best):
            alt = h0.copy()

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))
    return {"best": best, "alternative": alt}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150, mask=None):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    if mask is None:
        pos = np.flatnonzero(h > 0)
    else:
        pos = np.flatnonzero((h > 0) & mask)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.05)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _coarsen(h, fac):
    n = h.size
    m = n // fac
    if m < 1:
        return h.copy()
    hh = h[:m * fac].reshape(m, fac).sum(axis=1)
    return _rescale(hh)


def _prolongate(hc, n):
    x_old = np.linspace(0.0, 1.0, hc.size)
    x_new = np.linspace(0.0, 1.0, n)
    return _rescale(np.clip(np.interp(x_new, x_old, hc), 0, None))


def _peak_mask(h, frac=0.05, pad=20):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return np.zeros(h.size, dtype=bool)
    idx = np.flatnonzero(L >= mx * (1.0 - frac))
    if idx.size == 0:
        return np.zeros(h.size, dtype=bool)
    lo = max(0, int(idx[0]) - 1 - pad)
    hi = min(h.size, int(idx[-1]) - 1 + pad + 1)
    mask = np.zeros(h.size, dtype=bool)
    mask[lo:hi] = True
    return mask


def _perturb(h0, rng, kind):
    h = h0.copy()
    n = h.size
    act = np.flatnonzero(h > 0)
    if kind == 0:
        if act.size:
            h[act] = h[act] * np.exp(0.02 * rng.standard_normal(act.size))
    elif kind == 1:
        if act.size:
            h[act] = h[act] * np.exp(0.05 * rng.standard_normal(act.size))
    elif kind == 2:
        k = max(1, int(0.02 * n))
        sel = rng.choice(n, size=min(k, n), replace=False)
        amp = rng.uniform(0.05, 0.3) * h0.mean()
        h[sel] = amp * rng.uniform(0.5, 1.5, sel.size)
    elif kind == 3:
        hc = _coarsen(h, 4)
        h = _prolongate(hc, n)
    return _rescale(np.clip(h, 0, None))


def _window_lbfgs(h, deadline, frac=0.05, pad=20, maxiter=300):
    mask = _peak_mask(h, frac=frac, pad=pad)
    return _lbfgs_custom(h, _fun_grad_tie, deadline, maxiter=maxiter, mask=mask)


