import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _sq_param_lbfgs(c0, maxiter, deadline, beta=0.0, cap=None):
    if time.process_time() >= deadline - 0.3:
        return c0
    c0 = np.clip(c0, 0.0, None)
    if c0.sum() <= 0:
        return c0
    if cap is None:
        cap = max(c0.max(), 1e-12) * 4.0
    x0 = np.sqrt(np.clip(c0, 0.0, cap))
    lim = np.sqrt(cap)
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        c = np.clip(x, 0.0, None) ** 2
        val, g = fg(c)
        return val, g * (2.0 * np.clip(x, 0.0, None))

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(-lim, lim)] * x0.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return c0
    if res is None:
        return c0
    c = np.clip(res.x, 0.0, None) ** 2
    return _rescale(c)


def _sq_polish_full(h, deadline, maxiter=150):
    cur = h
    for beta in [1e6, 1e7, 0.0]:
        if time.process_time() >= deadline - 0.4:
            break
        ht = _sq_param_lbfgs(cur, maxiter, deadline - 0.3, beta=beta)
        if R_of(ht) >= R_of(cur) - 1e-15:
            cur = ht
    return cur


def _inject_mass(h, frac=0.05, scale=1e-3, rng=None):
    if rng is None:
        rng = np.random.RandomState()
    h = h.copy()
    zeros = np.flatnonzero(h <= 0)
    if zeros.size == 0:
        return h
    k = max(1, int(frac * zeros.size))
    if k >= zeros.size:
        sel = zeros
    else:
        sel = rng.choice(zeros, size=k, replace=False)
    mx = h.max()
    if mx <= 0:
        return h
    h[sel] += scale * mx
    return _rescale(h)


def _coarsen_blocksum(h, s, o):
    idx = np.arange(o, h.size, s)
    if idx.size == 0:
        return None
    return h[idx].copy()


def _prolongate(h_best, c, s, o):
    h_new = h_best.copy()
    idx = np.arange(o, h_new.size, s)
    L = min(idx.size, c.size)
    h_new[idx[:L]] = c[:L]
    return _rescale(np.clip(h_new, 0, None))


def _shift_polish(h, maxshift, maxiter, deadline, beta=1e7):
    """Try small integer shifts of the support; keep best."""
    best = h; bestR = R_of(h)
    if maxshift <= 0:
        return best
    n = h.size
    for d in range(1, maxshift + 1):
        if time.process_time() >= deadline - 0.5:
            break
        for sign in (1, -1):
            if time.process_time() >= deadline - 0.5:
                break
            hs = np.zeros_like(h)
            if sign > 0:
                hs[d:] = h[:n - d]
            else:
                hs[:n - d] = h[d:]
            ht = _lbfgs_all_pos(hs, maxiter, deadline - 0.3, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht, r
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0
    rng = np.random.RandomState(2024)

    N = best.size

    # ---- NEW Phase A: integer shift / support-position search ----
    # The main idea: the current support placement may be slightly off.  Small
    # shifts + re-polish can find a better basin before the expensive cycles.
    shift_end = min(deadline - 2.0, time.process_time() + 0.15 * budget_seconds)
    if N >= 8:
        ht = _shift_polish(best, maxshift=6, maxiter=120, deadline=shift_end)
        r = R_of(ht)
        print("shift polish R=%.9f (best %.9f)" % (r, bestR))
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, 'shift'
            print("  SHIFT NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase B: squared-param offset/odd coarsening cycles ----
    cycle_end = deadline - 2.0
    cyc = 0
    if N >= 6:
        while time.process_time() < cycle_end - 1.0:
            cyc += 1
            now = time.process_time()
            slice_dl = min(cycle_end, now + 0.10 * budget_seconds)
            if slice_dl <= now + 0.5:
                break
            s = 2 if (cyc % 2 == 1) else 3
            o = cyc % s
            c0 = _coarsen_blocksum(best, s, o)
            if c0 is None or c0.size < 4:
                continue
            c = c0.copy()
            for beta in [1e6, 1e7, 0.0]:
                if time.process_time() >= slice_dl - 0.5:
                    break
                ct = _sq_param_lbfgs(c, 150, slice_dl - 0.3, beta=beta)
                if R_of(ct) >= R_of(c) - 1e-15:
                    c = ct
            cR = R_of(c)
            hnew = _prolongate(best, c, s, o)
            hnew = _inject_mass(hnew, frac=0.05, scale=1e-3, rng=rng)
            ht = _sq_polish_full(hnew, slice_dl, maxiter=150)
            r = R_of(ht)
            if time.process_time() < slice_dl - 0.5:
                win = _peak_window(ht, pad_frac=0.10, extra=128)
                ht2 = _lbfgs_block(ht, win, 200, slice_dl - 0.3, beta=1e7)
                r2 = R_of(ht2)
                if r2 > r:
                    ht, r = ht2, r2
            zeros = float(np.mean(ht <= 0))
            print("cyc %d s=%d o=%d R(c)=%.9f liftR=%.9f zeros=%.3f (best %.9f)" %
                  (cyc, s, o, cR, r, zeros, bestR))
            if r > bestR + 1e-14:
                best, bestR, origin = ht.copy(), r, 'sq_s%d_o%d_cy%d' % (s, o, cyc)
                print("  SQ NEW BEST R=%.9f zeros=%.3f" % (bestR, zeros))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # ---- Phase C: peak-window + beta=0 polish ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            ht2 = _lbfgs_block(best, win, 400, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("peak polish NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    zeros_final = float(np.mean(best <= 0))
    print("final R=%.9f origin=%s zeros=%.3f (start %.9f, N=%d)" %
          (bestR, origin, zeros_final, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h, beta=None):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    if beta is None:
        idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
        w = 1.0 / idx.size
        gLf[idx] += w / Lm
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    else:
        # soft-max style sharpening
        e = np.exp(beta * (Lf - mx))
        Z = e.sum()
        p = e / Z
        gLf += beta * p / Lm
        val = -np.log(num) + 2.0 * np.log(s) + (np.log(Z) / beta + mx) / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=400, mask=None, beta=None):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    if mask is None:
        pos = np.flatnonzero(h > 0)
    else:
        pos = np.flatnonzero((h > 0) & mask)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh, beta)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.02)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _peak_mask(h, frac=0.90, widen=0.10):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return np.zeros(h.size, dtype=bool)
    idx = np.flatnonzero(L >= mx * frac)
    if idx.size == 0:
        return np.zeros(h.size, dtype=bool)
    lo = int(idx[0]); hi = int(idx[-1])
    span = hi - lo
    pad = max(1, int(widen * span))
    lo = max(0, lo - 1 - pad)
    hi = min(h.size, hi - 1 + pad + 1)
    mask = np.zeros(h.size, dtype=bool)
    mask[lo:hi] = True
    return mask


def _prolongate2x(h):
    n = h.size
    x_old = np.linspace(0.0, 1.0, n)
    x_new = np.linspace(0.0, 1.0, 2 * n)
    return _rescale(np.clip(np.interp(x_new, x_old, h), 0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
        else:
            best = None
    else:
        best = None

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        best = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(best)
    bestR = startR
    print("base R=%.12f (N=%d)" % (startR, best.size))

    last_improved = 0
    it = 0
    upsampled = False

    while time.process_time() < deadline - 0.3:
        it += 1
        improved = False

        # (a) full-array descent
        if time.process_time() < deadline - 0.3:
            cand = _lbfgs_custom(best, _fun_grad_tie, deadline, maxiter=400,
                                 mask=None, beta=None)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best = cand; bestR = r; improved = True
                print("a R=%.12f (+%.2e) it=%d" % (bestR, bestR - r + (r - bestR), it))

        # (b) peak-window descent
        if time.process_time() < deadline - 0.3:
            mask = _peak_mask(best, frac=0.90, widen=0.10)
            cand = _lbfgs_custom(best, _fun_grad_tie, deadline, maxiter=400,
                                 mask=mask, beta=None)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best = cand; bestR = r; improved = True
                print("b R=%.12f it=%d" % (bestR, it))

        # (c) beta-sharpening polish
        if time.process_time() < deadline - 0.3:
            for beta in (1e4, 1e5, 1e6):
                if time.process_time() >= deadline - 0.3:
                    break
                cand = _lbfgs_custom(best, _fun_grad_tie, deadline, maxiter=200,
                                     mask=None, beta=beta)
                r = R_of(cand)
                if r > bestR + 1e-15:
                    best = cand; bestR = r; improved = True
                    print("c R=%.12f beta=%.0e it=%d" % (bestR, beta, it))

        if improved:
            last_improved = it
        else:
            # small perturbation escape
            if time.process_time() < deadline - 0.3:
                rng = np.random.default_rng(12345 + it)
                h = best.copy()
                act = np.flatnonzero(h > 0)
                if act.size:
                    h[act] = h[act] * np.exp(0.01 * rng.standard_normal(act.size))
                h = _rescale(np.clip(h, 0, None))
                cand = _lbfgs_custom(h, _fun_grad_tie, deadline, maxiter=200,
                                     mask=None, beta=None)
                r = R_of(cand)
                if r > bestR + 1e-15:
                    best = cand; bestR = r; improved = True
                    last_improved = it
                    print("pert R=%.12f it=%d" % (bestR, it))

        # upsampling at 80% of budget
        if (not upsampled) and time.process_time() > t0 + 0.80 * budget_seconds:
            if it - last_improved <= 3:
                upsampled = True
                if best.size < 500000 and time.process_time() < deadline - 2.0:
                    h2 = _prolongate2x(best)
                    cand = _lbfgs_custom(h2, _fun_grad_tie, deadline, maxiter=400,
                                         mask=None, beta=None)
                    r = R_of(cand)
                    if r > bestR + 1e-15:
                        best = cand; bestR = r
                        print("upsample R=%.12f N=%d" % (bestR, best.size))
                    else:
                        # try peak-window at fine grid anyway
                        mask = _peak_mask(h2, frac=0.90, widen=0.10)
                        cand = _lbfgs_custom(h2, _fun_grad_tie, deadline, maxiter=400,
                                             mask=mask, beta=None)
                        r = R_of(cand)
                        if r > bestR + 1e-15:
                            best = cand; bestR = r
                            print("upsample-peak R=%.12f N=%d" % (bestR, best.size))
            else:
                upsampled = True

        if it - last_improved > 8 and time.process_time() > deadline - 2.0:
            break

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_pnorm(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lp = np.clip(Lf, 0, None) ** p
    S = Lp.sum()
    if S <= 0:
        return _fun_grad(h)
    sm = S ** (1.0 / p)
    w = (np.clip(Lf, 0, None) ** (p - 1)) / S
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lc = np.clip(Lf, 0, None)
    mx = Lc.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lc - mx))
    S = e.sum()
    if S <= 0:
        return _fun_grad(h)
    sm = mx + np.log(S) / beta
    w = e / S
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, p=0, beta=0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif p > 0:
        fg = (lambda hh: _fun_grad_pnorm(hh, p))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, p=0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_pnorm(hh, p)) if p > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.08):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    w = max(64, int(frac * n))
    lo = max(0, m - w)
    hi = min(n, m + w)
    return np.arange(lo, hi)


def _revive_zeros(h, frac=0.15, scale=1e-3, win=512):
    n = h.size
    out = h.copy()
    zones = [(0, int(frac * n)), (int((1.0 - frac) * n), n)]
    cs = np.concatenate(([0.0], np.cumsum(out)))
    for lo, hi in zones:
        if hi <= lo:
            continue
        seg = out[lo:hi]
        zeros = np.flatnonzero(seg == 0.0)
        if zeros.size == 0:
            continue
        for z in zeros:
            a = max(0, lo + z - win // 2)
            b = min(n, lo + z + win // 2)
            m = (cs[b] - cs[a]) / max(1, b - a)
            if m > 0:
                out[lo + z] = scale * m
    return out


def _prune(h, q):
    n = h.size
    k = int(round(q * n))
    if k <= 0:
        return h.copy()
    if k >= n:
        k = n - 1
    idx = np.argsort(h)
    out = h.copy()
    out[idx[:k]] = 0.0
    return out


def _coarsen(h, k):
    n = h.size
    m = n // k
    if m < 1:
        return h.copy()
    hh = h[:m * k].reshape(m, k)
    return hh.mean(axis=1)


def _prolongate(h, k, N):
    hb = np.repeat(h, k)
    if hb.size < N:
        pad = N - hb.size
        hb = np.concatenate((hb, np.zeros(pad)))
    else:
        hb = hb[:N]
    return _rescale(hb / np.sqrt(k))


def _smooth_upsample(h, n):
    """Linear-interp upsample, then rescale (smoother than repeat)."""
    x_old = np.linspace(0.0, 1.0, h.size)
    x_new = np.linspace(0.0, 1.0, n)
    return _rescale(np.clip(np.interp(x_new, x_old, h), 0, None))


def _local_sweep(h, deadline, passes=4, blk_frac=1/300.):
    """Coordinate block multiplicative sweep on the highest-impact region."""
    h = h.copy()
    bestR = R_of(h)
    n = h.size
    if n == 0:
        return h, bestR
    rng = np.random.RandomState(1234)
    factors = np.array([0.9, 0.95, 0.98, 1.02, 1.05, 1.1])
    blk = max(1, int(n * blk_frac))
    for _ in range(passes):
        if time.process_time() > deadline:
            break
        improved = False
        order = rng.permutation((n + blk - 1) // blk)
        for bi in order:
            if time.process_time() > deadline:
                break
            lo = bi * blk
            hi = min(n, lo + blk)
            cur = h[lo:hi].copy()
            curR = bestR
            bestf = 1.0
            for f in factors:
                h[lo:hi] = cur * f
                r = R_of(h)
                if r > curR:
                    curR = r; bestf = f
            h[lo:hi] = cur * bestf
            if bestf != 1.0:
                bestR = curR
                improved = True
        if not improved:
            break
    return h, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    print("base R=%.7f (N=%d)" % (start_bestR, start_best.size))

    best = start_best.copy()
    bestR = start_bestR
    alt = None
    altR = -1.0

    def _record(h, tag):
        nonlocal best, bestR, alt, altR
        h = _rescale(h)
        r = R_of(h)
        zf = float(np.mean(h == 0.0))
        mm = float(h.max() / max(h.mean(), 1e-300))
        Lf = _knots(h)
        near = float(np.mean(Lf >= 0.999 * Lf.max()))
        print("%s R=%.9f N=%d zero=%.3f max/mean=%.2f near=%.4f"
              % (tag, r, h.size, zf, mm, near))
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
        elif r > altR:
            alt, altR = h.copy(), r
        return r

    N0 = start_best.size

    # ---- Stage A: coarsest level k=8 ----
    h8 = _rescale(_coarsen(start_best, 8))
    print("coarsen k=8 R=%.9f N=%d" % (R_of(h8), h8.size))
    h8 = _lbfgs_log(h8, 300, deadline)
    if time.process_time() < deadline - 1.0:
        hp = _prune(h8, 0.15)
        hp = _revive_zeros(hp, frac=0.20, scale=1e-3)
        hp = _rescale(hp)
        hp = _lbfgs_log(hp, 100, deadline)
        hp = _rescale(hp)
        if R_of(hp) > R_of(h8):
            h8 = hp
    for beta in (1e2, 1e4):
        if time.process_time() >= deadline - 1.0:
            break
        hc = _lbfgs_log(h8, 80, deadline, beta=beta)
        if R_of(hc) > R_of(h8):
            h8 = hc
    if time.process_time() < deadline - 1.0:
        free = _peak_window(h8, 0.10)
        hc = _lbfgs_block(h8, free, 100, deadline)
        if R_of(hc) > R_of(h8):
            h8 = hc
    h8, r8 = _local_sweep(_rescale(h8), deadline, passes=2)
    h8 = _rescale(h8)
    print("L8 R=%.9f zero=%.3f" % (R_of(h8), float(np.mean(h8 == 0.0))))
    _record(h8, "L8")

    # ---- Stage B: prolongate to N=42496 ----
    N4 = 4 * h8.size
    h4 = _prolongate(h8, 2, N4)
    print("prol->L4 R=%.9f N=%d" % (R_of(h4), h4.size))
    _record(h4, "prol-L4")
    h4 = _lbfgs_log(h4, 200, deadline)
    if time.process_time() < deadline - 1.0:
        hc = _lbfgs_log(h4, 80, deadline, beta=1e4)
        if R_of(hc) > R_of(h4):
            h4 = hc
    if time.process_time() < deadline - 1.0:
        free = _peak_window(h4, 0.08)
        hc = _lbfgs_block(h4, free, 80, deadline)
        if R_of(hc) > R_of(h4):
            h4 = hc
    if time.process_time() < deadline - 1.0:
        hp = _prune(h4, 0.10)
        hp = _revive_zeros(hp, frac=0.20, scale=1e-3)
        hp = _rescale(hp)
        hp = _lbfgs_log(hp, 80, deadline)
        hp = _rescale(hp)
        if R_of(hp) > R_of(h4):
            h4 = hp
    h4 = _rescale(h4)
    print("L4 R=%.9f zero=%.3f" % (R_of(h4), float(np.mean(h4 == 0.0))))
    _record(h4, "L4")

    # ---- Stage C: prolongate to N=84992 ----
    N2 = 2 * h4.size
    h2 = _prolongate(h4, 2, N2)
    print("prol->L2 R=%.9f N=%d" % (R_of(h2), h2.size))
    _record(h2, "prol-L2")
    h2 = _lbfgs_log(h2, 200, deadline)
    if time.process_time() < deadline - 1.0:
        hc = _lbfgs_log(h2, 80, deadline, beta=1e4)
        if R_of(hc) > R_of(h2):
            h2 = hc
    if time.process_time() < deadline - 1.0:
        free = _peak_window(h2, 0.08)
        hc = _lbfgs_block(h2, free, 80, deadline)
        if R_of(hc) > R_of(h2):
            h2 = hc
    if time.process_time() < deadline - 1.0:
        hp = _prune(h2, 0.10)
        hp = _revive_zeros(hp, frac=0.20, scale=1e-3)
        hp = _rescale(hp)
        hp = _lbfgs_log(hp, 80, deadline)
        hp = _rescale(hp)
        if R_of(hp) > R_of(h2):
            h2 = hp
    h2 = _rescale(h2)
    print("L2 R=%.9f zero=%.3f" % (R_of(h2), float(np.mean(h2 == 0.0))))
    _record(h2, "L2")

    # ---- Stage D: prolongate to N=N0 and alternate ----
    h1 = _prolongate(h2, 2, N0)
    print("prol->L1 R=%.9f N=%d" % (R_of(h1), h1.size))
    _record(h1, "prol-L1")

    cand = h1.copy()
    candR = R_of(cand)
    if candR < bestR:
        cand, candR = best.copy(), bestR

    while time.process_time() < deadline - 0.7:
        improved = False
        if time.process_time() < deadline - 0.7:
            hc = _lbfgs_log(cand, 150, deadline)
            r = R_of(hc)
            if r > candR + 1e-13:
                cand, candR = hc, r
                improved = True
                _record(hc, "d-b0")
        if time.process_time() < deadline - 0.7:
            hc = _lbfgs_log(cand, 100, deadline, beta=1e5)
            r = R_of(hc)
            if r > candR + 1e-13:
                cand, candR = hc, r
                improved = True
                _record(hc, "d-b1e5")
        for pf in (0.05, 0.15):
            if time.process_time() >= deadline - 0.7:
                break
            free = _peak_window(cand, pf)
            hc = _lbfgs_block(cand, free, 80, deadline)
            r = R_of(hc)
            if r > candR + 1e-13:
                cand, candR = hc, r
                improved = True
                _record(hc, "d-pk%.2f" % pf)
        # NEW: local multiplicative sweep on the fine level
        if time.process_time() < deadline - 0.7:
            hs, rs = _local_sweep(cand, deadline - 0.7, passes=1)
            if rs > candR + 1e-13:
                cand, candR = hs, rs
                improved = True
                _record(hs, "d-sweep")
        if not improved:
            break

    _record(cand, "final")

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h, beta=None):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    if beta is None:
        idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
        w = 1.0 / idx.size
        gLf[idx] += w / Lm
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    else:
        e = np.exp(beta * (Lf - mx))
        Z = e.sum()
        p = e / Z
        gLf += beta * p / Lm
        val = -np.log(num) + 2.0 * np.log(s) + (np.log(Z) / beta + mx) / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _fun_grad_flat_top(h, tau=0.9, kappa=10.0):
    # variance surrogate: penalise knots above tau*max, encouraging flat top
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    thresh = tau * mx
    excess = np.clip(Lf - thresh, 0, None)
    var = np.sum(excess * excess)
    gLf += kappa * 2.0 * excess / (var + 1e-12) * (var / (var + 1e-12))
    # simpler: gradient of log(var+eps)
    gLf = -dq / num + kappa * 2.0 * excess / (var + 1e-12)
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm) + kappa * np.log(var + 1e-12)
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=400, mask=None, beta=None,
                  tau=None, kappa=None):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    if mask is None:
        pos = np.flatnonzero(h > 0)
    else:
        pos = np.flatnonzero((h > 0) & mask)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        if tau is not None:
            val, g = fun_grad(hh, tau, kappa)
        else:
            val, g = fun_grad(hh, beta)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.02)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _peak_mask(h, frac=0.90, widen=0.10):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return np.zeros(h.size, dtype=bool)
    idx = np.flatnonzero(L >= mx * frac)
    if idx.size == 0:
        return np.zeros(h.size, dtype=bool)
    lo = int(idx[0]); hi = int(idx[-1])
    span = hi - lo
    pad = max(1, int(widen * span))
    lo = max(0, lo - 1 - pad)
    hi = min(h.size, hi - 1 + pad + 1)
    mask = np.zeros(h.size, dtype=bool)
    mask[lo:hi] = True
    return mask


def _prolongate2x(h):
    n = h.size
    x_old = np.linspace(0.0, 1.0, n)
    x_new = np.linspace(0.0, 1.0, 2 * n)
    return _rescale(np.clip(np.interp(x_new, x_old, h), 0, None))


# ---- phases: each returns candidate array given current best + deadline ----

def phase_a(best, deadline, alloc):
    return _lbfgs_custom(best, _fun_grad_tie, deadline, maxiter=400,
                         mask=None, beta=None)


def phase_b(best, deadline, alloc):
    mask = _peak_mask(best, frac=0.90, widen=0.10)
    return _lbfgs_custom(best, _fun_grad_tie, deadline, maxiter=400,
                         mask=mask, beta=None)


def phase_c(best, deadline, alloc):
    h = best
    for tau, kappa in ((0.7, 1.0), (0.8, 10.0), (0.9, 100.0)):
        if time.process_time() >= deadline - 0.1:
            break
        h = _lbfgs_custom(h, _fun_grad_flat_top, deadline, maxiter=200,
                          mask=None, tau=tau, kappa=kappa)
    if time.process_time() < deadline - 0.1:
        h = _lbfgs_custom(h, _fun_grad_tie, deadline, maxiter=400,
                          mask=None, beta=None)
    return h


def phase_d(best, deadline, alloc):
    h = best
    for beta in (1e4, 1e6):
        if time.process_time() >= deadline - 0.1:
            break
        h = _lbfgs_custom(h, _fun_grad_tie, deadline, maxiter=200,
                          mask=None, beta=beta)
    return h


def phase_e(best, deadline, alloc):
    if best.size >= 500000:
        return best
    h2 = _prolongate2x(best)
    h2 = _lbfgs_custom(h2, _fun_grad_tie, deadline, maxiter=400,
                       mask=None, beta=None)
    if time.process_time() < deadline - 0.1:
        mask = _peak_mask(h2, frac=0.90, widen=0.10)
        h2 = _lbfgs_custom(h2, _fun_grad_tie, deadline, maxiter=400,
                           mask=mask, beta=None)
    return h2


PHASES = [('a', phase_a), ('b', phase_b), ('c', phase_c),
          ('d', phase_d), ('e', phase_e)]


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    reserve = t0 + budget_seconds * 0.80  # last 20% reserved

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
        else:
            best = None
    else:
        best = None

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        best = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(best)
    bestR = startR
    print("base R=%.12f (N=%d)" % (startR, best.size))

    # ---- probe each phase for ~4s from current best ----
    probe_alloc = 4.0
    rate = {name: 0.0 for name, _ in PHASES}
    alloc = {name: probe_alloc for name, _ in PHASES}

    for name, fn in PHASES:
        if time.process_time() >= reserve - 0.5:
            break
        pdeadline = min(time.process_time() + probe_alloc, reserve - 0.3)
        t_start = time.process_time()
        try:
            cand = fn(best, pdeadline, probe_alloc)
        except Exception:
            cand = best
        dt = max(1e-6, time.process_time() - t_start)
        r = R_of(cand)
        dR = r - bestR
        rate[name] = dR / dt
        if r > bestR + 1e-15:
            best = cand; bestR = r
        print("probe %s dR/s=%.3e (dR=%.3e, %.2fs)" % (name, rate[name], dR, dt))

    # ---- adaptive rounds ----
    it = 0
    while time.process_time() < reserve - 0.5:
        it += 1
        # pick phase with highest rate
        name = max(rate, key=lambda k: rate[k])
        fn = dict(PHASES)[name]
        this_alloc = min(alloc[name], max(1.0, reserve - time.process_time() - 0.5))
        pdeadline = min(time.process_time() + this_alloc, reserve - 0.3)
        t_start = time.process_time()
        try:
            cand = fn(best, pdeadline, this_alloc)
        except Exception:
            cand = best
        dt = max(1e-6, time.process_time() - t_start)
        r = R_of(cand)
        dR = r - bestR
        # exponential moving average of rate
        inst = dR / dt
        rate[name] = 0.5 * rate[name] + 0.5 * inst
        if r > bestR + 1e-15:
            best = cand; bestR = r
            alloc[name] = min(15.0, alloc[name] * 2.0)
            print("round %d win %s R=%.12f (+%.2e) alloc=%.1f" %
                  (it, name, bestR, dR, alloc[name]))
        else:
            alloc[name] = max(1.0, alloc[name] * 0.7)
            print("round %d %s no-improve (dR=%.2e) alloc=%.1f" %
                  (it, name, dR, alloc[name]))

    # ---- reserved final uninterrupted (a)+(b) ----
    if time.process_time() < deadline - 0.3:
        cand = _lbfgs_custom(best, _fun_grad_tie, deadline, maxiter=400,
                             mask=None, beta=None)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best = cand; bestR = r
            print("final-a R=%.12f" % bestR)
    if time.process_time() < deadline - 0.3:
        mask = _peak_mask(best, frac=0.90, widen=0.10)
        cand = _lbfgs_custom(best, _fun_grad_tie, deadline, maxiter=400,
                             mask=mask, beta=None)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best = cand; bestR = r
            print("final-b R=%.12f" % bestR)

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


