    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    """Smooth-tie gradient: spreads weight over all near-max knots."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-8))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fun_grad):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _upsample(h, n):
    x_old = np.linspace(0.0, 1.0, h.size)
    x_new = np.linspace(0.0, 1.0, n)
    return _rescale(np.clip(np.interp(x_new, x_old, h), 0, None))


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _polish(h, deadline, record_R):
    best = h.copy()
    bestR = R_of(best)
    if bestR < record_R - 3e-3:
        return best, bestR
    if time.process_time() < deadline - 1.0:
        hs = _lbfgs_custom(best, _fun_grad_tie, min(deadline - 0.5, time.process_time() + 4.0), 200)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 1.0:
            break
        fg = (lambda hh, b=beta: _fun_grad_beta(hh, b))
        hs = _lbfgs_custom(best, fg, min(deadline - 0.5, time.process_time() + 3.0), 150)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    for frac in (0.05, 0.15):
        if time.process_time() >= deadline - 1.0:
            break
        free = _peak_window(best, frac=frac)
        hs = _lbfgs_block(best, free, 150, min(deadline - 0.5, time.process_time() + 3.0), _fun_grad_tie)
        rs = R_of(hs)
        if rs > bestR:
            best, bestR = hs, rs
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    bestH = best.copy()
    bestRH = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Upsample the start to a finer grid; try to improve there ----
    n0 = best.size
    for factor in (2, 4):
        if time.process_time() >= deadline - 8.0:
            break
        n_new = min(1000000, n0 * factor)
        if n_new == n0:
            continue
        hu = _upsample(bestH, n_new)
        cap = min(deadline - 6.0, time.process_time() + 6.0)
        hp, rp = _polish(hu, cap, bestRH - 1e-3)
        print("  up x%d N=%d R=%.9f (best=%.9f)" % (factor, n_new, rp, bestRH))
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp.copy(), rp
            print("    NEW BEST R=%.9f" % bestRH)

    # ---- Beta-ladder polish on current best ----
    for beta in (1e2, 1e3, 1e4, 1e5, 1e6):
        if time.process_time() >= deadline - 3.0:
            break
        fg = (lambda hh, b=beta: _fun_grad_beta(hh, b))
        cap = min(deadline - 2.0, time.process_time() + 4.0)
        hs = _lbfgs_custom(bestH, fg, cap, 200)
        r_raw = R_of(hs)
        cap2 = min(deadline - 1.0, time.process_time() + 3.0)
        hp, rp = _polish(hs, cap2, bestRH - 1e-3)
        print("  beta=%.0e raw=%.9f polish=%.9f (best=%.9f)" % (beta, r_raw, rp, bestRH))
        if rp > bestRH + 1e-13:
            bestH, bestRH = hp.copy(), rp
            print("    NEW BEST R=%.9f" % bestRH)

    # ---- Final polish loop until deadline ----
    loop_end = deadline - 0.5
    it = 0
    rng = np.random.default_rng(12345)
    while time.process_time() < loop_end:
        it += 1
        cap = min(loop_end, time.process_time() + 4.0)
        hs = _lbfgs_custom(bestH, _fun_grad_tie, cap, 250)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            print("  final iter=%d R=%.9f" % (it, bestRH))
            continue
        if time.process_time() < loop_end - 1.0:
            frac = 0.04 + 0.12 * rng.random()
            free = _peak_window(bestH, frac=frac)
            cap = min(loop_end, time.process_time() + 3.0)
            hp = _lbfgs_block(bestH, free, 150, cap, _fun_grad_tie)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                print("  final peak iter=%d R=%.9f" % (it, bestRH))

    print("final R=%.9f" % bestRH)
    if bestRH > start_bestR + 1e-12:
        return {"best": bestH, "alternative": start_best}
    return {"best": start_best, "alternative": bestH}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h, beta=None):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    if beta is None:
        idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
        w = 1.0 / idx.size
        gLf[idx] += w / Lm
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    else:
        e = np.exp(beta * (Lf - mx))
        Z = e.sum()
        p = e / Z
        gLf += beta * p / Lm
        val = -np.log(num) + 2.0 * np.log(s) + (np.log(Z) / beta + mx) / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=400, mask=None, beta=None):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    if mask is None:
        pos = np.flatnonzero(h > 0)
    else:
        pos = np.flatnonzero((h > 0) & mask)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh, beta)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.02)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _peak_mask(h, frac=0.90, widen=0.10):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return np.zeros(h.size, dtype=bool)
    idx = np.flatnonzero(L >= mx * frac)
    if idx.size == 0:
        return np.zeros(h.size, dtype=bool)
    lo = int(idx[0]); hi = int(idx[-1])
    span = hi - lo
    pad = max(1, int(widen * span))
    lo = max(0, lo - 1 - pad)
    hi = min(h.size, hi - 1 + pad + 1)
    mask = np.zeros(h.size, dtype=bool)
    mask[lo:hi] = True
    return mask


def _prolongate2x(h):
    n = h.size
    x_old = np.linspace(0.0, 1.0, n)
    x_new = np.linspace(0.0, 1.0, 2 * n)
    return _rescale(np.clip(np.interp(x_new, x_old, h), 0, None))


def _coarsen_block(h, factor):
    n = h.size
    m = n // factor
    if m < 1:
        return h.copy()
    hh = h[:m * factor].reshape(m, factor).sum(axis=1)
    return _rescale(hh)


def _prolongate_lin(h, n_new):
    n = h.size
    x_old = np.linspace(0.0, 1.0, n)
    x_new = np.linspace(0.0, 1.0, n_new)
    return _rescale(np.clip(np.interp(x_new, x_old, h), 0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
        else:
            best = None
    else:
        best = None

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        best = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(best)
    bestR = startR
    print("base R=%.12f (N=%d)" % (startR, best.size))

    # ---- Phase 1: factor-4 coarsen escape ----
    phase1_end = t0 + 0.25 * budget_seconds
    if best.size >= 8 and time.process_time() < phase1_end:
        hc = _coarsen_block(best, 4)
        prof_before = hc.copy()
        cand_c = _lbfgs_custom(hc, _fun_grad_tie, min(phase1_end, deadline - 0.3),
                               maxiter=300, mask=None, beta=None)
        # measure shape movement
        if cand_c.size == prof_before.size and prof_before.sum() > 0:
            pb = prof_before / prof_before.sum()
            pc = cand_c / max(cand_c.sum(), 1e-30)
            move = float(np.abs(pb - pc).sum())
        else:
            move = 0.0
        hf = _prolongate_lin(cand_c, best.size)
        r = R_of(hf)
        print("phase1 coarsen R=%.12f (move=%.4f)" % (r, move))
        if r > bestR + 1e-15:
            best = hf; bestR = r
            print("phase1 accepted R=%.12f" % bestR)
        else:
            print("phase1 rejected")

    # ---- Phase 2: p3459 monotone loop ----
    last_improved = 0
    it = 0
    upsampled = False
    phase2_start = time.process_time()
    remaining = max(deadline - phase2_start, 0.1)

    while time.process_time() < deadline - 0.3:
        it += 1
        improved = False

        if time.process_time() < deadline - 0.3:
            cand = _lbfgs_custom(best, _fun_grad_tie, deadline, maxiter=400,
                                 mask=None, beta=None)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best = cand; bestR = r; improved = True
                print("a R=%.12f it=%d" % (bestR, it))

        if time.process_time() < deadline - 0.3:
            mask = _peak_mask(best, frac=0.90, widen=0.10)
            cand = _lbfgs_custom(best, _fun_grad_tie, deadline, maxiter=400,
                                 mask=mask, beta=None)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best = cand; bestR = r; improved = True
                print("b R=%.12f it=%d" % (bestR, it))

        if time.process_time() < deadline - 0.3:
            for beta in (1e4, 1e5, 1e6):
                if time.process_time() >= deadline - 0.3:
                    break
                cand = _lbfgs_custom(best, _fun_grad_tie, deadline, maxiter=200,
                                     mask=None, beta=beta)
                r = R_of(cand)
                if r > bestR + 1e-15:
                    best = cand; bestR = r; improved = True
                    print("c R=%.12f beta=%.0e it=%d" % (bestR, beta, it))

        if improved:
            last_improved = it
        else:
            if time.process_time() < deadline - 0.3:
                rng = np.random.default_rng(12345 + it)
                h = best.copy()
                act = np.flatnonzero(h > 0)
                if act.size:
                    h[act] = h[act] * np.exp(0.01 * rng.standard_normal(act.size))
                h = _rescale(np.clip(h, 0, None))
                cand = _lbfgs_custom(h, _fun_grad_tie, deadline, maxiter=200,
                                     mask=None, beta=None)
                r = R_of(cand)
                if r > bestR + 1e-15:
                    best = cand; bestR = r; improved = True
                    last_improved = it
                    print("pert R=%.12f it=%d" % (bestR, it))

        if (not upsampled) and time.process_time() > phase2_start + 0.80 * remaining:
            if it - last_improved <= 3:
                upsampled = True
                if best.size < 500000 and time.process_time() < deadline - 2.0:
                    h2 = _prolongate2x(best)
                    cand = _lbfgs_custom(h2, _fun_grad_tie, deadline, maxiter=400,
                                         mask=None, beta=None)
                    r = R_of(cand)
                    if r > bestR + 1e-15:
                        best = cand; bestR = r
                        print("upsample R=%.12f N=%d" % (bestR, best.size))
                    else:
                        mask = _peak_mask(h2, frac=0.90, widen=0.10)
                        cand = _lbfgs_custom(h2, _fun_grad_tie, deadline, maxiter=400,
                                             mask=mask, beta=None)
                        r = R_of(cand)
                        if r > bestR + 1e-15:
                            best = cand; bestR = r
                            print("upsample-peak R=%.12f N=%d" % (bestR, best.size))
            else:
                upsampled = True

        if it - last_improved > 8 and time.process_time() > deadline - 2.0:
            break

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))
    return best

