    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _upsample(h, n):
    x_old = np.linspace(0.0, 1.0, h.size)
    x_new = np.linspace(0.0, 1.0, n)
    return _rescale(np.clip(np.interp(x_new, x_old, h), 0, None))


def _local_sweep(h, deadline, passes=6):
    h = h.copy()
    bestR = R_of(h)
    n = h.size
    if n == 0:
        return h, bestR
    rng = np.random.RandomState(12345)
    factors = np.array([0.9, 0.95, 0.98, 1.02, 1.05, 1.1])
    blk = max(1, n // 200)
    for _ in range(passes):
        if time.process_time() > deadline:
            break
        improved = False
        order = rng.permutation((n + blk - 1) // blk)
        for bi in order:
            if time.process_time() > deadline:
                break
            lo = bi * blk
            hi = min(n, lo + blk)
            cur = h[lo:hi].copy()
            curR = bestR
            bestf = 1.0
            for f in factors:
                h[lo:hi] = cur * f
                r = R_of(h)
                if r > curR:
                    curR = r; bestf = f
            h[lo:hi] = cur * bestf
            if bestf != 1.0:
                bestR = curR
                improved = True
        if not improved:
            break
    return h, bestR


# ---------- equal-width M-block comb: exact via R_of on length-M array ----------

def _extract_blocks(h, M):
    """Mass-average h into M equal bins; return heights (u)."""
    N = h.size
    edges = np.linspace(0, N, M + 1)
    u = np.zeros(M)
    for i in range(M):
        lo = int(round(edges[i])); hi = int(round(edges[i + 1]))
        if hi <= lo:
            hi = lo + 1
        seg = h[lo:hi]
        u[i] = max(seg.mean(), 1e-12)
    return u


def _neg_logR_eq(x):
    h = np.exp(np.clip(x, -40, 40))
    r = R_of(h)
    if r <= 0 or not np.isfinite(r):
        return 1e18
    return -np.log(r)


def _eq_grad(x):
    h = np.exp(np.clip(x, -40, 40))
    val, g = _fun_grad_tie(h)
    return val, g * h


def _fit_equal_blocks(u0, deadline, maxiter=400):
    """L-BFGS-B in log-height space on the length-M array (equal widths)."""
    M = u0.size
    x0 = np.log(np.clip(u0, 1e-12, None))
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(_eq_grad, x0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * M,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return u0, R_of(u0)
    if res is None or not np.all(np.isfinite(res.x)):
        return u0, R_of(u0)
    u = np.exp(np.clip(res.x, -40.0, 40.0))
    return u, R_of(u)


def _rasterise(u, N):
    """Place M equal-width blocks into N steps (N multiple of M ideally)."""
    M = u.size
    idx = (np.arange(N) * M) // N
    idx = np.clip(idx, 0, M - 1)
    return _rescale(u[idx])


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    alt_best = None
    altR = 0.0

    # --- Experiment: equal-width M-block comb, M=64 then M=128 ---
    u32 = _extract_blocks(h0, 32)
    r32 = R_of(u32)
    print("eq32 R=%.12f (start %.12f)" % (r32, startR))

    # M=64: split each 32-block into two equal sub-blocks
    u64 = np.repeat(u32, 2)
    r64_init = R_of(u64)
    print("eq64 init R=%.12f (paired, should equal eq32)" % r64_init)

    N_target = 64 * 3281  # 209984
    if h0.size > N_target:
        N_target = h0.size

    eq_deadline = min(deadline - 10.0,
                      time.process_time() + budget_seconds * 0.35)
    u64_best, r64 = _fit_equal_blocks(u64, eq_deadline, maxiter=500)
    print("eq64 fit R=%.12f (start %.12f, diff %.2e)"
          % (r64, startR, r64 - startR))

    if r64 > startR + 1e-9:
        h64 = _rasterise(u64_best, N_target)
        r_raster = R_of(h64)
        print("eq64 rasterised R=%.12f (N=%d)" % (r_raster, h64.size))
        tlim = min(deadline - 6.0, time.process_time() + 8.0)
        h_pol = _full_lbfgs(h64, tlim, maxiter=250)
        r_pol = R_of(h_pol)
        if r_pol > r_raster:
            h64 = h_pol; r_raster = r_pol
        print("eq64+polish R=%.12f" % r_raster)
        alt_best = h64.copy(); altR = r_raster
        if r_raster > bestR:
            best = h64; bestR = r_raster
            print("eq64 accepted R=%.12f" % bestR)

    # M=128: split each 64-block again
    if time.process_time() < deadline - 12.0:
        u128 = np.repeat(u64_best, 2)
        r128_init = R_of(u128)
        print("eq128 init R=%.12f" % r128_init)
        eq_deadline2 = min(deadline - 6.0,
                           time.process_time() + budget_seconds * 0.20)
        u128_best, r128 = _fit_equal_blocks(u128, eq_deadline2, maxiter=500)
        print("eq128 fit R=%.12f (diff %.2e)" % (r128, r128 - startR))
        if r128 > max(startR, r64) + 1e-9:
            N2 = 128 * 3281  # 419968
            if N2 > 1000000:
                N2 = 1000000
            h128 = _rasterise(u128_best, N2)
            r_raster = R_of(h128)
            print("eq128 rasterised R=%.12f (N=%d)" % (r_raster, h128.size))
            tlim = min(deadline - 4.0, time.process_time() + 8.0)
            h_pol = _full_lbfgs(h128, tlim, maxiter=250)
            r_pol = R_of(h_pol)
            if r_pol > r_raster:
                h128 = h_pol; r_raster = r_pol
            print("eq128+polish R=%.12f" % r_raster)
            if r_raster > altR:
                alt_best = h128.copy(); altR = r_raster
            if r_raster > bestR:
                best = h128; bestR = r_raster
                print("eq128 accepted R=%.12f" % bestR)

    # --- Keep base's polish loop ---
    while time.process_time() < deadline - 2.0:
        tlim = min(deadline - 1.0, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("polish R=%.12f" % bestR)
        else:
            break

    n0 = best.size
    for n in (n0 * 2, n0 * 3, n0 * 4):
        if time.process_time() > deadline - 3.0:
            break
        n = min(1000000, int(n))
        if n <= best.size:
            continue
        h_up = _upsample(best, n)
        r_up = R_of(h_up)
        if r_up > bestR:
            best = h_up; bestR = r_up
            print("up R=%.12f (N=%d)" % (bestR, best.size))
        tlim = min(deadline - 2.0, time.process_time() + 5.0)
        hc = _full_lbfgs(best, tlim, maxiter=250)
        rc = R_of(hc)
        if rc > bestR:
            best = hc; bestR = rc
            print("polish R=%.12f (N=%d)" % (bestR, best.size))

    if time.process_time() < deadline - 2.0:
        hc, rc = _local_sweep(best, deadline - 1.0, passes=10)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("sweep R=%.12f" % bestR)

    while time.process_time() < deadline - 0.5:
        tlim = min(deadline - 0.2, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("polish R=%.12f" % bestR)
        else:
            break

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    if alt_best is None or altR <= 0:
        alt = best
    else:
        alt = alt_best

    print("final R=%.12f (start %.12f, N=%d, altR=%.12f)"
          % (bestR, startR, best.size, altR))

    return {"best": best, "alternative": alt}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h, beta=None):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    if beta is None:
        idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
        w = 1.0 / idx.size
        gLf[idx] += w / Lm
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    else:
        e = np.exp(beta * (Lf - mx))
        Z = e.sum()
        p = e / Z
        gLf += beta * p / Lm
        val = -np.log(num) + 2.0 * np.log(s) + (np.log(Z) / beta + mx) / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=400, mask=None, beta=None):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    if mask is None:
        pos = np.flatnonzero(h > 0)
    else:
        pos = np.flatnonzero((h > 0) & mask)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh, beta)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.02)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _peak_mask(h, frac=0.97, widen=0.20):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return np.zeros(h.size, dtype=bool)
    idx = np.flatnonzero(L >= mx * frac)
    if idx.size == 0:
        return np.zeros(h.size, dtype=bool)
    lo = int(idx[0]); hi = int(idx[-1])
    span = hi - lo
    pad = max(1, int(widen * span))
    lo = max(0, lo - 1 - pad)
    hi = min(h.size, hi - 1 + pad + 1)
    mask = np.zeros(h.size, dtype=bool)
    mask[lo:hi] = True
    return mask


def _prolongate_lin(h, n_new):
    n = h.size
    x_old = np.linspace(0.0, 1.0, n)
    x_new = np.linspace(0.0, 1.0, n_new)
    return _rescale(np.clip(np.interp(x_new, x_old, h), 0, None))


def _near_max_fracs(h):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    return (float(np.mean(L >= mx * 0.999)),
            float(np.mean(L >= mx * 0.99)),
            float(np.mean(L >= mx * 0.95)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
        else:
            best = None
    else:
        best = None

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        best = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(best)
    bestR = startR
    print("base R=%.12f (N=%d)" % (startR, best.size))

    upsampled = False
    it = 0
    phase_start = time.process_time()
    remaining = max(deadline - phase_start, 0.1)
    upsample_at = phase_start + 0.75 * remaining

    while time.process_time() < deadline - 0.3:
        it += 1

        # (a) full-array descent
        if time.process_time() < deadline - 0.3:
            cand = _lbfgs_custom(best, _fun_grad_tie, deadline, maxiter=400,
                                 mask=None, beta=None)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best = cand; bestR = r
                print("a R=%.12f it=%d" % (bestR, it))

        # (b) peak-window descent
        if time.process_time() < deadline - 0.3:
            mask = _peak_mask(best, frac=0.97, widen=0.20)
            cand = _lbfgs_custom(best, _fun_grad_tie, deadline, maxiter=400,
                                 mask=mask, beta=None)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best = cand; bestR = r
                print("b R=%.12f it=%d" % (bestR, it))

        # (c) beta-sharpening on the peak window every third round
        if it % 3 == 0:
            mask = _peak_mask(best, frac=0.97, widen=0.20)
            for beta in (1e3, 1e4, 1e5):
                if time.process_time() >= deadline - 0.3:
                    break
                cand = _lbfgs_custom(best, _fun_grad_tie, deadline, maxiter=200,
                                     mask=mask, beta=beta)
                r = R_of(cand)
                if r > bestR + 1e-15:
                    best = cand; bestR = r
                    print("c R=%.12f beta=%.0e it=%d" % (bestR, beta, it))

        # (d) one 2x upsample at 75% of remaining time
        if (not upsampled) and time.process_time() > upsample_at:
            upsampled = True
            if best.size < 500000 and time.process_time() < deadline - 3.0:
                h2 = _prolongate_lin(best, 2 * best.size)
                cand = _lbfgs_custom(h2, _fun_grad_tie, deadline, maxiter=400,
                                     mask=None, beta=None)
                r = R_of(cand)
                if r > bestR + 1e-15:
                    best = cand; bestR = r
                    print("upsample R=%.12f N=%d" % (bestR, best.size))
                else:
                    mask = _peak_mask(h2, frac=0.97, widen=0.20)
                    cand = _lbfgs_custom(h2, _fun_grad_tie, deadline, maxiter=400,
                                         mask=mask, beta=None)
                    r = R_of(cand)
                    if r > bestR + 1e-15:
                        best = cand; bestR = r
                        print("upsample-peak R=%.12f N=%d" % (bestR, best.size))

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    f01, f1, f5 = _near_max_fracs(best)
    print("near-max fractions 0.1%%=%.4f 1%%=%.4f 5%%=%.4f" % (f01, f1, f5))
    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, deadline, maxiter=150):
    """Optimise in log-space over positive entries (multiplicative)."""
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _prolong(h):
    out = np.empty(h.size * 2)
    out[0::2] = h
    out[1::2] = h
    return out


def _upsample(h, n):
    x_old = np.linspace(0.0, 1.0, h.size)
    x_new = np.linspace(0.0, 1.0, n)
    return _rescale(np.clip(np.interp(x_new, x_old, h), 0, None))


def _polish(h, deadline, rounds=3):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        free = _peak_window(best)
        cap = min(deadline - 0.3, time.process_time() + 1.5)
        hb = _lbfgs_block(best, free, 150, cap)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            best, bestR = hb, rb
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 2.5)
        hp = _lbfgs_log(best, cap, maxiter=250)
        rp = R_of(hp)
        if rp > bestR + 1e-15:
            best, bestR = hp, rp
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale(base)
            baseR = R_of(base)
        else:
            base, baseR = None, 0.0
    else:
        base, baseR = None, 0.0

    if base is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        base = _rescale(h)
        baseR = R_of(base)

    start_best = base.copy()
    start_bestR = baseR
    print("base R=%.9f (N=%d)" % (baseR, base.size))

    best = base.copy()
    bestR = baseR

    # Phase A: polish the start.
    hp, rp = _polish(best, min(deadline - 15.0, time.process_time() + 8.0), rounds=2)
    print("polish R=%.9f" % rp)
    if rp > bestR + 1e-14:
        best, bestR = hp, rp

    # Phase B: prolong + polish (doubling resolution).
    for _ in range(4):
        if best.size >= 500000 or time.process_time() >= deadline - 12.0:
            break
        hN = _prolong(best)
        cap = min(deadline - 10.0, time.process_time() + 6.0)
        hN, rN = _polish(hN, cap, rounds=2)
        print("prolong+polish R=%.9f (N=%d)" % (rN, hN.size))
        if rN > bestR + 1e-14:
            best, bestR = hN, rN
        else:
            break

    # Phase C: log-space full optimisations from best (multiplicative moves).
    while time.process_time() < deadline - 3.0:
        cap = min(deadline - 2.0, time.process_time() + 4.0)
        ht = _lbfgs_log(best, cap, maxiter=300)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht, r
            print("  log improve %.9f" % bestR)
