import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


# ---------- two-window mass transfer ----------

def _apply_transfer(h, a1, b1, a2, b2, alpha):
    hn = h.copy()
    m1 = h[a1:b1].sum()
    m2 = h[a2:b2].sum()
    if m1 <= 0 or m2 <= 0:
        return None
    hn[a1:b1] = h[a1:b1] * (1.0 + alpha)
    hn[a2:b2] = h[a2:b2] * (1.0 - alpha * m1 / m2)
    if np.any(hn < 0):
        return None
    return hn


def _best_alpha(h, a1, b1, a2, b2, lo=-0.45, hi=0.45, iters=20):
    gr = (np.sqrt(5.0) - 1.0) / 2.0
    c = hi - gr * (hi - lo)
    d = lo + gr * (hi - lo)
    hc = _apply_transfer(h, a1, b1, a2, b2, c)
    hd = _apply_transfer(h, a1, b1, a2, b2, d)
    fc = R_of(hc) if hc is not None else -1.0
    fd = R_of(hd) if hd is not None else -1.0
    for _ in range(iters):
        if fc > fd:
            hi = d; d = c; fd = fc
            c = hi - gr * (hi - lo)
            hc = _apply_transfer(h, a1, b1, a2, b2, c)
            fc = R_of(hc) if hc is not None else -1.0
        else:
            lo = c; c = d; fc = fd
            d = lo + gr * (hi - lo)
            hd = _apply_transfer(h, a1, b1, a2, b2, d)
            fd = R_of(hd) if hd is not None else -1.0
    alpha = 0.5 * (lo + hi)
    ha = _apply_transfer(h, a1, b1, a2, b2, alpha)
    if ha is None:
        return 0.0, h
    return alpha, ha


# ---------- adaptive-beta polish (soft-max continuation) ----------

def _polish(h, bestR, deadline, verbose=True):
    n = h.size
    for frac in [0.20, 0.10, 0.05, 0.025, 0.012]:
        if time.process_time() >= deadline - 0.5:
            return h, bestR
        free = _peak_window(h, frac=frac)
        cap = min(deadline - 0.3, time.process_time() + 1.5)
        hb = _lbfgs_block(h, free, 150, cap, beta=0.0)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            h, bestR = hb, rb
            if verbose:
                print("    polish frac=%.3f R=%.9f" % (frac, bestR))
    for beta in [200.0, 500.0, 1500.0, 4000.0]:
        if time.process_time() >= deadline - 0.5:
            return h, bestR
        cap = min(deadline - 0.3, time.process_time() + 1.2)
        hb = _lbfgs_block(h, np.arange(n), 120, cap, beta=beta)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            h, bestR = hb, rb
            if verbose:
                print("    beta=%.0f R=%.9f" % (beta, bestR))
    if time.process_time() < deadline - 0.5:
        cap = min(deadline - 0.3, time.process_time() + 2.5)
        hb = _lbfgs_block(h, np.arange(n), 200, cap, beta=0.0)
        rb = R_of(hb)
        if rb > bestR + 1e-15:
            h, bestR = hb, rb
            if verbose:
                print("    full R=%.9f" % bestR)
    return h, bestR


# ---------- mass-transfer coordinate sweep (new idea) ----------

def _transfer_sweep(h, bestR, deadline, ntrials=400, seed=0):
    """Random two-window mass transfers with golden-section alpha.
    This explores directions L-BFGS can't: exact mass-conserving moves
    that keep the support fixed but redistribute weight between distant
    windows."""
    rng = np.random.RandomState(seed)
    n = h.size
    if n < 8:
        return h, bestR
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    # window sizes: various scales
    scales = [max(1, n // 200), max(1, n // 50), max(1, n // 12), max(1, n // 4)]
    for t in range(ntrials):
        if time.process_time() > deadline:
            break
        w = scales[rng.randint(len(scales))]
        # anchor window 1 near the peak (where f*f max is achieved)
        a1 = max(0, m - w // 2 + rng.randint(-w, w + 1))
        b1 = min(n, a1 + w)
        if b1 <= a1:
            continue
        # window 2 random
        a2 = rng.randint(0, n)
        b2 = min(n, a2 + w)
        if b2 <= a2:
            continue
        if not (b2 <= a1 or b1 <= a2):
            continue
        if h[a1:b1].sum() <= 0 or h[a2:b2].sum() <= 0:
            continue
        alpha, hnew = _best_alpha(h, a1, b1, a2, b2)
        if abs(alpha) < 1e-6:
            continue
        r = R_of(hnew)
        if r > bestR + 1e-14:
            h, bestR = hnew, r
    return h, bestR


# ---------- main ----------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Phase 1: standard polish of the start
    best, bestR = _polish(best, bestR, deadline, verbose=True)
    print("after polish R=%.9f" % bestR)

    # Phase 2: alternate mass-transfer sweeps and polish until time out.
    # The transfer sweep is the new idea: exact mass-conserving
    # two-window moves that L-BFGS cannot represent.
    seed = 1
    stall = 0
    while time.process_time() < deadline - 1.0:
        prevR = bestR
        # give the sweep a solid slice of time
        cap = min(deadline - 0.6, time.process_time() + 3.0)
        best, bestR = _transfer_sweep(best, bestR, cap, ntrials=300, seed=seed)
        seed += 1
        if bestR > prevR + 1e-12:
            best, bestR = _polish(best, bestR, deadline, verbose=False)
            stall = 0
        else:
            stall += 1
            if stall >= 3:
                # one more polish then break
                best, bestR = _polish(best, bestR, deadline, verbose=False)
                break

    print("final R=%.9f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-13:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

