    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=200):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _upsample(h, n):
    x_old = np.linspace(0.0, 1.0, h.size)
    x_new = np.linspace(0.0, 1.0, n)
    return _rescale(np.clip(np.interp(x_new, x_old, h), 0, None))


def _local_sweep(h, deadline, passes=4):
    h = h.copy()
    bestR = R_of(h)
    n = h.size
    if n == 0:
        return h, bestR
    rng = np.random.RandomState(12345)
    factors = np.array([0.9, 0.95, 0.98, 1.02, 1.05, 1.1])
    blk = max(1, n // 200)
    for _ in range(passes):
        if time.process_time() > deadline:
            break
        improved = False
        order = rng.permutation((n + blk - 1) // blk)
        for bi in order:
            if time.process_time() > deadline:
                break
            lo = bi * blk
            hi = min(n, lo + blk)
            cur = h[lo:hi].copy()
            curR = bestR
            bestf = 1.0
            for f in factors:
                h[lo:hi] = cur * f
                r = R_of(h)
                if r > curR:
                    curR = r; bestf = f
            h[lo:hi] = cur * bestf
            if bestf != 1.0:
                bestR = curR
                improved = True
        if not improved:
            break
    return h, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    best = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = s.copy()
            best_R = R_of(best)

    # ---- Main idea: upsample start, do global L-BFGS polish, then multi-scale refine ----
    if best is not None:
        cur = best.copy()
        # upsample ladder: refine at multiple resolutions
        for target in [cur.size, 2 * cur.size, 4 * cur.size]:
            if time.process_time() > deadline - 5.0:
                break
            if target > 1_000_000:
                break
            if target != cur.size:
                cur = _upsample(cur, target)
            # global L-BFGS
            cap = min(deadline - 1.0, time.process_time() + 8.0)
            cur2 = _full_lbfgs(cur, cap, maxiter=250)
            if R_of(cur2) > R_of(cur):
                cur = cur2
            # local sweep
            cur3, _ = _local_sweep(cur, min(deadline - 0.5, time.process_time() + 3.0), passes=3)
            if R_of(cur3) > R_of(cur):
                cur = cur3
            r = R_of(cur)
            print(f"ladder N={cur.size}: R={r:.6f}")
            if r > best_R:
                best = cur.copy()
                best_R = r

    # ---- Final aggressive polish at best resolution ----
    if best is not None:
        while time.process_time() < deadline:
            cap = min(deadline, time.process_time() + 6.0)
            new = _full_lbfgs(best, cap, maxiter=300)
            r = R_of(new)
            if r > best_R + 1e-10:
                best = new
                best_R = r
                print(f"polish: R={r:.6f} N={best.size}")
            else:
                break

    if best is None:
        best = np.ones(50)
    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(50)
    print(f"final R={R_of(best):.6f} N={len(best)}")
    return best

