def _blockavg(h, B):
    N = h.size
    idx = (np.arange(N) * B) // N
    out = np.zeros(B)
    cnt = np.zeros(B)
    np.add.at(out, idx, h)
    np.add.at(cnt, idx, 1.0)
    cnt[cnt == 0] = 1.0
    return out / cnt


def _block_rblk(av):
    return R_of(np.concatenate(([0.0], np.convolve(av, av), [0.0])))


def _rasterise(a, N):
