                a[i] = base * f
                r = _block_rblk(a)
                if r > bestLocal:
                    bestLocal = r; bestf = f
            a[i] = base * bestf
            if bestLocal > curR + 1e-14:
                curR = bestLocal
                improved = True
    return a, curR


