    N = best.size
    print("base R=%.12f (N=%d)" % (bestR, N))

    # Phase 1: polish the given start
    while time.process_time() < deadline - 1.0:
        tlim = min(deadline - 0.5, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("polish R=%.12f" % bestR)
        else:
            break

    alt_best = best.copy()
    altR = bestR
    rng = np.random.RandomState(98765)

    # Phase 2: block-amplitude coordinate polish at several block counts,
    # rasterise + full LBFGS polish. This is the new structural idea:
    # directly optimise the coarse block shape (cheap), then lift.
    for B in (24, 40, 64, 96):
        if time.process_time() > deadline - 2.0:
            break
        tlim = min(deadline - 0.5, time.process_time() + 2.0)
        a, aR = _refine_blocks(best, B, tlim, rng)
        if aR <= 0:
            continue
        hr = _rescale(_rasterise(a / a.max(), N))
        tlim = min(deadline - 0.8, time.process_time() + 2.5)
        hp = _full_lbfgs(hr, tlim, maxiter=200)
        rp = R_of(hp)
        # a couple more full polishes to converge
        for _ in range(2):
            if time.process_time() > deadline - 1.0:
                break
            tlim = min(deadline - 0.3, time.process_time() + 2.0)
            hq = _full_lbfgs(hp, tlim, maxiter=150)
            rq = R_of(hq)
            if rq > rp + 1e-15:
                hp, rp = hq, rq
            else:
                break
        if rp > bestR + 1e-15:
            best, bestR = hp, rp
            print("block polish B=%d R=%.12f" % (B, bestR))
        if rp > altR:
            alt_best, altR = hp, rp

    # Phase 3: random block-perturbation multi-start around best
    B = 48
    a0 = _blockavg(best, B)
    if a0.sum() > 0:
        a0 = a0 / a0.max()
    else:
        a0 = np.ones(B) / B
    cur_a = a0.copy()
    curR = _block_rblk(cur_a)
    n_moves = 0
    while time.process_time() < deadline - 2.0:
        k = rng.randint(1, 6)
        sel = rng.choice(B, size=k, replace=False)
        step = np.exp(rng.randn(k) * 0.25)
        cand = cur_a.copy()
        cand[sel] *= step
        m = cand.max()
        if m <= 0:
            continue
        cand /= m
        candR = _block_rblk(cand)
        n_moves += 1
        if candR >= curR:
            cur_a, curR = cand, candR
        # occasionally lift perturbed shape and polish
        if n_moves % 40 == 0 and time.process_time() < deadline - 2.0:
            hr = _rescale(_rasterise(cur_a, N))
            tlim = min(deadline - 0.8, time.process_time() + 2.0)
            hp = _full_lbfgs(hr, tlim, maxiter=120)
            rp = R_of(hp)
            if rp > bestR + 1e-15:
                best, bestR = hp, rp
                print("perturb polish R=%.12f (moves=%d)" % (bestR, n_moves))
                new_a = _blockavg(best, B)
                if new_a.sum() > 0:
                    new_a = new_a / new_a.max()
                    nr = _block_rblk(new_a)
                    if nr > curR:
                        cur_a, curR = new_a, nr
            if rp > altR:
                alt_best, altR = hp, rp

    # Final polish
    while time.process_time() < deadline - 0.3:
        tlim = min(deadline - 0.1, time.process_time() + 2.0)
        hc = _full_lbfgs(best, tlim, maxiter=150)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best, bestR = hc, rc
            print("final polish R=%.12f" % bestR)
        else:
            break

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    # alternative: block-annealed rasterised shape if it beats alt
    alt_h = _rescale(_rasterise(cur_a, N))
    alt_r = R_of(alt_h)
    if alt_r > altR:
        alt_best, altR = alt_h, alt_r

    print("final R=%.12f (start %.12f, N=%d, altR=%.12f, moves=%d)"
          % (bestR, startR, best.size, altR, n_moves))

    return {"best": best, "alternative": alt_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        if beta > 0:
            fg = (lambda hh: _fun_grad_beta(hh, beta))
        else:
            fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _smooth(h):
    if h.size < 3:
        return h
    hs = h.copy()
    hs[1:-1] = 0.25 * h[:-2] + 0.5 * h[1:-1] + 0.25 * h[2:]
    return _rescale(hs)


def _upsample(h, factor):
    """Linear-interpolate upsampling of step heights to a finer grid."""
    n = h.size
    m = (n - 1) * factor + 1
    x_old = np.arange(n, dtype=float)
    x_new = np.linspace(0.0, n - 1.0, m)
    hu = np.interp(x_new, x_old, h)
    return _rescale(hu)


def _try_upsample(h, bestR, deadline, target_N):
    """Upsample then polish at higher resolution; return (h, R) or None."""
    if h.size >= target_N:
        return None
    factor = max(2, int(round(target_N / h.size)))
    hu = _upsample(h, factor)
    if hu.size > 1_000_000:
        hu = hu[:1_000_000]
    if time.process_time() >= deadline - 0.5:
        return None
    cap = deadline - 0.2
    hp = _lbfgs_log(hu, 250, cap, beta=0.0)
    rp = R_of(hp)
    if rp > bestR + 1e-13:
        return hp, rp
    return None


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    bestH = best.copy()
    bestRH = bestR

    loop_end = deadline - 0.6
    rng = np.random.default_rng(12345)

    # Phase 1: refine at current resolution using the multi-pronged search.
    since_improve = 0
    while time.process_time() < loop_end:
        since_improve += 1

        cap = min(loop_end, time.process_time() + 3.0)
        hs = _lbfgs_log(bestH, 200, cap, beta=0.0)
        rs = R_of(hs)
        if rs > bestRH + 1e-13:
            bestH, bestRH = hs.copy(), rs
            since_improve = 0
            continue

        # Upsample attempt: try a finer grid, which often reveals more room.
        target = min(1_000_000, bestH.size * 2)
        up = _try_upsample(bestH, bestRH, loop_end, target)
        if up is not None:
            bestH, bestRH = up
            since_improve = 0
            continue

        for beta in (1e3, 1e4, 1e5):
            if time.process_time() >= loop_end - 0.8:
                break
            cap = min(loop_end, time.process_time() + 2.0)
            hb = _lbfgs_log(bestH, 100, cap, beta=beta)
            rb = R_of(hb)
            if rb > bestRH + 1e-13:
                bestH, bestRH = hb.copy(), rb
                since_improve = 0
                break
        if since_improve == 0:
            continue

        if time.process_time() < loop_end - 0.8:
            frac = 0.04 + 0.08 * rng.random()
            free = _peak_window(bestH, frac=frac)
            cap = min(loop_end, time.process_time() + 2.0)
            hp = _lbfgs_block(bestH, free, 120, cap, beta=0.0)
            rp = R_of(hp)
            if rp > bestRH + 1e-13:
                bestH, bestRH = hp.copy(), rp
                since_improve = 0
                continue

        if since_improve >= 3 and time.process_time() < loop_end - 2.0:
            hsm = _smooth(bestH)
            cap = min(loop_end, time.process_time() + 2.0)
            hsp = _lbfgs_log(hsm, 150, cap, beta=0.0)
            rsp = R_of(hsp)
            if rsp > bestRH + 1e-13:
                bestH, bestRH = hsp.copy(), rsp
                since_improve = 0
            else:
                since_improve = 0

    print("final R=%.9f (N=%d)" % (bestRH, bestH.size))

    if bestRH > start_bestR + 1e-12:
        return {"best": bestH, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": bestH}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_Q(h, c=0.95, beta=1e3):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    thr = c * Lm
    over = Lf > thr
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    if np.any(over):
        excess = Lf[over] - thr
        gLf[over] += beta * excess / (Lm * Lm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    if np.any(over):
        val += 0.5 * beta * np.sum((Lf[over] - thr) ** 2) / (Lm * Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if fg is None:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if fg is None:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, frac=0.10):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    n = h.size
    half = max(16, int(frac * n))
    lo = max(0, m - half)
    hi = min(n, m + half)
    return np.arange(lo, hi)


def _argmax_pos(h):
    Lf = _knots(h)
    return int(np.argmax(Lf)) / max(1, Lf.size - 1)


def _polish(h, deadline, fracs=(0.02, 0.05, 0.10, 0.20)):
    best = h.copy()
    bestR = R_of(best)
    for frac in fracs:
        if time.process_time() >= deadline - 0.4:
            break
        free = _peak_window(best, frac=frac)
        cap = min(deadline, time.process_time() + 1.5)
        hp = _lbfgs_block(best, free, 120, cap)
        r = R_of(hp)
        if r > bestR:
            best, bestR = hp, r
    return best, bestR


def _restrict(h, k):
    n = h.size
    m = (n + k - 1) // k
    out = np.empty(m)
    for i in range(m):
        lo = i * k
        hi = min(lo + k, n)
        out[i] = h[lo:hi].mean()
    return out


def _prolong(hc, k, n_full):
    out = np.repeat(hc, k)
    if out.size >= n_full:
        return _rescale(out[:n_full])
    pad = n_full - out.size
    return _rescale(np.concatenate((out, np.full(pad, out[-1]))))


def _upsample(h, n):
    x_old = np.linspace(0.0, 1.0, h.size)
    x_new = np.linspace(0.0, 1.0, n)
    return _rescale(np.clip(np.interp(x_new, x_old, h), 0, None))


def construct(budget_seconds, start):
