        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.9f N=%d argmax=%.4f" % (bestR, best.size, _argmax_pos(best)))

    def try_new(name, cand):
        nonlocal best, bestR
        if cand is None:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            print("  %s NEW R=%.9f N=%d argmax=%.4f" %
                  (name, bestR, best.size, _argmax_pos(best)))
            return True
        return False

    loop_end = deadline - 0.5
    n_full = best.size

    # ---- Upsample to a higher resolution and re-optimize (new idea) ----
    # Try a higher-resolution representation to escape the local optimum of the
    # current resolution, then use it for the coarse/fine ladder.
    if time.process_time() < loop_end - 8.0 and n_full < 400000:
        target = min(int(n_full * 1.6), 400000)
        if target > n_full + 32:
            hu = _upsample(best, target)
            cap = min(loop_end, time.process_time() + 6.0)
            hu = _lbfgs_log(hu, 400, cap)
            if try_new("upsample%d" % target, hu):
                n_full = best.size

    # ---- Coarse restriction / optimize / prolongation ladder ----
    cycle = 0
    while time.process_time() < loop_end - 4.0:
        cycle += 1
        improved_this_cycle = False
        for k in (2, 3, 4, 5, 7):
            if time.process_time() >= loop_end - 4.0:
                break
            hc = _restrict(best, k)
            if hc.size < 8:
                continue
            cap = min(loop_end, time.process_time() + 3.0)
            hc = _lbfgs_log(hc, 150, cap, _fun_grad)
            r_after_coarse = R_of(hc)
            for beta in (1e3, 1e5):
                if time.process_time() >= loop_end - 4.0:
                    break
                cap = min(loop_end, time.process_time() + 1.5)
                hq = _lbfgs_log(hc, 120, cap,
                                lambda hh, b=beta: _fun_grad_Q(hh, c=0.95, beta=b))
                if R_of(hq) > R_of(hc):
                    hc = hq
            hp = _prolong(hc, k, n_full)
            cap = min(loop_end, time.process_time() + 2.5)
            hp, rp = _polish(hp, cap, fracs=(0.02, 0.05, 0.10, 0.20))
            print("  k=%d c=%d R_coarse=%.9f R_prolong=%.9f" %
                  (k, cycle, r_after_coarse, rp))
            if rp > bestR + 1e-14:
                if try_new("k=%d c=%d" % (k, cycle), hp):
                    improved_this_cycle = True
        if not improved_this_cycle:
            if time.process_time() < loop_end - 2.0:
                cap = min(loop_end, time.process_time() + 3.0)
                hf = _lbfgs_log(best, 250, cap)
                try_new("full c=%d" % cycle, hf)

    if time.process_time() < loop_end:
        cap = min(loop_end, time.process_time() + 6.0)
        hf = _lbfgs_log(best, 600, cap)
        try_new("final lbfgs", hf)
    if time.process_time() < loop_end:
        hp, rp = _polish(best, loop_end, fracs=(0.02, 0.05, 0.10, 0.20))
        try_new("final polish", hp)

    if bestR < start_bestR:
        best, bestR = start_best, start_bestR

    print("final R=%.9f N=%d argmax=%.4f" % (bestR, best.size, _argmax_pos(best)))

    if bestR > start_bestR + 1e-12:
        return {"best": best, "alternative": start_best}
    else:
        return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, deadline, maxiter=200, free=None):
    """L-BFGS in log coordinates on a subset (or all) of the entries."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    if free is None:
        active = np.flatnonzero(h > 0)
    else:
        active = np.asarray(free, dtype=int)
        active = active[h[active] > 0]
    if active.size == 0:
        return h0
    floor = 1e-12 * h.max() if h.max() > 0 else 1e-12
    x0 = np.log(np.clip(h[active], floor, None))

    def f(x):
        hh = h.copy()
        hh[active] = np.exp(x)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _lbfgs_lin(h0, deadline, maxiter=200, free=None):
    """L-BFGS in linear coordinates (better when many heights hit zero)."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    if free is None:
        active = np.arange(h.size)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.999, pad_frac=0.3, extra=128):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _upsample(h, N2):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    N = h.size
    if N2 == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    if c[-1] <= 0:
        return np.zeros(N2)
    x = np.linspace(0.0, N, N2 + 1)
    cm = np.interp(x, np.arange(N + 1), c)
    return np.clip(np.diff(cm), 0, None)


def _coarse(h, N2):
    return _upsample(h, N2)


def _poly_smooth(h0, deadline, iters=30):
    """Smooth the shape by repeated (1,2,1) blur with slight downscale."""
    h = h0.copy()
    for _ in range(iters):
        if time.process_time() > deadline:
            break
        hp = np.concatenate(([h[0]], h, [h[-1]]))
        h = 0.25 * hp[:-2] + 0.5 * hp[1:-1] + 0.25 * hp[2:]
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alternatives = []

    # ---- Strategy A: refine at current resolution (log + lin, then peak) ----
    try:
        cur = best.copy()
        for _ in range(8):
            if time.process_time() >= deadline - 3.0:
                break
            ht = _lbfgs_log(cur, deadline - 3.0, maxiter=250)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht.copy(), r
            cur = ht
            if time.process_time() >= deadline - 3.0:
                break
            ht = _lbfgs_lin(cur, deadline - 3.0, maxiter=250)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht.copy(), r
            cur = ht
            if time.process_time() >= deadline - 3.0:
                break
            win = _peak_window(best, pad_frac=0.10, extra=128)
            ht = _lbfgs_log(best, deadline - 3.0, maxiter=200, free=win)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht.copy(), r
            cur = best.copy()
        print("A refine: R=%.9f" % bestR)
    except Exception as e:
        print("A failed: %s" % e)

    # ---- Strategy B: peak-window ladder ----
    try:
        for pad in (0.25, 0.15, 0.10, 0.06, 0.04):
            if time.process_time() >= deadline - 3.0:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            for mode in ('log', 'lin'):
                if time.process_time() >= deadline - 3.0:
                    break
                fn = _lbfgs_log if mode == 'log' else _lbfgs_lin
                ht = fn(best, deadline - 3.0, maxiter=200, free=win)
                r = R_of(ht)
                if r > bestR + 1e-14:
                    best, bestR = ht.copy(), r
        print("B peak: R=%.9f" % bestR)
    except Exception as e:
        print("B failed: %s" % e)

    # ---- Strategy C: upsample ladder ----
    try:
        for factor in (1.5, 2.0, 3.0, 4.0):
            if time.process_time() >= deadline - 3.0:
                break
            if best.size * factor > 900000:
                continue
            hu = _upsample(best, int(best.size * factor))
            hu = _rescale(hu)
            ru = R_of(hu)
            ht = _lbfgs_log(hu, deadline - 3.0, maxiter=250)
            r = R_of(ht)
            if r > ru + 1e-14:
                hu, ru = ht, r
            if time.process_time() < deadline - 3.0:
                ht = _lbfgs_lin(hu, deadline - 3.0, maxiter=250)
                r = R_of(ht)
                if r > ru + 1e-14:
                    hu, ru = ht, r
            if time.process_time() < deadline - 3.0:
                win = _peak_window(hu, pad_frac=0.10, extra=256)
                ht = _lbfgs_log(hu, deadline - 3.0, maxiter=200, free=win)
                r = R_of(ht)
                if r > ru + 1e-14:
                    hu, ru = ht, r
            print("C up x%.1f: R=%.9f (N=%d)" % (factor, ru, hu.size))
            if ru > bestR + 1e-14:
                best, bestR = hu.copy(), ru
            elif ru > start_bestR + 1e-14 and hu.size != start_best.size:
                alternatives.append((ru, hu.copy()))
    except Exception as e:
        print("C failed: %s" % e)

    # ---- Strategy D: coarse-to-fine with smoothing ----
    try:
        if best.size > 4096 and time.process_time() < deadline - 3.0:
            Nc = max(1024, best.size // 4)
            hc = _coarse(best, Nc)
            hc = _rescale(hc)
            hc = _lbfgs_log(hc, deadline - 3.0, maxiter=250)
            hc = _lbfgs_lin(hc, deadline - 3.0, maxiter=250)
            hu = _upsample(hc, best.size)
            hu = _rescale(hu)
            ru = R_of(hu)
            if time.process_time() < deadline - 3.0:
                hu = _lbfgs_log(hu, deadline - 3.0, maxiter=250)
                ru = R_of(hu)
            print("D coarse-fine: R=%.9f" % ru)
            if ru > bestR + 1e-14:
                best, bestR = hu.copy(), ru
            elif ru > start_bestR + 1e-14 and hu.size != start_best.size:
                alternatives.append((ru, hu.copy()))
    except Exception as e:
        print("D failed: %s" % e)

    # ---- Strategy E: smoothing perturbation to escape local optima ----
    try:
        for it in range(20):
            if time.process_time() >= deadline - 3.0:
                break
            hp = _poly_smooth(best, deadline - 3.0, iters=8 + 4 * it)
            rp = R_of(hp)
            if rp >= bestR - 0.002:
                ht = _lbfgs_log(hp, deadline - 3.0, maxiter=250)
                r = R_of(ht)
                if r > bestR + 1e-14:
                    best, bestR = ht.copy(), r
                    print("E escape it=%d: R=%.9f" % (it, bestR))
            else:
                break
    except Exception as e:
        print("E failed: %s" % e)

    # ---- Final polish ----
    try:
        for _ in range(200):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_log(best, deadline - 0.5, maxiter=300)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht, r
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_lin(best, deadline - 0.5, maxiter=300)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht, r
            if time.process_time() >= deadline - 0.5:
                break
            win = _peak_window(best, pad_frac=0.08, extra=128)
            ht = _lbfgs_log(best, deadline - 0.5, maxiter=250, free=win)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht, r
            else:
                break
    except Exception as e:
        print("polish failed: %s" % e)

    print("final R=%.9f (N=%d, start %.9f)" % (bestR, best.size, start_bestR))

    if bestR >= start_bestR - 1e-13:
        if alternatives:
            alternatives.sort(key=lambda x: -x[0])
            alt = alternatives[0][1]
            if alt.size != best.size or not np.allclose(alt, best):
                return {"best": best, "alternative": alt}
        return best
    if alternatives:
        alternatives.sort(key=lambda x: -x[0])
        alt = alternatives[0][1]
        if alternatives[0][0] > start_bestR + 1e-14:
            return {"best": alt, "alternative": start_best}
    return start_best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h, beta=None):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    if beta is None:
        idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
        w = 1.0 / idx.size
        gLf[idx] += w / Lm
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    else:
        e = np.exp(beta * (Lf - mx))
        Z = e.sum()
        p = e / Z
        gLf += beta * p / Lm
        val = -np.log(num) + 2.0 * np.log(s) + (np.log(Z) / beta + mx) / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=400, mask=None, beta=None):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    if mask is None:
        pos = np.flatnonzero(h > 0)
    else:
        pos = np.flatnonzero((h > 0) & mask)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh, beta)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.02)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _peak_mask(h, frac=0.97, widen=0.20):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return np.zeros(h.size, dtype=bool)
    idx = np.flatnonzero(L >= mx * frac)
    if idx.size == 0:
        return np.zeros(h.size, dtype=bool)
    lo = int(idx[0]); hi = int(idx[-1])
    span = hi - lo
    pad = max(1, int(widen * span))
    lo = max(0, lo - 1 - pad)
    hi = min(h.size, hi - 1 + pad + 1)
    mask = np.zeros(h.size, dtype=bool)
    mask[lo:hi] = True
    return mask


def _prolongate_lin(h, n_new):
    n = h.size
    x_old = np.linspace(0.0, 1.0, n)
    x_new = np.linspace(0.0, 1.0, n_new)
    return _rescale(np.clip(np.interp(x_new, x_old, h), 0, None))


def _near_max_fracs(h):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    return (float(np.mean(L >= mx * 0.999)),
            float(np.mean(L >= mx * 0.99)),
            float(np.mean(L >= mx * 0.95)))


def _coarsen_block(h, factor=2):
    n = h.size
    m = n // factor
    if m < 1:
        return h.copy()
    hh = h[:m * factor].reshape(m, factor).sum(axis=1)
    return _prolongate_lin(hh, n)


def _perturb_multiplicative(h, sigma, rng):
    h2 = h.copy()
    pos = np.flatnonzero(h2 > 0)
    if pos.size == 0:
        return h2
    h2[pos] *= np.exp(rng.normal(0.0, sigma, pos.size))
    return _rescale(h2)


def _perturb_swap(h, frac, rng):
    h2 = h.copy()
    pos = np.flatnonzero(h2 > 0)
    zero = np.flatnonzero(h2 <= 0)
    if pos.size > 0:
        k = max(1, int(frac * pos.size))
        idx = rng.choice(pos, size=min(k, pos.size), replace=False)
        h2[idx] = 0.0
    if zero.size > 0:
        k = max(1, int(frac * zero.size))
        idx = rng.choice(zero, size=min(k, zero.size), replace=False)
        fill = h2.mean() if h2.mean() > 0 else 1.0
        h2[idx] = fill
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
        else:
            best = None
    else:
        best = None

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        best = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(best)
    bestR = startR
    print("base R=%.12f (N=%d)" % (startR, best.size))

    # --- Phase 1: multi-start arms ---
    phase1_end = t0 + 0.65 * (deadline - t0)
    rng = np.random.default_rng(12345)

    arms = []
    for s in (0.02, 0.02, 0.02, 0.02, 0.02):
        arms.append(("mult0.02", _perturb_multiplicative(best, s, rng)))
    arms.append(("mult0.05", _perturb_multiplicative(best, 0.05, rng)))
    arms.append(("swap", _perturb_swap(best, 0.01, rng)))
    arms.append(("coarsen", _coarsen_block(best, 2)))

    best_arm = best.copy()
    best_armR = bestR

    for name, arm_h in arms:
        if time.process_time() >= phase1_end - 0.5:
            break
        arm_deadline = min(time.process_time() + 5.0, phase1_end)
        cand = _lbfgs_custom(arm_h, _fun_grad_tie, arm_deadline,
                             maxiter=300, mask=None, beta=None)
        r = R_of(cand)
        # peak-window polish
        if time.process_time() < phase1_end - 0.3:
            mask = _peak_mask(cand, frac=0.97, widen=0.20)
            arm_deadline2 = min(time.process_time() + 2.0, phase1_end)
            cand2 = _lbfgs_custom(cand, _fun_grad_tie, arm_deadline2,
                                  maxiter=200, mask=mask, beta=None)
            r2 = R_of(cand2)
            if r2 > r:
                cand = cand2; r = r2
        print("arm %s R=%.12f" % (name, r))
        if r > best_armR + 1e-15:
            best_arm = cand; best_armR = r

    if best_armR > bestR + 1e-15:
        best = best_arm; bestR = best_armR
        print("winner R=%.12f" % bestR)

    # --- Phase 2: monotone alternating loop on winner ---
    it = 0
    while time.process_time() < deadline - 0.3:
        it += 1
        cand = _lbfgs_custom(best, _fun_grad_tie, deadline, maxiter=400,
                             mask=None, beta=None)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best = cand; bestR = r
            print("a R=%.12f it=%d" % (bestR, it))

        if time.process_time() >= deadline - 0.3:
            break
        mask = _peak_mask(best, frac=0.97, widen=0.20)
        cand = _lbfgs_custom(best, _fun_grad_tie, deadline, maxiter=400,
                             mask=mask, beta=None)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best = cand; bestR = r
            print("b R=%.12f it=%d" % (bestR, it))

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    f01, f1, f5 = _near_max_fracs(best)
    print("near-max fractions 0.1%%=%.4f 1%%=%.4f 5%%=%.4f" % (f01, f1, f5))
    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    num, _, Lf = _num_and_dq(h)
    den = s * s * Lf.max()
    if den <= 0:
        return 0.0
    return num / den


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _upsample(h, n):
    x_old = np.linspace(0.0, 1.0, h.size)
    x_new = np.linspace(0.0, 1.0, n)
    return _rescale(np.clip(np.interp(x_new, x_old, h), 0, None))


def _peak_window(h, deadline, half):
    n = h.size
    if n < 8:
        return h
    Lf = _knots(h)
    kmax = int(np.argmax(Lf))
    center = kmax - 1
    lo = max(0, center - half)
    hi = min(n, center + half)
    if hi - lo < 4:
        return h
    pos = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': 250, 'maxfun': 500,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    startN = h0.size
    best = h0.copy()
    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    # Phase A: refine at current resolution with full L-BFGS.
    while time.process_time() < deadline - 2.0:
        tlim = min(deadline - 1.0, time.process_time() + 4.0)
        hc = _full_lbfgs(best, tlim, maxiter=300)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("polish R=%.12f" % bestR)
        else:
            break

    # Phase B: local refinement in windows near the peak of f*f.
    # The binding constraint is the max of f*f; refining locally near the
    # peak gives the optimizer more effective freedom.
    if time.process_time() < deadline - 3.0:
        for half in (max(128, startN // 6), max(256, startN // 4)):
            if time.process_time() >= deadline - 2.0:
                break
            tlim = min(deadline - 1.0, time.process_time() + 5.0)
            hw = _peak_window(best, tlim, half)
            rw = R_of(hw)
            if rw > bestR + 1e-15:
                best = hw; bestR = rw
                print("window(half=%d) R=%.12f" % (half, bestR))

    # Phase C: upsample to a finer grid and polish to unlock more freedom.
    alt_best = best.copy()
    altR = bestR
    if time.process_time() < deadline - 4.0 and startN < 400000:
        N2 = min(400000, max(2 * startN, 60000))
        hu = _upsample(best, N2)
        ru = R_of(hu)
        tlim = min(deadline - 2.0, time.process_time() + 6.0)
        hup = _full_lbfgs(hu, tlim, maxiter=200)
        rup = R_of(hup)
        print("upsample N=%d: %.12f -> polish %.12f" % (N2, ru, rup))
        if rup > altR:
            alt_best = hup.copy(); altR = rup

    # Phase D: final polish of best.
    while time.process_time() < deadline - 0.5:
        tlim = min(deadline - 0.2, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("final polish R=%.12f" % bestR)
        else:
            break

    if bestR < startR:
        best = h0.copy(); bestR = startR

    # Prefer the finer alternative if it actually beats best.
    if altR > bestR:
        best, bestR = alt_best, altR
    else:
        alt_best, altR = best.copy(), bestR

    print("final R=%.12f (start %.12f, N=%d, altR=%.12f)"
          % (bestR, startR, best.size, altR))

    return {"best": best, "alternative": alt_best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _fun_grad_active(h, S):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    if S.size == 0:
        return 1e18, np.zeros(h.size)
    M = Lf[S].max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    idx = S[Lf[S] >= M * (1.0 - 1e-12)]
    gLf = -dq / num
    gLf[idx] += (1.0 / idx.size) / M
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M)
    return val, grad


def _active_lbfgs(h0, deadline, pad=0.02, maxiter=200):
    if time.process_time() >= deadline - 0.5:
        return h0
    Lf = _knots(h0)
    M = Lf.max()
    S = np.flatnonzero(Lf >= (1.0 - pad) * M)
    if S.size < 4:
        return h0
    return _lbfgs_custom(h0, lambda h: _fun_grad_active(h, S),
                         deadline, maxiter=maxiter)


def _resample(h, Nnew):
    """Resample step function h (length N) to Nnew equal steps preserving mass."""
    N = h.size
    if N == Nnew:
        return h.copy()
    # cumulative mass of h (piecewise constant), evaluated at new boundaries
    c = np.concatenate(([0.0], np.cumsum(h)))  # length N+1, mass up to boundary i/N
    xs = np.linspace(0.0, N, Nnew + 1)  # in units of old step widths
    vals = np.interp(xs, np.arange(N + 1), c)
    return np.diff(vals)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    alt_best = best.copy()
    altR = bestR

    # Phase 1: alternate full LBFGS and active-set LBFGS on the peak knots.
    stall = 0
    while time.process_time() < deadline - 1.0 and stall < 6:
        improved = False
        tlim = min(deadline - 0.5, time.process_time() + 2.5)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-14:
            best = hc; bestR = rc
            improved = True
            print("polish R=%.12f" % bestR)
        for pad in (0.05, 0.02, 0.01):
            if time.process_time() >= deadline - 0.6:
                break
            tlim = min(deadline - 0.5, time.process_time() + 1.5)
            hc = _active_lbfgs(best, tlim, pad=pad, maxiter=120)
            rc = R_of(hc)
            if rc > bestR + 1e-14:
                best = hc; bestR = rc
                improved = True
                print("active(pad=%.3f) R=%.12f" % (pad, bestR))
        if not improved:
            stall += 1
        else:
            stall = 0

    if bestR > altR:
        alt_best = best.copy(); altR = bestR

    # Phase 2 (NEW): resolution search. Downsample best, re-optimise at lower N,
    # then upsample back and re-optimise. Coarse-to-fine often escapes the
    # near-flat plateaus that full-resolution LBFGS cannot.
    N0 = best.size
    for Nnew in (N0 // 4, N0 // 2, N0 // 8, N0 // 16):
        if Nnew < 256 or time.process_time() >= deadline - 2.0:
            continue
        # downsample
        hd = _rescale(_resample(best, Nnew))
        rd = R_of(hd)
        # optimise at the coarse resolution
        tlim = min(deadline - 1.0, time.process_time() + 2.0)
        hd = _full_lbfgs(hd, tlim, maxiter=200)
        rd = R_of(hd)
        # upsample back to N0, then refine at full resolution
        hu = _rescale(_resample(hd, N0))
        tlim = min(deadline - 0.6, time.process_time() + 2.0)
        hu = _full_lbfgs(hu, tlim, maxiter=200)
        ru = R_of(hu)
        if ru > bestR + 1e-14:
            best = hu; bestR = ru
            print("resample(N=%d) R=%.12f" % (Nnew, bestR))

    if bestR > altR:
        alt_best = best.copy(); altR = bestR

    # Phase 3: keep alternating full/active-set until the deadline.
    stall = 0
    while time.process_time() < deadline - 0.5 and stall < 8:
        improved = False
        tlim = min(deadline - 0.3, time.process_time() + 2.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            improved = True
            print("polish R=%.12f" % bestR)
        for pad in (0.03, 0.015, 0.008):
            if time.process_time() >= deadline - 0.4:
                break
            tlim = min(deadline - 0.3, time.process_time() + 1.2)
            hc = _active_lbfgs(best, tlim, pad=pad, maxiter=100)
            rc = R_of(hc)
            if rc > bestR + 1e-15:
                best = hc; bestR = rc
                improved = True
                print("active(pad=%.3f) R=%.12f" % (pad, bestR))
        if not improved:
            stall += 1
        else:
            stall = 0

    if bestR < startR:
        best = h0.copy()
        bestR = startR
    if altR <= 0:
        alt_best = best.copy()
        altR = bestR

    print("final R=%.12f (start %.12f, N=%d, altR=%.12f)"
          % (bestR, startR, best.size, altR))

    return {"best": best, "alternative": alt_best}

