    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _split_half(h, deadline, iters=40):
    """One round of doubling resolution via piecewise-constant split, then polish."""
    n = h.size
    if n >= 900000:
        return h, R_of(h)
    h2 = np.repeat(h, 2)
    h2 = _rescale(h2)
    r = R_of(h2)
    tlim = min(deadline - 0.2, time.process_time() + 3.0)
    h3 = _full_lbfgs(h2, tlim, maxiter=iters)
    r3 = R_of(h3)
    if r3 >= r:
        return h3, r3
    return h2, r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    # Phase 1: heavy polish of start at its own resolution
    stale = 0
    while time.process_time() < deadline - 1.0 and stale < 3:
        tlim = min(deadline - 0.5, time.process_time() + 4.0)
        hc = _full_lbfgs(best, tlim, maxiter=300)
        rc = R_of(hc)
        if rc > bestR + 1e-14:
            best = hc; bestR = rc; stale = 0
            print("polish R=%.12f" % bestR)
        else:
            stale += 1

    # Phase 2: resolution doubling with polish at each level.
    while time.process_time() < deadline - 3.0:
        hc, rc = _split_half(best, deadline, iters=60)
        if rc > bestR + 1e-14:
            best = hc; bestR = rc
            print("split R=%.12f (N=%d)" % (bestR, best.size))
        else:
            break

    # Phase 3: final polish to converge at current resolution.
    stale = 0
    while time.process_time() < deadline - 0.5 and stale < 2:
        tlim = min(deadline - 0.2, time.process_time() + 4.0)
        hc = _full_lbfgs(best, tlim, maxiter=400)
        rc = R_of(hc)
        if rc > bestR + 1e-14:
            best = hc; bestR = rc; stale = 0
            print("final-polish R=%.12f (N=%d)" % (bestR, best.size))
        else:
            stale += 1

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))

    return {"best": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _seed_zeros(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    eps = max(1e-9, 1e-6 * h.mean())
    out = h.copy()
    out[out <= 0] = eps
    return out


def _refine_knots(h, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h
    hs = _seed_zeros(h)
    return _lbfgs_all_pos(hs, maxiter, deadline, beta=0.0)


def run_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 800, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 400, deadline - 0.5, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.05, 64, 1e7), (0.10, 64, 1e8), (0.25, 128, 1e8),
              (0.40, 256, 1e8), (0.60, 512, 1e8)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=250, deadline=deadline - 0.5,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _lbfgs_all_pos(best, 300, deadline - 0.5, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.5:
        ht = _refine_knots(best, 300, deadline - 0.5)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _mini_cycle(best, bestR, deadline):
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 200, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    ladder = [(0.10, 64, 1e7), (0.30, 128, 1e7), (0.50, 256, 1e7)]
    for frac, extra, beta in ladder:
        if time.process_time() >= deadline - 0.4:
            break
        win = _peak_window(best, pad_frac=frac, extra=extra)
        ht = _lbfgs_block(best, win, maxiter=150, deadline=deadline - 0.4,
                          beta=beta)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    if time.process_time() < deadline - 0.4:
        ht = _lbfgs_all_pos(best, 150, deadline - 0.4, beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r
    return best, bestR


def _grad_logR(h):
    s = h.sum()
    if s <= 0:
        return np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    return _backprop(gLf, h)


def _screen(h, g):
    n = h.size
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return []
    mean_pos = h[pos].mean()
    cands = []
    for a in pos:
        ha = h[a]
        half = 0.5 * ha
        for b in (a + 1, a - 1):
            if 0 <= b < n:
                pred = -half * g[a] + half * g[b]
                cands.append((pred, int(a), int(b), 'split'))
    posset = pos
    for a in pos:
        left = posset[posset < a]
        right = posset[posset > a]
        ha = h[a]
        if left.size:
            b = int(left[-1])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
        if right.size:
            b = int(right[0])
            pred = -ha * g[a] + ha * g[b]
            cands.append((pred, int(a), b, 'transfer'))
    for a in pos:
        pred = -h[a] * g[a]
        cands.append((pred, int(a), -1, 'death'))
    posmask = h > 0
    zeros = np.flatnonzero(~posmask)
    births = []
    for z in zeros:
        left_pos = z - 1 >= 0 and posmask[z - 1]
        right_pos = z + 1 < n and posmask[z + 1]
        if left_pos or right_pos:
            births.append(int(z))
    if births:
        births = np.array(births, dtype=int)
        val = 0.5 * mean_pos
        preds = val * g[births]
        for i, z in enumerate(births):
            cands.append((preds[i], int(z), -1, 'birth'))
    if not cands:
        return []
    cands.sort(key=lambda t: -t[0])
    chosen = []
    used = []
    for pred, a, b, kind in cands:
        if pred <= 0:
            break
        ok = True
        for u in used:
            if abs(a - u) < 4 or (b >= 0 and abs(b - u) < 4):
                ok = False
                break
        if ok:
            chosen.append((pred, a, b, kind))
            used.append(a)
            if b >= 0:
                used.append(b)
            if len(chosen) >= 64:
                break
    return chosen


def _apply_edit(h, a, b, kind):
    h2 = h.copy()
    if kind == 'split':
        half = h2[a] * 0.5
        h2[a] -= half
        h2[b] += half
    elif kind == 'transfer':
        h2[b] += h2[a]
        h2[a] = 0.0
    elif kind == 'death':
        h2[a] = 0.0
    elif kind == 'birth':
        pos = h2 > 0
        if pos.any():
            h2[a] = 0.5 * h2[pos].mean()
        else:
            h2[a] = 1.0
    return h2


def _repair_edit(h2, a, b, deadline):
    n = h2.size
    lo = max(0, a - 48)
    hi = min(n - 1, a + 48)
    if b >= 0:
        lo = min(lo, max(0, b - 48))
        hi = max(hi, min(n - 1, b + 48))
    free = np.arange(lo, hi + 1)
    h2 = _lbfgs_block(h2, free, 60, deadline, beta=0.0)
    h2 = _lbfgs_block(h2, free, 40, deadline, beta=1e7)
    return h2


def _greedy_edit_loop(best, bestR, deadline, rng):
    round_no = 0
    while time.process_time() < deadline - 0.5:
        round_no += 1
        g = _grad_logR(best)
        cands = _screen(best, g)
        if not cands:
            break
        best_cand = None
        best_cand_R = bestR
        for pred, a, b, kind in cands:
            if time.process_time() >= deadline - 0.5:
                break
            h2 = _apply_edit(best, a, b, kind)
            h2 = _repair_edit(h2, a, b, deadline)
            r2 = R_of(h2)
            if r2 > best_cand_R + 1e-13:
                best_cand = h2
                best_cand_R = r2
        if best_cand is not None and best_cand_R > bestR + 1e-12:
            best = best_cand
            bestR = best_cand_R
        else:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
                    continue
            break
        if round_no % 20 == 0:
            if time.process_time() < deadline - 1.0:
                st, r = _mini_cycle(best, bestR, deadline - 0.5)
                if r > bestR + 1e-13:
                    best, bestR = st, r
    return best, bestR


def _active_support(h):
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return 0, h.size - 1
    return int(pos[0]), int(pos[-1])


def _warp(h, kind, alpha):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    if n < 2 or h.sum() <= 0:
        return h.copy()
    H = np.concatenate(([0.0], np.cumsum(h)))
    Htot = H[-1]
    x = np.linspace(0.0, 1.0, n + 1)
    t = x
    if kind == 'sym':
        psi = t + alpha * t * (1.0 - t)
    elif kind == 'left':
        psi = t + alpha * t * t
    elif kind == 'right':
        psi = t - alpha * (1.0 - t) ** 2
    else:
        return h.copy()
    psi = np.clip(psi, 0.0, 1.0)
    psi = np.maximum.accumulate(psi)
    xp = psi
    fp = t
    keep = np.concatenate(([True], np.diff(xp) > 0))
    if not np.all(keep):
        xp = xp[keep]
        fp = fp[keep]
    if xp.size < 2:
        return h.copy()
    t_inv = np.interp(x, xp, fp)
    t_inv = np.clip(t_inv, 0.0, 1.0)
    Hv = np.interp(t_inv, np.linspace(0.0, 1.0, n + 1), H)
    h2 = np.diff(Hv)
    h2 = np.clip(h2, 0.0, None)
    if h2.sum() <= 0:
        return h.copy()
    h2 *= Htot / h2.sum()
    return _rescale(h2)


# ---------------- NEW: peak-flattening via second-order push ----------------

def _flatten_peak(h, bestR, deadline, n_rounds=6):
    """Iteratively flatten the top of f*f by moving mass within the peak band.

    The idea: where L is at its max over a broad band, the current
    objective only rewards the single max knot. Instead, push mass between
    positions in the peak region so that the top band becomes wider/flatter,
    which tends to increase ||L||_2^2 relative to ||L||_inf.
    """
    n = h.size
    cur = h.copy()
    curR = bestR
    for r in range(n_rounds):
        if time.process_time() >= deadline - 0.5:
            break
        Lf = _knots(cur)
        M = Lf.max()
        if M <= 0:
            break
        # target band: knots within 2% of max
        band = np.flatnonzero(Lf >= 0.98 * M)
        if band.size < 4:
            break
        lo_k = int(band.min())
        hi_k = int(band.max())
        # h index range that influences knots [lo_k, hi_k]:
        # L_i = sum h_j h_{i-j}.  Push a little at h indices near the
        # center of the peak.
        center_k = 0.5 * (lo_k + hi_k)
        c_h = int(round(center_k / 2.0))
        half = max(64, int((hi_k - lo_k) * 0.75))
        lo = max(0, c_h - half)
        hi = min(n - 1, c_h + half)
        if hi - lo < 8:
            break
        win = np.arange(lo, hi + 1)
        # run a peak-window L-BFGS with a *sharper* soft-max to flatten
        # (larger beta => more emphasis on top band being flat)
        for beta in (2e7, 5e7):
            if time.process_time() >= deadline - 0.5:
                break
            ht = _lbfgs_block(cur, win, 120, deadline - 0.4, beta=beta)
            r = R_of(ht)
            if r > curR + 1e-13:
                cur, curR = ht, r
        # Also: try a small localized random perturbation of heights in
        # the peak-affected zone, followed by polish.  This can jump out
        # of local optima that pure gradient can't escape.
        if time.process_time() < deadline - 0.5:
            rng = np.random.default_rng(12345 + r)
            amp = 0.02 * cur[win].mean() + 1e-12
            pert = cur.copy()
            noise = rng.standard_normal(win.size) * amp
            pert[win] = np.clip(pert[win] + noise, 0.0, None)
            pert = _rescale(pert)
            ht = _lbfgs_block(pert, win, 80, deadline - 0.4, beta=1e7)
            r = R_of(ht)
            if r > curR + 1e-13:
                cur, curR = ht, r
    return cur, curR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt_cand = None
    altR = -1.0

    # ---- NEW: peak-flattening phase (the main new idea) ----
    # Run this early while there is time, on a copy.
    if time.process_time() < deadline - 20.0:
        flat_budget_end = deadline - 18.0
        hf, rf = _flatten_peak(best, bestR, flat_budget_end, n_rounds=4)
        print("flatten R=%.7f (was %.7f)" % (rf, bestR))
        if rf > altR:
            alt_cand, altR = hf.copy(), rf
        if rf > bestR + 1e-13:
            best, bestR = hf.copy(), rf

    # ---- Keep the proven machinery ----
    if time.process_time() < deadline - 4.0:
        best, bestR = run_cycle(best, bestR, deadline - 4.0)
        print("base cycle R=%.7f zeros=%.1f%%" %
              (bestR, 100.0 * np.mean(best <= 0)))

    # ---- Another flatten pass now that we've polished ----
    if time.process_time() < deadline - 8.0:
        hf, rf = _flatten_peak(best, bestR, deadline - 7.0, n_rounds=3)
        print("flatten2 R=%.7f" % rf)
        if rf > altR:
            alt_cand, altR = hf.copy(), rf
        if rf > bestR + 1e-13:
            best, bestR = hf.copy(), rf

    # ---- Greedy edit loop if time remains ----
    while time.process_time() < deadline - 6.0:
        st, sr = _greedy_edit_loop(best, bestR, min(deadline - 5.0,
                                                    time.process_time() + 8.0),
                                   None)
        if sr > bestR + 1e-13:
            best, bestR = st, sr
        else:
            break

    if time.process_time() < deadline - 0.5:
        best, bestR = run_cycle(best, bestR, deadline - 0.5)
        print("final cycle R=%.7f" % bestR)

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt_cand is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt_cand
    elif bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _gauge(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_quant(h, tau):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    interior = Lf[1:-1]
    n = interior.size
    if n < 1:
        return _fun_grad_tie(h)
    k = int(tau * (n - 1))
    k = min(max(k, 0), n - 1)
    q = np.partition(interior, k)[k]
    if q <= 0:
        return _fun_grad_tie(h)
    gLf = -dq / num
    tol = 1e-9 * max(q, 1e-300)
    idx = np.flatnonzero(np.abs(Lf - q) <= tol)
    if idx.size == 0:
        idx = np.array([int(np.argmin(np.abs(Lf - q)))])
    w = 1.0 / idx.size
    gLf[idx] += w / q
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(q)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0, tie=False, tau=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if tau is not None:
        fg = (lambda hh: _fun_grad_quant(hh, tau))
    elif beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads=(0.15, 0.10, 0.06, 0.04), iters=400, tie=True):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad_frac=pad, extra=128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_block(h, win, iters, deadline - 0.3, tie=tie)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
    return h


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _quantile_of(h, tau):
    Lf = _knots(h)
    interior = Lf[1:-1]
    n = interior.size
    if n < 1:
        return 0.0
    k = int(tau * (n - 1))
    k = min(max(k, 0), n - 1)
    return float(np.partition(interior, k)[k])


def _detect_staircase(h):
    n = h.size
    mx = h.max()
    if mx <= 0:
        return None, 1
    for p in (1, 2, 3, 4, 5, 8, 16, 32, 64):
        if n % p != 0:
            continue
        m = n // p
        if m < 2:
            continue
        c = h.reshape(m, p).mean(axis=1)
        err = np.max(np.abs(h - np.repeat(c, p))) / mx
        if err < 1e-10:
            return c, p
    return None, 1


def _dilate(idx, n, r):
    if idx.size == 0:
        return idx
    mask = np.zeros(n, dtype=bool)
    mask[idx] = True
    out = mask.copy()
    for d in range(1, r + 1):
        out[d:] |= mask[:-d]
        out[:-d] |= mask[d:]
    return np.flatnonzero(out)


def _max_plateau_window(h, frac=0.9995, extra=256, pad_frac=0.6):
    """Window centered on the near-max plateau, generously padded."""
    Lf = _knots(h)
    mx = Lf.max()
    n = h.size
    if mx <= 0:
        return np.arange(n)
    idx = np.flatnonzero(Lf >= frac * mx)
    lo = max(0, int(idx.min()) - 1)
    hi = min(n - 1, int(idx.max()))
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _scaled_peak_lbfgs(h, deadline, iters=400, maxwin=60000):
    """Optimize only the near-max plateau region, capped in size for speed."""
    win = _max_plateau_window(h, frac=0.999, extra=512, pad_frac=0.8)
    if win.size > maxwin:
        # subsample around plateau: take even stride
        stride = int(np.ceil(win.size / maxwin))
        win = win[::stride]
    h1 = _lbfgs_block(h, win, iters, deadline - 0.3, beta=1e7)
    if R_of(h1) > R_of(h) + 1e-15:
        h = h1
    if time.process_time() < deadline - 0.5:
        h2 = _lbfgs_block(h, win, iters, deadline - 0.3, tie=True)
        if R_of(h2) > R_of(h) + 1e-15:
            h = h2
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    rng = np.random.default_rng(12345)

    # ---- Phase 1: high-beta peak polish, then tie polish on plateau window ----
    # The dominant structure is a broad near-max plateau; a big beta ladder
    # on a generous window around it is the most efficient lever.
    phase1_end = t0 + budget_seconds * 0.35
    betas = [1e3, 1e4, 1e5, 1e6, 1e7, 1e8]
    cyc = 0
    while time.process_time() < phase1_end - 2.0:
        cyc += 1
        prevR = bestR
        for b in betas:
            if time.process_time() >= phase1_end - 1.5:
                break
            win = _max_plateau_window(best, frac=0.999, extra=512, pad_frac=0.8)
            if win.size > 80000:
                stride = int(np.ceil(win.size / 80000))
                win = win[::stride]
            ht = _lbfgs_block(best, win, 300,
                              min(phase1_end - 1.0,
                                  time.process_time() + 5.0), beta=b)
            r = R_of(ht)
            if r > bestR + 1e-16:
                best, bestR = ht.copy(), r
        # final tie polish on plateau
        if time.process_time() < phase1_end - 1.0:
            ht = _scaled_peak_lbfgs(best, phase1_end - 0.5, iters=400)
            r = R_of(ht)
            if r > bestR + 1e-16:
                best, bestR = ht.copy(), r
        f01, f1, f5 = _nearmax_fracs(best)
        print("p1 cyc=%d R=%.9f near=%.3f/%.3f/%.3f"
              % (cyc, bestR, f01, f1, f5))
        if bestR - prevR < 1e-14 and cyc > 1:
            break

    # ---- Phase 2: quantile surrogate ladder (broadens the near-max band) ----
    quant_end = t0 + budget_seconds * 0.55
    taus = [0.95, 0.97, 0.985, 0.99, 0.995, 0.998, 0.999, 0.9995, 0.9999]
    for tau in taus:
        if time.process_time() >= quant_end - 1.0:
            break
        hq = _lbfgs_all_pos(best, 300, quant_end - 0.5, tau=tau)
        r = R_of(hq)
        Lf = _knots(hq)
        M = Lf.max()
        q = _quantile_of(hq, tau)
        ratio = q / M if M > 0 else 0.0
        if r > bestR + 1e-16:
            best, bestR = hq.copy(), r
            print("  q tau=%.4f ACC R=%.9f q/M=%.6f" % (tau, bestR, ratio))
        else:
            print("  q tau=%.4f no  R=%.9f q/M=%.6f" % (tau, r, ratio))

    # ---- Phase 3: exact coordinate descent on staircase (if any) ----
    # If the shape has an underlying coarse staircase, refine coarse coords
    # exactly; this can break local flatness that L-BFGS cannot.
    coord_end = t0 + budget_seconds * 0.72
    c, p = _detect_staircase(best)
    if c is not None and c.size <= 20000:
        print("staircase p=%d m=%d" % (p, c.size))
        work_c = c.copy()

        def Rc(cc):
            s = cc.sum()
            if s <= 0:
                return 0.0
            L = np.concatenate(([0.0], np.convolve(cc, cc), [0.0]))
            a = L[:-1]; b = L[1:]
            num = np.sum(a * a + a * b + b * b) / 3.0
            den = s * s * L.max()
            return num / den if den > 0 else 0.0

        work_R = Rc(work_c)
        cyc2 = 0
        while time.process_time() < coord_end - 3.0:
            cyc2 += 1
            order = rng.permutation(work_c.size)
            moved = 0
            for k in order:
                if time.process_time() > coord_end - 2.0:
                    break
                ck = work_c[k]
                if ck <= 0:
                    continue
                best_d = ck
                br = work_R
                for fac in (0.6, 0.8, 0.9, 1.1, 1.25, 1.6):
                    work_c[k] = ck * fac
                    r = Rc(work_c)
                    if r > br + 1e-16:
                        br = r; best_d = ck * fac
                work_c[k] = best_d
                if br > work_R + 1e-16:
                    work_R = br; moved += 1
            h_new = _rescale(np.repeat(work_c, p))
            # polish
            h_new = _scaled_peak_lbfgs(
                h_new, min(coord_end - 1.0, time.process_time() + 5.0),
                iters=300)
            r_new = R_of(h_new)
            if r_new > bestR + 1e-15:
                best, bestR = h_new.copy(), r_new
                c2, p2 = _detect_staircase(best)
                if c2 is not None and c2.size == work_c.size:
                    work_c = c2.copy(); work_R = Rc(work_c)
            print("  coord cyc=%d R=%.9f moved=%d" % (cyc2, bestR, moved))
            if moved == 0 and cyc2 > 1:
                break

    # ---- Phase 4: full-space tie polish with warm start ----
    fd = t0 + budget_seconds * 0.90
    if time.process_time() < fd - 3.0:
        h_t = _lbfgs_all_pos(best, 400, fd - 1.5, tie=True)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL tie ACC R=%.9f ties=%d" % (bestR, _tie_count(best)))
    if time.process_time() < fd - 1.0:
        h_t = _lbfgs_all_pos(best, 300, fd - 0.3, tie=False)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("FINAL argmax ACC R=%.9f" % bestR)

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f, ties=%d)"
          % (bestR, startR, best.size, _zero_frac(best),
             _nearmax_frac(best), _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, q):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round((1.0 - q) * Lf.size)))
    if m >= Lf.size:
        m = Lf.size - 1
    S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cvar = Lf[S].mean()
    if cvar <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cvar)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cvar)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, free, maxiter, deadline, cvar_q=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    floor = 1e-12 * max(h.max(), 1e-30)
    u0 = np.log(np.clip(h[active], floor, None))
    fg = (lambda hh: _fun_grad_cvar(hh, cvar_q)) if cvar_q is not None else _fun_grad_tie

    def f(u):
        hh = h.copy()
        hh[active] = np.exp(np.clip(u, -40.0, 40.0))
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def _upsample(h, factor):
    """Linear upsample heights by integer factor."""
    n = h.size
    x = np.arange(n, dtype=float)
    xn = np.linspace(0, n - 1, (n - 1) * factor + 1)
    return np.interp(xn, x, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    N = best.size
    allidx = np.arange(N)

    # Stage 1: full-length CVaR homotopy to sharpen the peak region, then exact polish.
    cur = best.copy()
    for q in (0.98, 0.995, 0.999):
        if time.process_time() >= deadline - 2.0:
            break
        tlim = min(deadline - 1.0, time.process_time() + budget_seconds * 0.15)
        cand = _lbfgs_log(cur, allidx, 120, tlim, cvar_q=q)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand.copy(), r
        cur = cand

    # Stage 2: alternate full-length tie polish and peak-window polish.
    cycle = 0
    while time.process_time() < deadline - 1.0:
        cycle += 1
        tlim = min(deadline - 0.5, time.process_time() + budget_seconds * 0.18)
        cand = _lbfgs_log(best, allidx, 80, tlim)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best, bestR = cand.copy(), r

        for pad in (0.05, 0.02):
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=128)
            tlim = min(deadline - 0.4, time.process_time() + budget_seconds * 0.08)
            cand = _lbfgs_log(best, win, 120, tlim)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best, bestR = cand.copy(), r

        print("cycle %d R=%.12f ties=%d" % (cycle, bestR, _tie_count(best)))

    # Stage 3: RESOLUTION refinement. Upsample the best solution, then re-polish
    # at higher resolution. This is the new idea: the current solution sits at a
    # fixed N, but R can improve with finer discretization of the same shape.
    if time.process_time() < deadline - 1.0:
        cur = best.copy()
        curR = bestR
        for factor in (2, 2, 2):
            if time.process_time() >= deadline - 1.0:
                break
            up = _upsample(cur, factor)
            up = _rescale(up)
            r = R_of(up)
            print("upsample x%d -> N=%d R=%.12f" % (factor, up.size, r))
            if up.size > 900000:
                break
            # polish the upsampled solution
            tlim = min(deadline - 0.5, time.process_time() + budget_seconds * 0.20)
            cand = _lbfgs_log(up, np.arange(up.size), 100, tlim)
            rc = R_of(cand)
            if rc > r:
                cand_r = rc
            else:
                cand, cand_r = up, r
            if cand_r > bestR + 1e-15:
                best, bestR = cand.copy(), cand_r
            cur = cand
            curR = cand_r
            # peak-window polish at new resolution
            for pad in (0.05, 0.02):
                if time.process_time() >= deadline - 0.8:
                    break
                win = _peak_window(cur, pad_frac=pad, extra=256)
                tlim = min(deadline - 0.4, time.process_time() + budget_seconds * 0.10)
                cand = _lbfgs_log(cur, win, 120, tlim)
                rc = R_of(cand)
                if rc > bestR + 1e-15:
                    best, bestR = cand.copy(), rc
                    cur = cand
                    curR = rc

    # Final short full polish on best.
    if time.process_time() < deadline - 0.5:
        tlim = min(deadline - 0.2, time.process_time() + budget_seconds * 0.10)
        cand = _lbfgs_log(best, np.arange(best.size), 60, tlim)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best, bestR = cand.copy(), r

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_log(h0, maxiter, deadline):
    """Optimise in log-space over positive entries only (keeps sparsity)."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 1e-14 * h.max())
    if pos.size == 0:
        return h0
    u0 = np.log(h[pos])

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(np.clip(u, -40, 40))
        val, g = _fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40, 40))
    return _rescale(h2)


def _perturb(h, rng, sigma):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    return _rescale(h * np.exp(sigma * rng.standard_normal(h.size)))


def _refine_resample(h, factor):
    n = h.size
    n2 = min(int(n * factor), 900000)
    if n2 <= n:
        return h
    xi = np.linspace(0.0, n - 1, n2)
    return _rescale(np.interp(xi, np.arange(n), h))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(20240117)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 16384
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    cur, curR = best.copy(), bestR

    # Resolution refinement
    if best.size < 400000 and time.process_time() < deadline - 15.0:
        for factor in (1.5, 2.0):
            if time.process_time() > deadline - 15.0:
                break
            hr = _refine_resample(best, factor)
            if hr.size == best.size:
                continue
            ht = _lbfgs_all_pos(hr, 120, deadline, beta=0.0)
            rt = R_of(ht)
            if rt > curR + 1e-14:
                cur, curR = ht, rt
                if curR > bestR + 1e-14:
                    best, bestR = cur.copy(), curR
                print("  refine x%.1f N=%d R=%.7f" % (factor, best.size, bestR))
                break

    beta_seq = [200.0, 800.0, 3000.0, 0.0]
    pass_no = 0
    while time.process_time() < deadline - 3.0:
        pass_no += 1
        b = beta_seq[pass_no % len(beta_seq)]

        if time.process_time() < deadline - 4.0:
            hb = _lbfgs_all_pos(cur, 300, deadline, beta=b)
            rb = R_of(hb)
            if rb > curR + 1e-14:
                cur, curR = hb, rb
            # Also try log-space polish from the current best
            if time.process_time() < deadline - 5.0:
                hl = _lbfgs_log(best, 200, deadline)
                rl = R_of(hl)
                if rl > bestR + 1e-14:
                    best, bestR = hl.copy(), rl
                    cur, curR = hl.copy(), rl
                    print("  log R=%.7f" % bestR)

        if curR > bestR + 1e-14:
            best, bestR = cur.copy(), curR

        if pass_no % 3 == 0 and time.process_time() < deadline - 8.0:
            sigma = 0.0008 + 0.0012 * ((pass_no // 3) % 5)
            cand = _perturb(best, rng, sigma)
            hc = _lbfgs_all_pos(cand, 150, deadline, beta=0.0)
            rc = R_of(hc)
            if rc > bestR + 1e-14:
                best, bestR = hc.copy(), rc
                cur, curR = hc.copy(), rc
                print("  perturb s=%.4f R=%.7f" % (sigma, bestR))

        if pass_no % 4 == 0 and best.size < 500000 and \
                time.process_time() < deadline - 12.0:
            hr = _refine_resample(best, 1.4)
            if hr.size > best.size:
                ht = _lbfgs_all_pos(hr, 150, deadline, beta=1000.0)
                rt = R_of(ht)
                if rt > bestR + 1e-14:
                    best, bestR = ht.copy(), rt
                    cur, curR = ht.copy(), rt
                    print("  re-refine N=%d R=%.7f" % (best.size, bestR))

    if time.process_time() < deadline - 1.0:
        hf = _lbfgs_all_pos(best, 500, deadline, beta=0.0)
        rf = R_of(hf)
        if rf > bestR + 1e-14:
            best, bestR = hf, rf
        if time.process_time() < deadline - 0.5:
            hl = _lbfgs_log(best, 300, deadline)
            rl = R_of(hl)
            if rl > bestR + 1e-14:
                best, bestR = hl, rl

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    if best.size != start_best.size and bestR > start_bestR - 1e-6:
        return {"best": start_best, "alternative": best}
    return start_best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_band(h, lam):
    """Log-space objective with annealed band penalty on 0.90M..0.999M."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return _fun_grad(h)
    lo = 0.90 * M
    hi = 0.999 * M
    band = (Lf >= lo) & (Lf < hi)
    nb = int(band.sum())
    gLf = -dq / num
    pen = 0.0
    if nb > 0:
        d = M - Lf[band]
        pen = lam * np.mean(d * d) / (M * M)
        gLf[band] += lam * (-2.0 * d) / (M * M * nb)
    # exact tie-averaged term at argmax knots
    mx_idx = np.flatnonzero(Lf >= M - 1e-15 * max(1.0, M))
    if mx_idx.size == 0:
        mx_idx = np.array([int(np.argmax(Lf))])
    gLf[mx_idx] += 1.0 / (M * mx_idx.size)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(M) + pen
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, q=0.97, pad_frac=0.15, extra=128):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    thr = q * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _stats(h):
    Lf = _knots(h)
    M = Lf.max()
    num, _, _ = _num_and_dq(h)
    if M <= 0:
        return M, num, 0.0, 0.0, 0.0
    f01 = float(np.mean(Lf >= 0.999 * M))
    f1 = float(np.mean(Lf >= 0.99 * M))
    f5 = float(np.mean(Lf >= 0.95 * M))
    return M, num, f01, f1, f5


def _upsample2(h):
    n = h.size
    out = np.empty(2 * n)
    out[0::2] = h
    out[1::2] = h
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    rng = np.random.default_rng(2024)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    def offer(cand, tag):
        nonlocal best, bestR, alt_best, alt_bestR
        if cand is None or cand.size == 0 or cand.sum() <= 0:
            return False
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand.copy(), r
            M, num, f01, f1, f5 = _stats(best)
            print("NEW BEST R=%.9f (%s) M=%.6f num=%.6f near 0.1%%=%.4f 1%%=%.4f 5%%=%.4f"
                  % (bestR, tag, M, num, f01, f1, f5))
            return True
        elif r > alt_bestR and cand.size == best.size:
            alt_best, alt_bestR = cand.copy(), r
        return False

    # ---- Phase 1: band-penalty ladder ----
    band_deadline = t0 + budget_seconds * 0.35
    for lam in (1e-2, 1e-1, 1.0, 10.0, 100.0):
        if time.process_time() >= band_deadline - 1.0:
            break
        fg = (lambda hh, _l=lam: _fun_grad_band(hh, _l))
        ht = _lbfgs_all_pos(best, 300, band_deadline, fg)
        r = R_of(ht)
        M, num, f01, f1, f5 = _stats(ht)
        print("band lam=%.3g R=%.9f M=%.6f num=%.6f near 0.1%%=%.4f 1%%=%.4f 5%%=%.4f"
              % (lam, r, M, num, f01, f1, f5))
        offer(ht, 'band_%.3g' % lam)

    # ---- Phase 2: monotone alternating exact-tie log-space L-BFGS + peak polish ----
    def exact_fg(hh):
        return _fun_grad(hh)

    def polish_round(h, dl, iters=300):
        # full-array exact-tie
        ht = _lbfgs_all_pos(h, iters, dl, exact_fg)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
        # peak-window polish at 0.97 quantile
        for q in (0.97, 0.95, 0.90):
            if time.process_time() >= dl - 0.5:
                break
            win = _peak_window(h, q=q, pad_frac=0.12, extra=96)
            ht = _lbfgs_block(h, win, iters, dl, exact_fg)
            if R_of(ht) > R_of(h) + 1e-14:
                h = ht
        return h

    # initial polish
    work = best.copy()
    while time.process_time() < t0 + budget_seconds * 0.55 - 1.0:
        prev = R_of(work)
        work = polish_round(work, t0 + budget_seconds * 0.55)
        offer(work, 'polish')
        if R_of(work) <= prev + 1e-15:
            break

    # ---- Phase 3: 2x upsample at 75% of budget + re-polish ----
    up_deadline = t0 + budget_seconds * 0.75
    if time.process_time() < up_deadline - 2.0 and best.size * 2 <= 1000000:
        h_up = _rescale(_upsample2(best))
        h_up = polish_round(h_up, up_deadline, iters=200)
        offer(h_up, 'upsample2x')

    # ---- Phase 4: keep polishing until deadline ----
    work = best.copy()
    while time.process_time() < deadline - 1.0:
        prev = R_of(work)
        work = polish_round(work, deadline, iters=250)
        offer(work, 'final_polish')
        if R_of(work) <= prev + 1e-15:
            # try band penalty as a perturbation
            if time.process_time() < deadline - 2.0:
                fg = (lambda hh: _fun_grad_band(hh, 1.0))
                ht = _lbfgs_all_pos(work, 200, deadline, fg)
                if R_of(ht) > R_of(work) + 1e-14:
                    work = ht
                    offer(work, 'band_perturb')
                    continue
            break

    M, num, f01, f1, f5 = _stats(best)
    print("final R=%.9f (start %.9f, N=%d) M=%.6f num=%.6f near 0.1%%=%.4f 1%%=%.4f 5%%=%.4f"
          % (bestR, start_bestR, best.size, M, num, f01, f1, f5))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _gauss_kernel(sigma):
    r = int(max(1, np.ceil(3.0 * sigma)))
    x = np.arange(-r, r + 1, dtype=float)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    return k, r


def _mollify(L, k, r):
    Lp = np.concatenate((np.zeros(r), L, np.zeros(r)))
    return np.convolve(Lp, k, mode='valid')


def _fun_grad_smooth(h, sigma):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    k, r = _gauss_kernel(sigma)
    Ls = _mollify(Lf, k, r)
    a = Ls[:-1]; b = Ls[1:]
    num_s = np.sum(a * a + a * b + b * b) / 3.0
    if num_s <= 0:
        return 1e18, np.zeros(h.size)
    dq_s = np.zeros_like(Ls)
    dq_s[:-1] += (2 * a + b)
    dq_s[1:] += (a + 2 * b)
    dq_s /= 3.0
    mx = Ls.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    gLs = -dq_s / num_s
    idx = np.flatnonzero(Ls >= mx * (1.0 - 1e-10))
    gLs[idx] += (1.0 / idx.size) / mx
    gLp = np.correlate(gLs, k, mode='valid')
    gL = gLp[r:r + Lf.size]
    gLf = np.zeros_like(Lf)
    gLf[:] = gL
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num_s) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _smooth_lbfgs(h0, deadline, sigma, maxiter=150):
    return _lbfgs_custom(h0, lambda h: _fun_grad_smooth(h, sigma),
                         deadline, maxiter=maxiter)


def _peak_window(h, deadline, bestR, half=None):
    """Optimize only the window around the max of f*f, keep R if improved."""
    n = h.size
    if n < 8:
        return h, bestR
    if half is None:
        half = max(64, n // 8)
    Lf = _knots(h)
    kmax = int(np.argmax(Lf))
    center = kmax - 1
    lo = max(0, center - half)
    hi = min(n, center + half)
    if hi - lo < 4:
        return h, bestR
    pos = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': 200, 'maxfun': 400,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h, bestR
    if res is None:
        return h, bestR
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    h2 = _rescale(h2)
    r2 = R_of(h2)
    if r2 > bestR + 1e-15:
        return h2, r2
    return h, bestR


def _upsample(h, factor):
    """Linear-interpolation resample to factor*n points."""
    n = h.size
    m = n * factor
    x = np.linspace(0, n, m, endpoint=False)
    return np.interp(x, np.arange(n), h)


def _near_max_fracs(h):
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return 0.0, 0.0, 0.0
    return (np.mean(L >= mx * 0.999), np.mean(L >= mx * 0.99),
            np.mean(L >= mx * 0.95))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    # Phase 0: quick exact polish
    while time.process_time() < deadline - 3.0:
        tlim = min(deadline - 2.0, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("polish R=%.12f" % bestR)
        else:
            break

    alt_best = best.copy()
    altR = bestR

    # Phase 1: NEW IDEA — upsample the step function (finer resolution of the
    # same shape) and re-polish at higher N.  This lets the optimizer carve
    # sharper structure into the near-max region of f*f.
    if best.size * 2 <= 1_000_000 and time.process_time() < deadline - 6.0:
        for factor in (2, 2):
            if best.size * factor > 1_000_000:
                break
            if time.process_time() >= deadline - 6.0:
                break
            hup = _rescale(_upsample(best, factor))
            rup = R_of(hup)
            print("upsample x%d: R=%.12f (from %.12f)" % (factor, rup, bestR))
            # polish the upsampled version
            tlim = min(deadline - 4.0, time.process_time() + 8.0)
            hc = _full_lbfgs(hup, tlim, maxiter=300)
            rc = R_of(hc)
            if rc > bestR + 1e-15:
                best = hc; bestR = rc
                print("  upsample-polish R=%.12f N=%d" % (bestR, best.size))
                if bestR > altR:
                    alt_best = best.copy(); altR = bestR
            # also try peak-window polish on the upsampled shape
            if time.process_time() < deadline - 5.0:
                tlim = min(deadline - 4.0, time.process_time() + 6.0)
                hw, rw = _peak_window(hup, tlim, rup)
                if rw > bestR + 1e-15:
                    best = hw; bestR = rw
                    print("  upsample-peak R=%.12f" % bestR)
                    if bestR > altR:
                        alt_best = best.copy(); altR = bestR

    # Phase 2: mollifier annealing (shrinking sigma) on the current best
    sigmas = [32, 16, 8, 4, 2, 1]
    for sigma in sigmas:
        if time.process_time() >= deadline - 2.0:
            break
        tlim = min(deadline - 1.0, time.process_time() + 5.0)
        hc = _smooth_lbfgs(best, tlim, sigma, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            tlim = min(deadline - 0.5, time.process_time() + 3.0)
            hc2 = _full_lbfgs(best, tlim, maxiter=200)
            rc2 = R_of(hc2)
            if rc2 > bestR:
                best = hc2; bestR = rc2
            print("sigma=%d -> R=%.12f" % (sigma, bestR))
            if bestR > altR:
                alt_best = best.copy(); altR = bestR

    # Phase 3: alternate peak-window polish and full polish until deadline
    while time.process_time() < deadline - 0.5:
        improved = False
        # peak window around the max
        tlim = min(deadline - 0.5, time.process_time() + 4.0)
        hw, rw = _peak_window(best, tlim, bestR)
        if rw > bestR + 1e-15:
            best = hw; bestR = rw
            improved = True
            if bestR > altR:
                alt_best = best.copy(); altR = bestR
        # full polish
        if time.process_time() < deadline - 0.5:
            tlim = min(deadline - 0.3, time.process_time() + 4.0)
            hc = _full_lbfgs(best, tlim, maxiter=200)
            rc = R_of(hc)
            if rc > bestR + 1e-15:
                best = hc; bestR = rc
                improved = True
                if bestR > altR:
                    alt_best = best.copy(); altR = bestR
        if not improved:
            break

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    alt = alt_best if altR > 0 else best

    f1, f2, f3 = _near_max_fracs(best)
    print("final R=%.12f (start %.12f, N=%d, altR=%.12f)"
          % (bestR, startR, best.size, altR))
    print("near-max fracs 0.1%%/1%%/5%%: %.4f / %.4f / %.4f" % (f1, f2, f3))

    return {"best": best, "alternative": alt}

