    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fg(hh)

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _escalate(h, N):
    h = np.asarray(h, dtype=float)
    n = len(h)
    if n == N:
        return _rescale(h.copy())
    c = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, c[-1], N + 1)
    newc = np.interp(xs, np.linspace(0.0, c[-1], n + 1), c)
    out = np.diff(newc)
    return _rescale(np.maximum(out, 0.0))


def _polish(h, deadline, n_cycles=8):
    h = _rescale(np.asarray(h, dtype=float))
    best = h.copy()
    bestR = R_of(best)

    def try_update(hh):
        nonlocal best, bestR
        R = R_of(hh)
        if R > bestR + 1e-12:
            bestR = R
            best = hh.copy()
        return R

    if time.process_time() < deadline - 0.5:
        slice_end = min(deadline, time.process_time() + 0.30 * (deadline - time.process_time()))
        hh = _lbfgs_all_pos(best, 300, slice_end)
        try_update(hh)

    for beta in [50.0, 200.0, 800.0]:
        if time.process_time() >= deadline - 0.5:
            break
        slice_end = min(deadline, time.process_time() + 0.10 * (deadline - time.process_time()))
        hh = _lbfgs_all_pos(best, 200, slice_end, beta=beta)
        try_update(hh)

    cycle = 0
    while time.process_time() < deadline - 0.4 and cycle < n_cycles * 6:
        cycle += 1
        if cycle % 3 == 0:
            slice_end = min(deadline, time.process_time() + 0.15 * (deadline - time.process_time()))
            hh = _lbfgs_all_pos(best, 200, slice_end)
        else:
            win = _peak_window(best, tol=0.999, pad_frac=0.5, extra=128)
            slice_end = min(deadline, time.process_time() + 0.10 * (deadline - time.process_time()))
            hh = _lbfgs_block(best, win, 200, slice_end)
        try_update(hh)
    return best


def _smooth(h, k):
    """Light smoothing by a small box kernel (keeps shape, reduces noise)."""
    if k <= 1:
        return h
    ker = np.ones(k) / k
    return _rescale(np.convolve(h, ker, mode='same'))


def construct(budget_seconds, start):
    t0 = time.process_time()
    total = budget_seconds
    hard_deadline = t0 + total * 0.94

    best_h = None
    best_R = -1.0
    start_h = None
    start_R = -1.0

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            start_h = _rescale(s.copy())
            start_R = R_of(start_h)
            best_h = start_h.copy()
            best_R = start_R

    if best_h is None:
        best_h = np.ones(512)
        best_R = R_of(best_h)

    # ---- Stage 1: polish the start directly ----
    slice_end = t0 + total * 0.35
    hp = _polish(best_h, slice_end)
    Rp = R_of(hp)
    if Rp > best_R:
        best_h = hp
        best_R = Rp
    print(f"start-polish R={best_R:.6f} (from {start_R:.6f})")

    # ---- Stage 2: escalate and polish, keeping alternative ----
    alt_h = None
    alt_R = -1.0
    n0 = len(best_h)
    for f in [1.5, 2.0]:
        if time.process_time() > hard_deadline - 1.0:
            break
        N = int(max(64, min(1000000, n0 * f)))
        h = _escalate(best_h, N)
        slice_end = min(hard_deadline, time.process_time() + (hard_deadline - time.process_time()) * 0.35)
        hp = _polish(h, slice_end)
        Rp = R_of(hp)
        if Rp > best_R:
            alt_h = best_h.copy(); alt_R = best_R
            best_h = hp
            best_R = Rp
            print(f"escalate N={N} R={best_R:.6f}")
        else:
            if Rp > alt_R:
                alt_h = hp; alt_R = Rp
            print(f"escalate N={N} R={Rp:.6f} (kept {best_R:.6f})")

    # ---- Stage 3: smoothing-aware refinement ----
    # Try a lightly smoothed version at same N (helps escape local maxima
    # caused by isolated spikes) and re-polish.
    if time.process_time() < hard_deadline - 2.0:
        n = best_h.size
        k = max(3, n // 4000)
        hs = _smooth(best_h, k)
        slice_end = min(hard_deadline, time.process_time() + (hard_deadline - time.process_time()) * 0.30)
        hp = _polish(hs, slice_end)
        Rp = R_of(hp)
        if Rp > best_R:
            alt_h = best_h.copy(); alt_R = best_R
            best_h = hp
            best_R = Rp
            print(f"smooth R={best_R:.6f}")
        else:
            if Rp > alt_R:
                alt_h = hp; alt_R = Rp
            print(f"smooth R={Rp:.6f} (kept {best_R:.6f})")

    # ---- Stage 4: final long polish ----
    if time.process_time() < hard_deadline:
        hp = _polish(best_h, hard_deadline, n_cycles=12)
        Rp = R_of(hp)
        if Rp > best_R:
            alt_h = best_h.copy(); alt_R = best_R
            best_h = hp
            best_R = Rp

    best_h = _rescale(best_h)
    final_R = R_of(best_h)
    print(f"final R={final_R:.6f}")

    # Return best (and alternative if genuinely different and useful)
    if start_h is not None and start_R > final_R:
        return {"best": start_h, "alternative": best_h}
    if alt_h is not None and alt_h.size != best_h.size and alt_R > 0:
        # Provide the escalated alternative as a fresh starting line
        return {"best": best_h, "alternative": _rescale(alt_h)}
    return best_h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, maxiter=120):
    L = _knots(h)
    pk = int(np.argmax(L))
    n = h.size
    center = (pk - 1) // 2
    half = max(64, n // 8)
    lo = max(0, center - half)
    hi = min(n, center + half)
    if hi <= lo:
        return h
    sub = h[lo:hi].copy()
    if sub.sum() <= 0:
        return h

    def fg(u):
        hh = h.copy()
        hh[lo:hi] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[lo:hi] * hh[lo:hi]

    u0 = np.log(np.clip(sub, 1e-12, None))
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(fg, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * sub.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[lo:hi] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _coarsen(h, M):
    N = h.size
    if M >= N:
        return h.copy(), None
    bs = N // M
    if bs < 1:
        return h.copy(), None
    # sum disjoint blocks; remainder into last block
    main = h[:bs * M].reshape(M, bs).sum(axis=1)
    rem = h[bs * M:].sum()
    main[-1] += rem
    return main, bs


def _prolongate(coarse, bs, N):
    h = np.repeat(coarse, bs)
    if h.size < N:
        h = np.concatenate([h, np.full(N - h.size, coarse[-1] / max(bs, 1))])
    elif h.size > N:
        h = h[:N]
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    alt_best = None
    altR = 0.0

    # --- Coarse-grid multigrid phase ---
    N = h0.size
    for M in [64, 128]:
        if time.process_time() > deadline - 8.0:
            break
        coarse, bs = _coarsen(h0, M)
        if bs is None:
            continue
        coarse = _rescale(coarse)
        cR0 = R_of(coarse)
        tlim = min(deadline - 6.0, time.process_time() + 12.0)
        coarse_opt = _lbfgs_custom(coarse, _fun_grad_tie, tlim, maxiter=300)
        cR = R_of(coarse_opt)
        fine = _prolongate(coarse_opt, bs, N)
        fine = _rescale(fine)
        fR = R_of(fine)
        print("M=%d coarseR %.12f -> %.12f prolongR %.12f"
              % (M, cR0, cR, fR))
        if fR > bestR + 1e-12:
            best = fine.copy()
            bestR = fR
            print("  coarse accepted R=%.12f" % bestR)
        else:
            if alt_best is None or fR > altR:
                alt_best = fine.copy()
                altR = fR

    # --- Polish best with full L-BFGS + peak-window ---
    while time.process_time() < deadline - 2.0:
        tlim = min(deadline - 1.0, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("polish R=%.12f" % bestR)
        else:
            break

    while time.process_time() < deadline - 1.5:
        tlim = min(deadline - 0.8, time.process_time() + 3.0)
        hc = _peak_window_polish(best, tlim, maxiter=120)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("peak-window R=%.12f" % bestR)
            hc2 = _full_lbfgs(best, min(deadline - 0.5, time.process_time() + 2.0), maxiter=150)
            rc2 = R_of(hc2)
            if rc2 > bestR + 1e-15:
                best = hc2; bestR = rc2
                print("polish R=%.12f" % bestR)
        else:
            break

    if bestR < startR + 1e-9:
        best = h0.copy()
        bestR = startR

    if alt_best is None or altR <= 0:
        alt = best
    else:
        alt = alt_best

    print("final R=%.12f (start %.12f, N=%d, altR=%.12f)"
          % (bestR, startR, best.size, altR))

    return {"best": best, "alternative": alt}

