        return val, g[lo:hi] * hh[lo:hi]

    u0 = np.log(np.clip(sub, 1e-12, None))
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(fg, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * sub.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[lo:hi] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _coarsen(h, M):
    N = h.size
    if M >= N:
        return h.copy(), None
    bs = N // M
    if bs < 1:
        return h.copy(), None
    # sum disjoint blocks; remainder into last block
    main = h[:bs * M].reshape(M, bs).sum(axis=1)
    rem = h[bs * M:].sum()
    main[-1] += rem
    return main, bs


def _prolongate(coarse, bs, N):
    h = np.repeat(coarse, bs)
    if h.size < N:
        h = np.concatenate([h, np.full(N - h.size, coarse[-1] / max(bs, 1))])
    elif h.size > N:
        h = h[:N]
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.12f (N=%d)" % (bestR, best.size))

    alt_best = None
    altR = 0.0

    # --- Coarse-grid multigrid phase ---
    N = h0.size
    for M in [64, 128]:
        if time.process_time() > deadline - 8.0:
            break
        coarse, bs = _coarsen(h0, M)
        if bs is None:
            continue
        coarse = _rescale(coarse)
        cR0 = R_of(coarse)
        tlim = min(deadline - 6.0, time.process_time() + 12.0)
        coarse_opt = _lbfgs_custom(coarse, _fun_grad_tie, tlim, maxiter=300)
        cR = R_of(coarse_opt)
        fine = _prolongate(coarse_opt, bs, N)
        fine = _rescale(fine)
        fR = R_of(fine)
        print("M=%d coarseR %.12f -> %.12f prolongR %.12f"
              % (M, cR0, cR, fR))
        if fR > bestR + 1e-12:
            best = fine.copy()
            bestR = fR
            print("  coarse accepted R=%.12f" % bestR)
        else:
            if alt_best is None or fR > altR:
                alt_best = fine.copy()
                altR = fR

    # --- Polish best with full L-BFGS + peak-window ---
    while time.process_time() < deadline - 2.0:
        tlim = min(deadline - 1.0, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("polish R=%.12f" % bestR)
        else:
            break

    while time.process_time() < deadline - 1.5:
        tlim = min(deadline - 0.8, time.process_time() + 3.0)
        hc = _peak_window_polish(best, tlim, maxiter=120)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("peak-window R=%.12f" % bestR)
            hc2 = _full_lbfgs(best, min(deadline - 0.5, time.process_time() + 2.0), maxiter=150)
            rc2 = R_of(hc2)
            if rc2 > bestR + 1e-15:
                best = hc2; bestR = rc2
                print("polish R=%.12f" % bestR)
        else:
            break

    if bestR < startR + 1e-9:
        best = h0.copy()
        bestR = startR

    if alt_best is None or altR <= 0:
        alt = best
    else:
        alt = alt_best

    print("final R=%.12f (start %.12f, N=%d, altR=%.12f)"
          % (bestR, startR, best.size, altR))

    return {"best": best, "alternative": alt}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, deadline, maxiter=200):
    """L-BFGS in log-space over positive entries; keeps zeros pinned."""
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 1e-300)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-10 * hmax
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * pos.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _smooth_peak_fun_grad(h, p=8.0):
    """Softmax over knots approximating ||f*f||_inf; drives many knots to max."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    z = p * (Lf - mx)
    z = np.clip(z, -60, 0)
    e = np.exp(z)
    Z = e.sum()
    w = e / Z
    # smoothed max value and its gradient w.r.t. Lf
    sm = mx + np.log(Z) / p
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _lbfgs_smooth(h0, p, deadline, maxiter=200):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 1e-300)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-10 * hmax
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = _smooth_peak_fun_grad(hh, p)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * pos.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))
    f01, f1, f5 = _fracs(best)
    print("fracs before: 0.1%%=%.4f 1%%=%.4f 5%%=%.4f" % (f01, f1, f5))

    alt_best = None
    altR = -1.0

    def _record(hc, tag):
        nonlocal best, bestR, alt_best, altR
        r = R_of(hc)
        f01, f1, f5 = _fracs(hc)
        mx = _knots(hc).max()
        mean = hc.mean() if hc.mean() > 0 else 1.0
        print("%s R=%.12f fracs 0.1%%=%.4f 1%%=%.4f 5%%=%.4f max/mean=%.1f"
              % (tag, r, f01, f1, f5, mx / mean))
        if r > altR:
            altR = r
            alt_best = hc.copy()
        if r > bestR + 1e-16:
            best, bestR = hc.copy(), r
            return True
        return False

    # Main loop: alternate smoothing (drives more knots near max) and exact tie polish.
    cyc = 0
    while time.process_time() < deadline - 2.0:
        improved = False
        # Smooth-peak stages: increasing p focuses more sharply on the max
        for p in (4.0, 8.0, 16.0, 32.0):
            if time.process_time() >= deadline - 2.0:
                break
            tlim = min(deadline - 1.5, time.process_time() + 5.0)
            hc = _lbfgs_smooth(best, p, tlim, maxiter=120)
            if _record(hc, "cyc%d p=%.0f" % (cyc, p)):
                improved = True
            if time.process_time() >= deadline - 2.0:
                break
            tlim2 = min(deadline - 1.0, time.process_time() + 4.0)
            hp = _lbfgs_log(hc, tlim2, maxiter=100)
            if _record(hp, "cyc%d tie" % cyc):
                improved = True
        cyc += 1
        if not improved and cyc > 2:
            # Small extra smoothing pass to try to escape
            if time.process_time() < deadline - 2.0:
                tlim = min(deadline - 1.5, time.process_time() + 5.0)
                hc = _lbfgs_smooth(best, 2.0, tlim, maxiter=100)
                _record(hc, "cyc%d p=2" % cyc)

    # Final exact polish on best
    if time.process_time() < deadline - 1.0:
        hp = _lbfgs_log(best, min(deadline - 0.5, time.process_time() + 5.0),
                        maxiter=150)
        _record(hp, "final")

    if bestR < startR:
        best = _rescale(np.clip(np.asarray(start, dtype=float), 0, None))
        bestR = startR

    f01, f1, f5 = _fracs(best)
    print("fracs after: 0.1%%=%.4f 1%%=%.4f 5%%=%.4f" % (f01, f1, f5))
    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if alt_best is not None and altR <= startR + 1e-14 and alt_best.shape == best.shape:
        result["alternative"] = alt_best
    elif bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_softmax(h, beta):
    """Smooth max via log-sum-exp; beta large -> closer to true max."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _fun_grad_cap(h, Mt, lam):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    hn = h / s
    num, dq, Lf = _num_and_dq(hn)
    nk = Lf.size
    over = np.maximum(Lf - Mt, 0.0)
    pen = lam * np.mean(over * over) / (Mt * Mt)
    gLf = -dq / num
    gLf += lam * 2.0 * over / (Mt * Mt * nk)
    mx = Lf.max()
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    ghn = _backprop(gLf, hn)
    proj = ghn - np.dot(ghn, hn)
    grad = proj / s
    val = -np.log(num) + pen + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, fun_grad, deadline, maxiter=150):
    """Optimize in log-space over positive entries."""
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _peak_window(h, tol=0.999, pad_frac=0.5, extra=128):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


# ---------- sharp staircase machinery ----------

def _build_sharp(u, b, N):
    M = u.size
    a = np.exp(np.clip(u, -40.0, 40.0))
    bounds = np.clip(np.asarray(b, dtype=int), 1, N - 1)
    for j in range(1, M - 1):
        if bounds[j] < bounds[j - 1] + 1:
            bounds[j] = bounds[j - 1] + 1
    h = np.empty(N)
    prev = 0
    for j in range(M - 1):
        bb = bounds[j]
        if bb < prev:
            bb = prev
        h[prev:bb] = a[j]
        prev = bb
    h[prev:] = a[M - 1]
    return h


def _fun_grad_sharp(u, b, N):
    h = _build_sharp(u, b, N)
    val, gh = _fun_grad_tie(h)
    M = u.size
    a = np.exp(np.clip(u, -40.0, 40.0))
    bounds = np.clip(np.asarray(b, dtype=int), 1, N - 1)
    for j in range(1, M - 1):
        if bounds[j] < bounds[j - 1] + 1:
            bounds[j] = bounds[j - 1] + 1
    gu = np.zeros(M)
    gb = np.zeros(M - 1)
    prev = 0
    for j in range(M - 1):
        bb = bounds[j]
        if bb < prev:
            bb = prev
        seg = slice(prev, bb)
        gu[j] += np.sum(gh[seg]) * a[j]
        prev = bb
    gu[M - 1] += np.sum(gh[prev:]) * a[M - 1]
    prev = 0
    for j in range(M - 1):
        bb = bounds[j]
        if bb < prev:
            bb = prev
        if 1 <= bb < N - 1:
            gb[j] = gh[bb - 1] - gh[bb]
        prev = bb
    return val, (gu, gb)


def _optimize_sharp(u0, b0, N, deadline, maxiter=200):
    M = u0.size
    if M < 2:
        return _build_sharp(u0, b0, N)
    x0 = np.concatenate([u0, np.asarray(b0, dtype=float)])

    def f(x):
        u = x[:M]
        b = x[M:]
        val, (gu, gb) = _fun_grad_sharp(u, b, N)
        return val, np.concatenate([gu, gb])

    bounds = [(-40.0, 40.0)] * M + [(1.0, float(N - 1))] * (M - 1)
    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=bounds, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return _build_sharp(u0, b0, N)
    if res is None:
        return _build_sharp(u0, b0, N)
    u = res.x[:M]
    b = np.round(res.x[M:]).astype(int)
    h = _build_sharp(u, b, N)
    return _rescale(h)


def _init_sharp_from_h(h, M):
    N = h.size
    c = np.cumsum(h)
    total = c[-1]
    if total <= 0:
        a = np.ones(M)
        bounds = np.linspace(0, N, M + 1).astype(int)[1:-1]
        return np.log(a), bounds
    targets = total * np.linspace(0, 1, M + 1)[1:-1]
    bounds = np.searchsorted(c, targets)
    bounds = np.clip(bounds, 1, N - 1)
    for j in range(1, M - 1):
        if bounds[j] < bounds[j - 1] + 1:
            bounds[j] = bounds[j - 1] + 1
    a = np.empty(M)
    prev = 0
    for j in range(M - 1):
        bb = bounds[j]
        if bb < prev:
            bb = prev
        if bb > prev:
            a[j] = h[prev:bb].mean()
        else:
            a[j] = h[prev] if prev < N else 1.0
        prev = bb
    a[M - 1] = h[prev:].mean() if prev < N else 1.0
    a = np.clip(a, 1e-12, None)
    return np.log(a), bounds


def _upsample(h, n):
    x_old = np.linspace(0.0, 1.0, h.size)
    x_new = np.linspace(0.0, 1.0, n)
    return _rescale(np.clip(np.interp(x_new, x_old, h), 0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    candidates = []

    def record(h, name):
        if h is None:
            return
        r = R_of(h)
        candidates.append((r, h.copy(), name))
        print("  branch %s R=%.12f (d=%.2e)" % (name, r, r - startR))

    # ---------------------------------------------------------------
    # NEW IDEA: improve the max term via soft-max ladder at increasing
    # beta combined with peak-window refinement. Alternate full-array
    # log-space LBFGS with peak-window LBFGS.
    # ---------------------------------------------------------------
    def peak_refine(h, bestR, tlim):
        pos = _peak_window(h, tol=0.999, pad_frac=0.4, extra=64)
        if pos.size < 4:
            return h, bestR
        hmax = h.max()
        floor = 1e-12 * hmax if hmax > 0 else 1e-12
        u0 = np.log(np.clip(h[pos], floor, None))

        def f(u):
            hh = h.copy()
            hh[pos] = np.exp(u)
            val, g = _fun_grad_tie(hh)
            return val, g[pos] * hh[pos]

        cb = _make_cb(tlim - 0.2)
        try:
            res = minimize(f, u0, jac=True, method='L-BFGS-B',
                           bounds=[(-40.0, 40.0)] * pos.size,
                           callback=cb,
                           options={'maxiter': 200, 'maxfun': 400,
                                    'ftol': 1e-20, 'gtol': 1e-16})
        except (TimeoutError, Exception):
            return h, bestR
        if res is None:
            return h, bestR
        h2 = h.copy()
        h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
        h2 = _rescale(h2)
        r2 = R_of(h2)
        if r2 > bestR + 1e-15:
            return h2, r2
        return h, bestR

    # Softmax ladder — smooths ties then converges to true max
    if time.process_time() < deadline - 1.0:
        hS = best.copy()
        for beta in (1e2, 1e3, 1e4, 1e5, 1e6, 1e7):
            if time.process_time() >= deadline - 0.5:
                break
            tlim = min(deadline - 0.4, time.process_time() + 1.5)
            hS = _lbfgs_log(hS, lambda hh: _fun_grad_softmax(hh, beta),
                            tlim, maxiter=120)
        record(hS, "softmax")

    # Cap penalty — cap at just under current max, forcing flattening
    if time.process_time() < deadline - 1.0:
        hC = best.copy()
        Lf = _knots(hC)
        Mt = Lf.max() * 0.9995
        for lam in (1e2, 1e3, 1e4):
            if time.process_time() >= deadline - 0.5:
                break
            tlim = min(deadline - 0.4, time.process_time() + 2.0)
            hC = _lbfgs_log(hC, lambda hh: _fun_grad_cap(hh, Mt, lam),
                            tlim, maxiter=120)
            Lf = _knots(hC)
            Mt = min(Mt, Lf.max() * 0.9995)
        record(hC, "cap")

    # Sharp staircase on upsampled version
    if time.process_time() < deadline - 1.0:
        for M in (128, 256, 512):
            if time.process_time() >= deadline - 1.0:
                break
            u0, b0 = _init_sharp_from_h(best, M)
            tlim = min(deadline - 0.5, time.process_time() + 3.0)
            hA = _optimize_sharp(u0, b0, best.size, tlim, maxiter=200)
            record(hA, "sharp%d" % M)

    for r, h, name in candidates:
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    print("after branches best R=%.12f (start %.12f)" % (bestR, startR))

    # ---------- Final race: alternate softmax / peak-window / sharp ----------
    rnd = 0
    Ms = [256, 512, 1024, 2048]
    while time.process_time() < deadline - 0.5:
        rnd += 1
        # full tie polish
        tlim = min(deadline - 0.4, time.process_time() + 2.5)
        h1 = _lbfgs_log(best, _fun_grad_tie, tlim, maxiter=150)
        r1 = R_of(h1)
        if r1 > bestR + 1e-15:
            best, bestR = h1.copy(), r1
        # peak window refinement (targets the tight max)
        if time.process_time() < deadline - 0.5:
            tlim = min(deadline - 0.3, time.process_time() + 2.0)
            h2, r2 = peak_refine(best, bestR, tlim)
            if r2 > bestR + 1e-15:
                best, bestR = h2.copy(), r2
        # sharp staircase at increasing M
        M = Ms[(rnd - 1) % len(Ms)]
        if M <= best.size and time.process_time() < deadline - 0.5:
            u0, b0 = _init_sharp_from_h(best, M)
            tlim = min(deadline - 0.3, time.process_time() + 3.0)
            h3 = _optimize_sharp(u0, b0, best.size, tlim, maxiter=150)
            r3 = R_of(h3)
            if r3 > bestR + 1e-15:
                best, bestR = h3.copy(), r3
        # softmax occasionally
        if rnd % 2 == 0 and time.process_time() < deadline - 0.4:
            tlim = min(deadline - 0.3, time.process_time() + 1.5)
            h4 = _lbfgs_log(best, lambda hh: _fun_grad_softmax(hh, 1e6),
                            tlim, maxiter=100)
            r4 = R_of(h4)
            if r4 > bestR + 1e-15:
                best, bestR = h4.copy(), r4

    if bestR < startR:
        best, bestR = _rescale(np.clip(np.asarray(start, dtype=float), 0, None)), startR

    print("final R=%.12f (start %.12f, N=%d, ties=%d)"
          % (bestR, startR, best.size, _tie_count(best)))

    result = {"best": best}
    if candidates:
        r, h, name = max(candidates, key=lambda t: t[0])
        if r > startR - 1e-12 and r < bestR - 1e-15:
            result["alternative"] = h
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cap(h, Mt, lam):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    hn = h / s
    num, dq, Lf = _num_and_dq(hn)
    nk = Lf.size
    over = np.maximum(Lf - Mt, 0.0)
    pen = lam * np.mean(over * over) / (Mt * Mt)
    gLf = -dq / num
    gLf += lam * 2.0 * over / (Mt * Mt * nk)
    mx = Lf.max()
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    ghn = _backprop(gLf, hn)
    proj = ghn - np.dot(ghn, hn)
    grad = proj / s
    val = -np.log(num) + pen + np.log(mx)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _cap_lbfgs(h0, Mt, lam, deadline, maxiter=150):
    return _lbfgs_custom(h0, lambda hh: _fun_grad_cap(hh, Mt, lam),
                         deadline, maxiter=maxiter)


def _peak_window(h, deadline, bestR, half=None):
    n = h.size
    if n < 8:
        return h, bestR
    if half is None:
        half = max(64, n // 8)
    Lf = _knots(h)
    kmax = int(np.argmax(Lf))
    center = kmax - 1
    lo = max(0, center - half)
    hi = min(n, center + half)
    if hi - lo < 4:
        return h, bestR
    pos = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': 200, 'maxfun': 400,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h, bestR
    if res is None:
        return h, bestR
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    h2 = _rescale(h2)
    r2 = R_of(h2)
    if r2 > bestR + 1e-15:
        return h2, r2
    return h, bestR


def _near_max_fractions(h):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 0.0, 0.0, 0.0
    return (np.mean(Lf >= 0.999 * M),
            np.mean(Lf >= 0.99 * M),
            np.mean(Lf >= 0.95 * M))


def _importance(h):
    s = h.sum()
    if s <= 0:
        return np.zeros_like(h)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    g = _backprop(gLf, h)
    return h * np.abs(g)


# ---------------- integer support moves ----------------

def _runs(h):
    """Return list of (start, end) inclusive indices of maximal nonzero runs."""
    nz = h > 0
    if not nz.any():
        return []
    d = np.diff(nz.astype(np.int8))
    starts = list(np.flatnonzero(d == 1) + 1)
    ends = list(np.flatnonzero(d == -1))
    if nz[0]:
        starts = [0] + starts
    if nz[-1]:
        ends = ends + [h.size - 1]
    return list(zip(starts, ends))


def _move_boundary(h, run, side, delta):
    """Shift a run boundary by delta cells (delta>0 = expand run into gap,
    delta<0 = shrink run). Mass of removed edge cell moves to adjacent gap
    cell; filling a gap cell takes mass from the neighbouring active cell."""
    h = h.copy()
    n = h.size
    s, e = run
    if side == 'left':
        if delta > 0:
            # expand left: fill cells s-1..s-delta from cell s
            for k in range(delta):
                j = s - 1 - k
                if j < 0:
                    return None
                h[j] = h[s]
                h[s] = 0.0
                s = j
        else:
            # shrink left: move cells s..s+(-delta)-1 to gap cell s-1
            for k in range(-delta):
                i = s + k
                if i > e:
                    return None
                if s - 1 - k < 0:
                    return None
                h[s - 1 - k] = h[i]
                h[i] = 0.0
    else:  # right
        if delta > 0:
            for k in range(delta):
                j = e + 1 + k
                if j >= n:
                    return None
                h[j] = h[e]
                h[e] = 0.0
                e = j
        else:
            for k in range(-delta):
                i = e - k
                if i < s:
                    return None
                if e + 1 + k >= n:
                    return None
                h[e + 1 + k] = h[i]
                h[i] = 0.0
    return h


def _split_run(h, run, idx):
    """Zero cell idx inside run, redistribute its height to neighbours."""
    h = h.copy()
    s, e = run
    if idx <= s or idx >= e:
        return None
    m = h[idx]
    if m <= 0:
        return None
    h[idx] = 0.0
    h[idx - 1] += m * 0.5
    h[idx + 1] += m * 0.5
    return h


def _merge_runs(h, run_a, run_b):
    """Fill gap between two runs, taking mass from nearest active cells."""
    h = h.copy()
    sa, ea = run_a
    sb, eb = run_b
    if sb <= ea + 1:
        return None
    gap = sb - ea - 1
    # take mass from ea and sb, distribute into gap
    m = 0.5 * (h[ea] + h[sb])
    h[ea] *= 0.5
    h[sb] *= 0.5
    per = m / gap
    for j in range(ea + 1, sb):
        h[j] = per
    return h


def _candidate_moves(h):
    """Yield candidate arrays from integer boundary/split/merge moves."""
    runs = _runs(h)
    n = h.size
    cands = []
    for ri, run in enumerate(runs):
        s, e = run
        for side in ('left', 'right'):
            for delta in (1, 2, -1, -2):
                c = _move_boundary(h, run, side, delta)
                if c is not None and c.sum() > 0:
                    cands.append(c)
        # splits at interior cells
        if e - s >= 3:
            for idx in (s + 1, e - 1, (s + e) // 2):
                c = _split_run(h, run, idx)
                if c is not None and c.sum() > 0:
                    cands.append(c)
        # merge with next run
        if ri + 1 < len(runs):
            c = _merge_runs(h, run, runs[ri + 1])
            if c is not None and c.sum() > 0:
                cands.append(c)
    return cands


def _boundary_sensitivity(h):
    """Score each boundary by |gradient| at the edge cells (importance)."""
    imp = _importance(h)
    runs = _runs(h)
    scores = []
    for ri, (s, e) in enumerate(runs):
        sc = 0.0
        if s > 0:
            sc += imp[s] + imp[s - 1]
        if e < h.size - 1:
            sc += imp[e] + imp[e + 1]
        scores.append((sc, ri))
    scores.sort(reverse=True)
    return [ri for _, ri in scores]


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.96

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    f01, f1, f5 = _near_max_fractions(best)
    print("base R=%.12f (N=%d) fracs 0.1%%=%.4f 1%%=%.4f 5%%=%.4f"
          % (bestR, best.size, f01, f1, f5))

    alt_best = None
    alt_bestR = -1.0

    # ---------- Phase I: integer boundary/split/merge search ----------
    phaseI_end = min(deadline - 1.0, t0 + budget_seconds * 0.92)
    print("=== integer support move search ===")
    accepted_count = 0
    cycle = 0
    while time.process_time() < phaseI_end - 4.0:
        cycle += 1
        order = _boundary_sensitivity(best)
        runs = _runs(best)
        if not order:
            break
        # build candidate list, prioritized by sensitivity
        cands = []
        for ri in order:
            run = runs[ri]
            s, e = run
            for side in ('left', 'right'):
                for delta in (1, -1, 2, -2):
                    c = _move_boundary(best, run, side, delta)
                    if c is not None and c.sum() > 0:
                        cands.append(c)
            if e - s >= 3:
                for idx in (s + 1, e - 1, (s + e) // 2):
                    c = _split_run(best, run, idx)
                    if c is not None and c.sum() > 0:
                        cands.append(c)
            if ri + 1 < len(runs):
                c = _merge_runs(best, run, runs[ri + 1])
                if c is not None and c.sum() > 0:
                    cands.append(c)
        if not cands:
            break
        gained = False
        for ci, cand in enumerate(cands):
            if time.process_time() > phaseI_end - 4.0:
                break
            hc = _rescale(cand)
            r_pre = R_of(hc)
            # quick polish
            tlim = min(phaseI_end, time.process_time() + 2.0)
            hp = _full_lbfgs(hc, tlim, maxiter=100)
            rp = R_of(hp)
            tlim = min(phaseI_end, time.process_time() + 2.0)
            hw, rw = _peak_window(hp, tlim, rp)
            if rw > rp:
                hp, rp = hw, rw
            if rp > bestR + 1e-12:
                best = hp.copy()
                bestR = rp
                gained = True
                accepted_count += 1
                f01, f1, f5 = _near_max_fractions(best)
                print("move cycle=%d cand=%d R_pre=%.12f R=%.12f fracs 0.1%%=%.4f 1%%=%.4f 5%%=%.4f"
                      % (cycle, ci, r_pre, bestR, f01, f1, f5))
                break
            else:
                if rp > alt_bestR:
                    alt_bestR = rp
                    alt_best = hp.copy()
        if not gained:
            print("cycle=%d no move accepted (R=%.12f)" % (cycle, bestR))
            break

    print("integer search done: %d accepted, R=%.12f" % (accepted_count, bestR))

    # ---------- Phase B: full L-BFGS + peak-window polish ----------
    phaseB_end = min(deadline - 0.5, t0 + budget_seconds * 0.99)
    while time.process_time() < phaseB_end - 1.0:
        tlim = min(phaseB_end, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        gained = False
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("full R=%.12f" % bestR)
            gained = True
        tlim = min(phaseB_end, time.process_time() + 3.0)
        hw, rw = _peak_window(best, tlim, bestR)
        if rw > bestR + 1e-15:
            best = hw; bestR = rw
            print("peakwin R=%.12f" % bestR)
            gained = True
        if not gained:
            break

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    f01, f1, f5 = _near_max_fractions(best)
    print("final R=%.12f (start %.12f, N=%d) fracs 0.1%%=%.4f 1%%=%.4f 5%%=%.4f"
          % (bestR, startR, best.size, f01, f1, f5))

    if alt_best is not None and alt_bestR > startR + 1e-15 and alt_bestR > bestR + 1e-15:
        return {"best": alt_best, "alternative": best}
    if bestR > startR + 1e-15:
        out = {"best": best}
        if alt_best is not None and alt_best is not best:
            out["alternative"] = alt_best
        else:
            out["alternative"] = best
        return out
    if alt_best is not None and alt_bestR > 0:
        return {"best": h0, "alternative": alt_best}
    return {"best": h0, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return 1e18, np.zeros(h.size)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=1e7):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_beta(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _lbfgs_all(h0, maxiter, deadline, beta=1e7):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0

    def f(x):
        hh = np.clip(x, 0.0, None)
        return _fun_grad_beta(hh, beta)

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _peak_window(h, pad_frac, extra):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= 0.9995 * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_ladder(h, deadline, pads, iters, beta=1e7):
    for pad in pads:
        if time.process_time() >= deadline - 0.5:
            break
        win = _peak_window(h, pad, 128)
        ht = _lbfgs_block(h, win, iters, deadline - 0.3, beta=beta)
        if R_of(ht) > R_of(h) + 1e-14:
            h = ht
    return h


def _local_peak_perturb(h, rng, strength):
    h = h.copy()
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    idx = np.flatnonzero(Lf >= 0.95 * mx)
    lo = max(0, idx.min())
    hi = min(h.size, idx.max() + 1)
    wlen = max(1, int((hi - lo) * 0.5))
    s = max(0, lo)
    e = min(h.size, hi + wlen)
    noise = 1.0 + strength * rng.standard_normal(e - s)
    h[s:e] *= np.clip(noise, 0.0, None)
    return _rescale(h)


def _zero_frac(h):
    return float(np.mean(h <= 0))


def _nearmax_frac(h, frac=0.95):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= frac * mx))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d, zero_frac=%.4f, nearmax5=%.4f)"
          % (bestR, best.size, _zero_frac(best), _nearmax_frac(best)))

    rng = np.random.default_rng(20240417)

    # Phase 1: peak-localized perturbation + beta-LBFGS (soft-max) exploration.
    # The soft-max beta schedule lets the optimizer move knots that are close
    # to but not exactly tied at the maximum; this can reshape ties.
    phase1_end = t0 + budget_seconds * 0.55
    tries = 0
    accepted = 0
    cur = best.copy()
    while time.process_time() < phase1_end - 3.0:
        tries += 1
        if tries == 1:
            cand = cur.copy()
        else:
            strength = rng.uniform(0.05, 0.35)
            cand = _local_peak_perturb(cur, rng, strength)
        slice_end = min(phase1_end, time.process_time() + 6.0)
        # soft-max full pass first
        h = _lbfgs_all(cand, 300, slice_end - 3.5, beta=1e5)
        if time.process_time() < slice_end - 3.0:
            h = _lbfgs_all(h, 200, slice_end - 2.5, beta=1e7)
        if time.process_time() < slice_end - 2.0:
            h = _peak_ladder(h, slice_end - 0.5,
                             pads=(0.10, 0.06, 0.04), iters=200, beta=1e7)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            cur = h.copy()
            accepted += 1
            print("P1 try %d ACCEPT R=%.9f (+%.2e)" % (tries, r, r - startR))
        elif r > bestR - 1e-7:
            cur = h.copy()
        if tries % 10 == 0:
            print("P1 tries=%d accepted=%d best=%.9f" % (tries, accepted, bestR))

    # Phase 2: final polish
    fd = t0 + budget_seconds * 0.92
    it = 0
    while time.process_time() < fd - 3.0:
        it += 1
        slice_end = min(fd, time.process_time() + 7.0)
        h_t = _lbfgs_all(best, 400, slice_end - 3.0, beta=1e7)
        r_t = R_of(h_t)
        if r_t > bestR + 1e-15:
            best, bestR = h_t.copy(), r_t
            print("P2 tie %d ACCEPT R=%.9f" % (it, bestR))
        if time.process_time() < slice_end - 2.0:
            h_t = _peak_ladder(best, slice_end - 0.5,
                               pads=(0.08, 0.05, 0.03), iters=250, beta=1e7)
            r_t = R_of(h_t)
            if r_t > bestR + 1e-15:
                best, bestR = h_t.copy(), r_t
                print("P2 peak %d ACCEPT R=%.9f" % (it, bestR))

    print("final R=%.9f (start %.9f, N=%d, zero_frac=%.4f, nearmax5=%.4f)"
          % (bestR, startR, best.size, _zero_frac(best), _nearmax_frac(best)))

    result = {"best": best}
    if bestR <= startR + 1e-14 and start is not None:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _polish_coarse(cs, slice_dl, maxiter=100):
    if time.process_time() >= slice_dl - 1.5:
        return cs
    cs = _lbfgs_all_pos(cs, maxiter, slice_dl - 1.0, beta=1e6)
    if time.process_time() >= slice_dl - 1.5:
        return cs
    cs = _lbfgs_all_pos(cs, maxiter, slice_dl - 1.0, beta=1e7)
    if time.process_time() >= slice_dl - 1.5:
        return cs
    cs = _lbfgs_all_pos(cs, maxiter, slice_dl - 1.0, beta=0.0)
    return cs


def _lift_split(c, seed, slice_dl, maxiter=80):
    rs = np.random.RandomState(seed)
    w = np.exp(0.25 * rs.randn(2))
    w = w * 2.0 / w.sum()
    h = _rescale(np.repeat(c, 2) * np.tile(w, c.size))
    if time.process_time() < slice_dl - 1.5:
        h = _lbfgs_all_pos(h, maxiter, slice_dl - 1.0, beta=1e7)
    return h


def _lift_linear(c, slice_dl, maxiter=80):
    n0 = c.size
    x_old = np.linspace(0.0, 1.0, n0)
    x_new = np.linspace(0.0, 1.0, 2 * n0)
    h = np.interp(x_new, x_old, c)
    h = _rescale(np.clip(h, 0, None))
    if time.process_time() < slice_dl - 1.5:
        h = _lbfgs_all_pos(h, maxiter, slice_dl - 1.0, beta=1e7)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    alt_best = None
    alt_bestR = -1.0

    # ---- Phase 1: half-resolution polish, alternate lift strategies ----
    if best.size % 2 == 0 and best.size >= 4 and time.process_time() < deadline - 3.0:
        c = best[0::2].copy()
        half_deadline = t0 + budget_seconds * 0.22
        work_c = c.copy()
        best_c = c.copy()
        best_cR = R_of(c)
        rounds = 0
        while time.process_time() < half_deadline - 1.0:
            if time.process_time() >= half_deadline - 1.5:
                break
            work_c = _polish_coarse(work_c, half_deadline, maxiter=120)
            r = R_of(work_c)
            if r > best_cR + 1e-14:
                best_c, best_cR = work_c.copy(), r
            rounds += 1
        print("half-res rounds=%d R(c)=%.9f" % (rounds, best_cR))
        for lift_fn, tag in ((lambda cc: _rescale(np.repeat(cc, 2)), 'rep'),
                             (lambda cc: _lift_linear(cc, deadline - 1.0, 40), 'lin')):
            if time.process_time() >= deadline - 2.0:
                break
            h_lift = lift_fn(best_c)
            ht = h_lift
            for beta in [1e6, 1e7]:
                if time.process_time() >= deadline - 1.0:
                    break
                ht = _lbfgs_all_pos(ht, 250, deadline - 0.5, beta=beta)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR, origin = ht.copy(), r, 'lift_' + tag
                print("lift(%s) NEW BEST R=%.9f" % (tag, bestR))
            elif r > alt_bestR:
                alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 2: deep stride ladder with mixed lifts ----
    cascade_start = t0 + budget_seconds * 0.22
    cascade_end = deadline - 4.0
    if time.process_time() < cascade_start:
        while time.process_time() < cascade_start - 0.05:
            time.sleep(0.005)
    cyc = 0
    while cyc < 6 and time.process_time() < cascade_end - 1.0:
        now = time.process_time()
        slice_dl = min(now + 8.0, deadline - 5.0)
        if slice_dl <= now + 1.0:
            break
        c = best.copy()
        ok = True
        for i, s in enumerate((16, 8, 4, 2)):
            if time.process_time() >= slice_dl - 1.5:
                ok = False
                break
            if c.size % 2 != 0:
                ok = False
                break
            cs = c[0::2].copy()
            cs = _polish_coarse(cs, slice_dl, maxiter=80)
            if time.process_time() >= slice_dl - 1.5:
                ok = False
                break
            if (cyc + i) % 3 == 0:
                c = _lift_linear(cs, slice_dl, maxiter=60)
            else:
                c = _lift_split(cs, 9000 + 97 * cyc + s, slice_dl, maxiter=60)
        if not ok:
            print("cycle %d aborted mid-ladder" % cyc)
            cyc += 1
            continue
        h = c
        if time.process_time() < slice_dl - 1.5:
            h = _lbfgs_all_pos(h, 120, slice_dl - 1.0, beta=1e6)
        if time.process_time() < slice_dl - 1.5:
            h = _lbfgs_all_pos(h, 120, slice_dl - 1.0, beta=1e7)
        if time.process_time() < slice_dl - 1.5:
            win = _peak_window(h, 0.06, 128)
            h = _lbfgs_block(h, win, 200, slice_dl - 1.0, beta=1e7)
        if time.process_time() < slice_dl - 1.5:
            h = _lbfgs_all_pos(h, 150, slice_dl - 1.0, beta=0.0)
        r_h = R_of(h)
        accepted = r_h > bestR + 5e-14
        if accepted:
            best, bestR, origin = h.copy(), r_h, 'ladder_%d' % cyc
        elif r_h > alt_bestR:
            alt_best, alt_bestR = h.copy(), r_h
        print("cycle %d R(h)=%.9f %s best=%.9f"
              % (cyc, r_h, "ACCEPT" if accepted else "reject", bestR))
        cyc += 1

    # ---- Phase 3: fine peak polish ladder ----
    if time.process_time() < deadline - 1.0:
        for pad in [0.10, 0.06, 0.04, 0.02]:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=pad, extra=96)
            ht2 = _lbfgs_block(best, win, 350, deadline - 0.3, beta=1e7)
            r2 = R_of(ht2)
            if r2 > bestR + 1e-14:
                best, bestR, origin = ht2.copy(), r2, origin + '+pk'
                print("final peak NEW BEST R=%.9f" % bestR)
            elif r2 > alt_bestR:
                alt_best, alt_bestR = ht2.copy(), r2

    if time.process_time() < deadline - 0.8:
        ht = _lbfgs_all_pos(best, 250, deadline - 0.4, beta=0.0)
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR, origin = ht.copy(), r, origin + '+b0'
            print("trailing beta0 NEW BEST R=%.9f" % bestR)
        elif r > alt_bestR:
            alt_best, alt_bestR = ht.copy(), r

    # ---- Phase 4 (NEW): fine local polish of the full-resolution best ----
    # The main gains come from resolving the peak region finely. Repeatedly
    # run shrinking peak windows with the exact objective (beta=0) at the
    # largest N we have, which is where improvements concentrate.
    if time.process_time() < deadline - 0.5:
        for half in [int(best.size * 0.15), int(best.size * 0.08),
                     int(best.size * 0.04), int(best.size * 0.02)]:
            if time.process_time() >= deadline - 0.5:
                break
            half = max(64, half)
            Lf = _knots(best)
            kmax = int(np.argmax(Lf))
            center = max(0, kmax - 1)
            lo = max(0, center - half)
            hi = min(best.size, center + half)
            if hi - lo < 4:
                continue
            win = np.arange(lo, hi)
            for beta in (1e7, 0.0):
                if time.process_time() >= deadline - 0.4:
                    break
                ht3 = _lbfgs_block(best, win, 300, deadline - 0.3, beta=beta)
                r3 = R_of(ht3)
                if r3 > bestR + 1e-15:
                    best, bestR, origin = ht3.copy(), r3, origin + '+p4'
                    print("phase4 half=%d NEW BEST R=%.9f" % (half, bestR))
                elif r3 > alt_bestR:
                    alt_best, alt_bestR = ht3.copy(), r3

    print("final R=%.9f origin=%s (start %.9f, N=%d)" %
          (bestR, origin, start_bestR, best.size))

    result = {"best": best}
    if alt_best is not None and alt_best.size == best.size and alt_bestR < bestR:
        result["alternative"] = alt_best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _make_fg(kind, param):
    if kind == 'tie':
        return _fun_grad_tie
    if kind == 'beta':
        return lambda hh: _fun_grad_beta(hh, param)
    if kind == 'cvar':
        return lambda hh: _fun_grad_cvar(hh, param)
    return _fun_grad_tie


def _lbfgs_log(h0, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, fg):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _stats(h):
    Lf = _knots(h)
    mx = Lf.max()
    m = int(np.argmax(Lf))
    near = int(np.sum(Lf >= 0.999 * mx))
    return mx, m, near


def _restrict(h, f, o):
    n = h.size
    hr = np.roll(h, -o)
    m = n // f
    hr = hr[:m * f]
    return hr.reshape(m, f).mean(axis=1)


def _prolong(hc, f, o, n):
    up = np.repeat(hc, f)
    if up.size < n:
        up = np.concatenate((up, np.full(n - up.size, up[-1] if up.size else 0.0)))
    else:
        up = up[:n]
    return np.roll(up, o)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        return np.arange(h.size)
    lo = max(0, int(idx.min()) - 1)
    hi = min(h.size - 1, int(idx.max()))
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _upsample_lin(h, n):
    x_old = np.linspace(0.0, 1.0, h.size)
    x_new = np.linspace(0.0, 1.0, n)
    return _rescale(np.clip(np.interp(x_new, x_old, h), 0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            baseH = _rescale(base)
            baseR = R_of(baseH)
        else:
            baseH, baseR = None, 0.0
    else:
        baseH, baseR = None, 0.0

    if baseH is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        baseH = _rescale(h)
        baseR = R_of(baseH)

    mx0, m0, near0 = _stats(baseH)
    print("base R=%.9f (N=%d) Lmax=%.6e argmax=%d near0.1%%=%d" %
          (baseR, baseH.size, mx0, m0, near0))

    bestH = baseH.copy()
    bestR = baseR
    n = baseH.size
    fg_tie = _fun_grad_tie

    # Phase 0: sharpen the plateau at the start's resolution (cheap, in-place).
    if time.process_time() < deadline - 8.0:
        w = _peak_window(bestH, tol=0.999, pad_frac=0.6, extra=512)
        cap = min(deadline - 4.0, time.process_time() + 6.0)
        hp = _lbfgs_block(bestH, w, 400, cap, fg_tie)
        rp = R_of(hp)
        if rp > bestR + 1e-14:
            bestH, bestR = hp.copy(), rp
            print("  phase0 window polish: R=%.9f" % bestR)

    def try_cycle(h_cur, f, o, time_cap, fg):
        if time.process_time() >= time_cap - 0.5:
            return h_cur, R_of(h_cur)
        hc = _restrict(h_cur, f, o)
        if hc.size < 8:
            return h_cur, R_of(h_cur)
        hc = _rescale(hc)
        rc0 = R_of(hc)
        cap = min(time_cap - 0.3, time.process_time() + 5.0)
        hc = _lbfgs_log(hc, 350, cap, fg)
        rc = R_of(hc)
        hp = _prolong(hc, f, o, n)
        hp = _rescale(hp)
        rp = R_of(hp)
        cap = min(time_cap - 0.2, time.process_time() + 3.0)
        hp = _lbfgs_log(hp, 250, cap, fg)
        rp2 = R_of(hp)
        cap = min(time_cap - 0.2, time.process_time() + 2.0)
        hp = _lbfgs_log(hp, 150, cap, fg_tie)
        rp3 = R_of(hp)
        print("  f=%d o=%d: coarse %.9f -> %.9f | prolong %.9f -> %.9f -> %.9f" %
              (f, o, rc0, rc, rp, rp2, rp3))
        return hp, rp3

    # Phase 1: multigrid scan on the start's grid.
    scan_cap = min(deadline, t0 + budget_seconds * 0.45)
    results = {}
    fgs = [('tie', None), ('beta', 200.0), ('beta', 800.0)]
    for f in (2, 3, 4):
        for o in range(f):
            for kind, param in fgs:
                if time.process_time() >= scan_cap - 1.0:
                    break
                fg = _make_fg(kind, param)
                hp, rp = try_cycle(bestH, f, o, scan_cap, fg)
                key = (f, o, kind, param)
                results[key] = (hp, rp)
                if rp > bestR + 1e-14:
                    bestH, bestR = hp.copy(), rp
                    print("  >>> new best from %s: R=%.9f" % (str(key), bestR))

    # Phase 2: REFINEMENT -- upsample the best solution to a finer grid and
    # re-polish. This is the key new idea: the start is grid-limited, so a
    # finer discretization can capture more of the plateau and raise R.
    refine_cap = min(deadline, t0 + budget_seconds * 0.75)
    target_N = min(1_000_000, max(n * 2, 200_000))
    if bestH.size < target_N and time.process_time() < refine_cap - 5.0:
        # Try a couple of refinement levels, keeping whichever helps.
        cur = bestH
        curR = bestR
        for mult in (2, 2):
            newN = min(target_N, cur.size * mult)
            if newN <= cur.size:
                break
            if time.process_time() >= refine_cap - 4.0:
                break
            hu = _upsample_lin(cur, newN)
            ru = R_of(hu)
            cap = min(refine_cap - 2.0, time.process_time() + 8.0)
            hu2 = _lbfgs_log(hu, 400, cap, fg_tie)
            ru2 = R_of(hu2)
            # Also polish the peak window at the new resolution.
            if time.process_time() < refine_cap - 2.0:
                w = _peak_window(hu2, tol=0.999, pad_frac=0.5, extra=1024)
                cap = min(refine_cap - 1.0, time.process_time() + 4.0)
                hu3 = _lbfgs_block(hu2, w, 300, cap, fg_tie)
                ru3 = R_of(hu3)
                if ru3 > ru2:
                    hu2, ru2 = hu3, ru3
            print("  refine N=%d: %.9f -> %.9f -> %.9f" %
                  (newN, ru, ru2, curR))
            if ru2 > curR + 1e-15:
                cur, curR = hu2, ru2
                if curR > bestR + 1e-14:
                    bestH, bestR = cur.copy(), curR
                    n = bestH.size
            else:
                # Upsampling didn't help; stop refining further.
                break

    # Phase 3: on the (possibly finer) grid, alternate cycles + window polish.
    round_i = 0
    while time.process_time() < deadline - 2.0:
        round_i += 1
        improved = False
        # Pick the best recent cycle key if any, else use f=2,o=0,tie.
        if results:
            f, o, kind, param = max(results.keys(),
                                    key=lambda k: results[k][1])
        else:
            f, o, kind, param = 2, 0, 'tie', None
        fg = _make_fg(kind, param)
        hp, rp = try_cycle(bestH, f, o, deadline - 1.0, fg)
        if rp > bestR + 1e-14:
            bestH, bestR = hp.copy(), rp
            improved = True
            print("  round %d cycle improved: R=%.9f" % (round_i, bestR))
        if time.process_time() < deadline - 2.0:
            w = _peak_window(bestH, tol=0.999, pad_frac=0.5, extra=1024)
            cap = min(deadline - 1.0, time.process_time() + 3.0)
            hp = _lbfgs_block(bestH, w, 300, cap, fg_tie)
            rp = R_of(hp)
            if rp > bestR + 1e-14:
                bestH, bestR = hp.copy(), rp
                improved = True
                print("  round %d window improved: R=%.9f" % (round_i, bestR))
        if not improved and time.process_time() > deadline - 6.0:
            break

    # Final full polish.
    if time.process_time() < deadline - 1.0:
        cap = min(deadline - 0.5, time.process_time() + 2.5)
        hs = _lbfgs_log(bestH, 200, cap, fg_tie)
        rs = R_of(hs)
        if rs > bestR + 1e-14:
            bestH, bestR = hs.copy(), rs

    mx, m, near = _stats(bestH)
    print("final N=%d R=%.9f zeros %.1f%% Lmax=%.6e argmax=%d near0.1%%=%d" %
          (bestH.size, bestR, 100.0 * np.mean(bestH <= 0), mx, m, near))

    if bestR > baseR + 1e-12:
        return {"best": bestH, "alternative": baseH}
    else:
        alt = baseH
        if results:
            k = max(results.keys(), key=lambda k: results[k][1])
            rk = results[k][1]
            if rk > baseR + 1e-12:
                alt = results[k][0]
        return {"best": baseH, "alternative": alt}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_all_pos(h0, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g

    cb = _make_cb(deadline - 0.2)
    opts = {'maxiter': maxiter, 'maxfun': 2 * maxiter,
            'ftol': 1e-20, 'gtol': 1e-16}
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb, options=opts)
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, tie=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad_tie(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.05, extra=64):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _peak_polish(h, deadline, iters=150):
    if time.process_time() >= deadline - 0.3:
        return h
    win = _peak_window(h, pad_frac=0.05, extra=64)
    ht = _lbfgs_block(h, win, iters, deadline - 0.2, tie=True)
    if R_of(ht) > R_of(h) + 1e-14:
        return ht
    return h


def _mass_resample(base, newN):
    n = base.size
    c = np.cumsum(base)
    tot = c[-1]
    if tot <= 0:
        return _rescale(np.ones(newN))
    c = c / tot
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(newN) + 0.5) / newN
    cm = np.interp(x_new, x_old, c, left=0.0, right=1.0)
    h = np.diff(np.concatenate(([0.0], cm)))
    h = np.clip(h, 0, None)
    return _rescale(h)


def _jitter(h, rng, sigma=0.05):
    n = h.size
    out = h.copy()
    i = 0
    while i < n:
        blk = int(rng.integers(2, 33))
        j = min(n, i + blk)
        f = np.exp(rng.normal(0.0, sigma))
        out[i:j] *= f
        i = j
    return _rescale(np.clip(out, 0, None))


def _jitter_round(h, deadline, rng, rounds=4, iters=200):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        cand = _jitter(best, rng, sigma=0.05)
        cand = _lbfgs_all_pos(cand, iters, deadline - 0.3, tie=True)
        if time.process_time() < deadline - 0.5:
            cand = _peak_polish(cand, deadline - 0.2, iters=100)
        r = R_of(cand)
        if r > bestR + 1e-14:
            best = cand
            bestR = r
    return best


def _ladder(seed, levels, deadline, rng, rounds=4):
    h = seed
    best_small = None
    best_smallR = -1.0
    for n_new in levels:
        if time.process_time() >= deadline - 1.0:
            break
