        h2 = _peak_polish(h2, deadline - 0.2, iters=250)
    if R_of(h2) > R_of(h) + 1e-14:
        return h2
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.95
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_arr = _rescale(base)
            startR = R_of(start_arr)
        else:
            start_arr, startR = None, 0.0
    else:
        start_arr, startR = None, 0.0

    print("start R=%.9f (N=%s)" % (startR,
          start_arr.size if start_arr is not None else 0))

    # ============ Phase A: resample start down to small N, polish ============
    phaseA_end = t0 + budget_seconds * 0.15
    small_best = None
    small_bestR = -1.0
    if start_arr is not None:
        for n_small in (512, 1024):
            if time.process_time() >= phaseA_end - 0.5:
                break
            hs = _mass_resample(start_arr, n_small)
            hs = _lbfgs_all_pos(hs, 300, phaseA_end - 0.3, tie=True)
            r = R_of(hs)
            print("PhaseA N=%d R=%.9f" % (n_small, r))
            if r > small_bestR:
                small_bestR = r
                small_best = hs.copy()
    if small_best is None:
        small_best = _rescale(np.ones(1024))
        small_bestR = R_of(small_best)

    # ============ Phase B: ladder up from best small state ============
    phaseB_end = t0 + budget_seconds * 0.80
    levels = [1024, 2048, 4096, 8192, 16384, 32768, 65536]

    print("Chain 1 (from start):")
    h1, s1, s1R = _ladder(small_best.copy(), levels, phaseB_end, rng, rounds=4)
    r1 = R_of(h1)

    # Chain 2: symmetrized seed (different construction: symmetric submanifold)
    print("Chain 2 (symmetric):")
    h2, s2, s2R, r2 = None, None, -1.0, -1.0
    if time.process_time() < phaseB_end - 2.0:
        sym_seed = _symmetrize(small_best.copy())
        sym_seed = _lbfgs_all_pos(sym_seed, 400, phaseB_end - 1.0, tie=True)
        print("  sym seed R=%.9f" % R_of(sym_seed))
        h2, s2, s2R = _ladder(sym_seed, levels, phaseB_end, rng, rounds=4)
        r2 = R_of(h2)

    best = h1
    bestR = r1
    if h2 is not None and r2 > bestR:
        best = h2
        bestR = r2
    alt_small = s1
    alt_smallR = s1R
    if s2 is not None and s2R > alt_smallR:
        alt_small = s2
        alt_smallR = s2R

    print("PhaseB best R=%.9f (N=%d)" % (bestR, best.size))

    # ============ Phase C: plateau push + jitter on best ============
    while time.process_time() < deadline - 1.0:
        cand = _plateau_push(best, deadline - 0.5, rng, iters=400)
        r = R_of(cand)
        if r > bestR + 1e-14:
            best = cand
            bestR = r
            print("PhaseC improved R=%.9f" % bestR)
            continue
        cand = _jitter_round(best, deadline - 0.5, rng, rounds=3, iters=250)
        r = R_of(cand)
