    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _true_polish(h, deadline, rounds=2):
    cur = h
    cur_r = R_of(cur)
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        cand = _lbfgs_log(cur, maxiter=400, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= deadline - 1.0:
            break
        cand = _window_polish_peak(cur, deadline, 0.10, 8, maxiter=400)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def _hard_threshold(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = h.max()
    h = h.copy()
    h[h < 1e-3 * mx] = 0.0
    return h


def _block_perturb(h, rng):
    n = h.size
    B = int(rng.choice([64, 128, 256]))
    B = min(B, n)
    edges = np.linspace(0, n, B + 1).astype(int)
    out = h.copy()
    zero_frac = rng.uniform(0.10, 0.30)
    for i in range(B):
        lo, hi = edges[i], edges[i + 1]
        if hi <= lo:
            continue
        if rng.random() < zero_frac:
            out[lo:hi] = 0.0
        else:
            f = np.exp(rng.uniform(-1.0, 1.0))
            out[lo:hi] *= f
    if out.sum() <= 0:
        return h.copy()
    return _rescale(out)


def _sparse_seed(N, rng):
    nblk = int(rng.integers(20, 41))
    edges = np.linspace(0, N, nblk + 1).astype(int)
    out = np.zeros(N)
    zero_frac = rng.uniform(0.40, 0.70)
    for i in range(nblk):
        lo, hi = edges[i], edges[i + 1]
        if hi <= lo:
            continue
        if rng.random() < zero_frac:
            continue
        val = np.exp(rng.uniform(np.log(30.0), np.log(1000.0)))
        out[lo:hi] = val
    if out.sum() <= 0:
        out[:] = 1.0
    return _rescale(out)


def _homotopy(cand, deadline, betas=(2, 4, 8, 16, 32, 64, 128), maxiter=250):
    cur = cand
    cur_r = R_of(cur)
    for beta in betas:
        if time.process_time() >= deadline - 1.0:
            break
        c = _lbfgs_sm(cur, beta, maxiter=maxiter, deadline=deadline)
        r = R_of(c)
        if r > cur_r:
            cur, cur_r = c, r
    if time.process_time() < deadline - 1.0:
        c = _lbfgs_log(cur, maxiter=600, deadline=deadline)
        r = R_of(c)
        if r > cur_r:
            cur, cur_r = c, r
    if time.process_time() < deadline - 1.0:
        c = _window_polish_peak(cur, deadline, 0.10, 8, maxiter=400)
        r = R_of(c)
        if r > cur_r:
            cur, cur_r = c, r
    return cur, cur_r


# -------- NEW: coordinate/pattern refinement on the discrete heights --------
def _coord_refine(h, deadline, sweeps=2, mults=(0.5, 0.8, 0.9, 1.1, 1.25, 2.0)):
    """Coordinate-wise multiplicative hill climb on a subset of heights."""
    cur = h.copy()
    cur_r = R_of(cur)
    n = cur.size
    # Focus on non-tiny entries (others barely matter for R)
    thr = 1e-4 * cur.max()
    pos = np.flatnonzero(cur > thr)
    if pos.size == 0:
        return cur, cur_r
    rng = np.random.default_rng(7)
    for _ in range(sweeps):
        if time.process_time() >= deadline - 0.5:
            break
        # iterate in a random order over active positions
        order = pos.copy()
        rng.shuffle(order)
        improved_any = False
        for i in order:
            if time.process_time() >= deadline - 0.5:
                break
            base = cur[i]
            if base <= 0:
                continue
            best_local = cur_r
            best_val = base
            for m in mults:
                trial = cur.copy()
                trial[i] = base * m
                r = R_of(trial)
                if r > best_local:
                    best_local = r
                    best_val = base * m
            if best_local > cur_r + 1e-14:
                cur[i] = best_val
                cur_r = best_local
                improved_any = True
        if not improved_any:
            break
    return cur, cur_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    cur = _rescale(best.copy())
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r

    N0 = 32768
    if cur.size != N0:
        cand = _coarsen(cur, N0)
        cand = _rescale(cand)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r

    improved = False
    for beta in (4, 8, 16, 32, 64):
        if time.process_time() >= deadline - 6.0:
            break
        cand = _lbfgs_sm(cur, beta, maxiter=300, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
            improved = True

    if time.process_time() < deadline - 4.0:
        cand, r = _true_polish(cur, deadline, rounds=2)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
            improved = True

    # NEW: coordinate refinement on the incumbent before escalating resolution
    if time.process_time() < deadline - 8.0:
        cand, r = _coord_refine(cur, deadline, sweeps=2)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
            improved = True

    if improved and time.process_time() < deadline - 3.0:
        for N in (65536, 131072, 262144):
            if time.process_time() >= deadline - 4.0:
                break
            if cur.size == N:
                cand = cur.copy()
            else:
                cand = _prolongate(cur, N)
                cand = _rescale(cand)
            for beta in (16, 64):
                if time.process_time() >= deadline - 4.0:
                    break
                c2 = _lbfgs_sm(cand, beta, maxiter=200, deadline=deadline)
                r2 = R_of(c2)
                if r2 > R_of(cand):
                    cand = c2
            cand, r = _true_polish(cand, deadline, rounds=2)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

    rng = np.random.default_rng(12345)
    baseline = best_r
    near_count = 0
    restart_count = 0
    incumbent = cur.copy()
    inc_r = cur_r

    while time.process_time() < deadline - 1.0:
        if time.process_time() >= deadline - 1.0:
            break
        restart_count += 1
        if restart_count % 2 == 1:
            cand = _block_perturb(incumbent, rng)
        else:
            cand = _sparse_seed(8192, rng)
        cand = _hard_threshold(cand)
        cand = _rescale(cand)
        if cand.sum() <= 0:
            continue
        cand, r = _homotopy(cand, deadline)
        cand = _hard_threshold(cand)
        cand = _rescale(cand)
        r = R_of(cand)
        if abs(r - baseline) < 1e-4:
            near_count += 1
        if r > inc_r:
            incumbent = cand.copy()
            inc_r = r
        if r > best_r:
            best, best_r = cand.copy(), r
            if time.process_time() < deadline - 2.0 and best.size != 65536:
                big = _prolongate(best, 65536)
                big = _rescale(big)
                big, rb = _homotopy(big, deadline)
                big = _hard_threshold(big)
                big = _rescale(big)
                rb = R_of(big)
                if rb > best_r:
                    best, best_r = big.copy(), rb

    if time.process_time() < deadline - 0.5:
        c = _lbfgs_log(best, maxiter=800, deadline=deadline)
        r = R_of(c)
        if r > best_r:
            best, best_r = c, r
        if time.process_time() < deadline - 0.5:
            c = _window_polish_peak(best, deadline, 0.10, 8, maxiter=400)
            r = R_of(c)
            if r > best_r:
                best, best_r = c, r

    print(f"restarts={restart_count} near_baseline={near_count} best={best_r:.6f}")

    best = _rescale(best)
    if start_arr is not None:
        return {"best": best, "alternative": _rescale(start_arr)}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_pos(h0, fun_grad, maxiter, deadline):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size

    def f(x):
        hh = np.clip(x, 0.0, None)
        return fun_grad(hh)

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    return _rescale(np.clip(res.x, 0.0, None))


def _lbfgs_block(h0, free, maxiter, deadline, fun_grad):
    if time.process_time() >= deadline - 0.2:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.15)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _densify(h):
    h = np.clip(h, 0, None)
    pos = h[h > 0]
    if pos.size == 0:
        return h
    eps = 1e-6 * pos.mean()
    out = h.copy()
    out[out <= 0] = eps
    return _rescale(out)


def _band_frac(h, tol):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    return float(np.mean(Lf >= (1.0 - tol) * mx))


def _sharpen(h, deadline, iters=6):
    if time.process_time() >= deadline - 0.5:
        return h
    cur = h.copy()
    curR = R_of(cur)
    for k in range(iters):
        if time.process_time() >= deadline - 0.5:
            break
        beta = 10.0 ** (3 + 1.5 * k)
        ht = _lbfgs_pos(cur, lambda hh, b=beta: _fun_grad_beta(hh, b),
                        400, deadline - 0.5)
        r = R_of(ht)
        if r > curR + 1e-14:
            cur, curR = ht, r
        else:
            cur = ht
        if time.process_time() < deadline - 0.5:
            ht = _lbfgs_pos(cur, _fun_grad_tie, 300, deadline - 0.5)
            r = R_of(ht)
            if r > curR + 1e-14:
                cur, curR = ht, r
    return cur if R_of(cur) >= R_of(h) else h


def _smooth(h, w):
    """Box-smooth h with window w (integer). Preserves mass."""
    if w <= 1:
        return h
    k = np.ones(w, dtype=float)
    out = np.convolve(h, k, mode='same')
    return out


def _refine(h, deadline, sub_iters=3):
    """NEW: upsample by 2x via linear interpolation, then polish at higher
    resolution. This is the main structural change: it lets the optimizer
    find finer peak structure that coarse N cannot represent."""
    if time.process_time() >= deadline - 2.0:
        return h
    n = h.size
    if n * 2 > 1000000:
        return h
    x_old = np.linspace(0, 1, n)
    x_new = np.linspace(0, 1, 2 * n)
    h2 = np.interp(x_new, x_old, h)
    h2 = _rescale(np.clip(h2, 0, None))
    r2 = R_of(h2)
    if r2 <= 0:
        return h
    cur = h2
    curR = r2
    for _ in range(sub_iters):
        if time.process_time() >= deadline - 1.5:
            break
        ht = _lbfgs_pos(cur, _fun_grad_tie, 800, deadline - 1.5)
        r = R_of(ht)
        if r > curR + 1e-14:
            cur, curR = ht, r
        else:
            cur = ht
        for beta in [1e6, 1e7, 1e8]:
            if time.process_time() >= deadline - 1.5:
                break
            ht = _lbfgs_pos(cur, lambda hh, b=beta: _fun_grad_beta(hh, b),
                            300, deadline - 1.5)
            r = R_of(ht)
            if r > curR + 1e-14:
                cur, curR = ht, r
    if curR > R_of(h) + 1e-13:
        return cur
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase A: sharpen the peak structure.
    if time.process_time() < deadline - 1.5:
        hs = _sharpen(best, deadline - 1.5, iters=5)
        r = R_of(hs)
        if r > bestR + 1e-13:
            best, bestR = hs.copy(), r
        print("sharpen R=%.7f" % bestR)

    # Phase B: alternate refinement (upsample) and polish.
    it = 0
    while time.process_time() < deadline - 1.2:
        it += 1
        # Try refining to higher resolution
        if time.process_time() < deadline - 5.0:
            hr = _refine(best, deadline - 3.0, sub_iters=2)
            r = R_of(hr)
            if r > bestR + 1e-13:
                best, bestR = hr.copy(), r
                print("refine R=%.7f (N=%d)" % (bestR, best.size))

        # Polish at current resolution
        hp = _densify(best)
        hp = _lbfgs_pos(hp, _fun_grad_tie, 1200, deadline - 1.0)
        if time.process_time() >= deadline - 1.0:
            r = R_of(hp)
            if r > bestR + 1e-13:
                best, bestR = hp.copy(), r
            break
        for beta in [1e4, 1e5, 1e6, 1e7, 1e8]:
            if time.process_time() >= deadline - 1.0:
                break
            hp = _lbfgs_pos(hp, lambda hh, b=beta: _fun_grad_beta(hh, b),
                            200, deadline - 1.0)
        for frac, extra, beta in [(0.30, 256, 1e8), (0.30, 256, 0.0)]:
            if time.process_time() >= deadline - 1.0:
                break
            win = _peak_window(hp, tol=0.99, pad_frac=frac, extra=extra)
            fg = (lambda hh, b=beta: _fun_grad_beta(hh, b)) if beta > 0 else _fun_grad_tie
            hp = _lbfgs_block(hp, win, 250, deadline - 1.0, fg)
        if time.process_time() < deadline - 1.0:
            hp = _lbfgs_pos(hp, _fun_grad_tie, 300, deadline - 1.0)
        r = R_of(hp)
        acc = r > bestR + 1e-13
        if acc:
            best, bestR = hp.copy(), r
        if it % 2 == 0 or acc:
            print("iter %d R=%.7f acc=%s bestR=%.7f" % (it, r, acc, bestR))

    # Phase C: final sharpen + polish.
    if time.process_time() < deadline - 0.5:
        hs = _sharpen(best, deadline - 0.5, iters=3)
        r = R_of(hs)
        if r > bestR + 1e-13:
            best, bestR = hs.copy(), r
    if time.process_time() < deadline - 0.3:
        ht = _lbfgs_pos(best, _fun_grad_tie, 400, deadline - 0.3)
        r = R_of(ht)
        if r > bestR + 1e-13:
            best, bestR = ht.copy(), r

    print("final R=%.7f (N=%d, zeros %.1f%%, band01 %.2f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001)))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if bestR > start_bestR - 1e-6:
        out["alternative"] = best
    return out

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad_tie(h)
    e = np.exp(np.clip(beta * (Lf - mx), -60.0, 60.0))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad_tie(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad_tie

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_window(h, tol=0.9995, pad_frac=0.4, extra=256):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(h.size)
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * pad_frac))
    lo = max(0, lo - pad)
    hi = min(h.size - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _dilate(idx, n, r):
    if idx.size == 0:
        return idx
    mask = np.zeros(n, dtype=bool)
    mask[idx] = True
    out = mask.copy()
    for d in range(1, r + 1):
        out[d:] |= mask[:-d]
        out[:-d] |= mask[d:]
    return np.flatnonzero(out)


def _nearmax_fracs(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    return (float(np.mean(Lf >= 0.999 * mx)),
            float(np.mean(Lf >= 0.99 * mx)),
            float(np.mean(Lf >= 0.95 * mx)))


def _tie_count(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0
    return int(np.sum(Lf >= mx * (1.0 - 1e-10)))


# ---- NEW: plateau-flattening move ----
def _flatten_plateau(h, deadline):
    """Set values just below the max plateau up to the max, then re-optimise.
    Widening the near-max plateau is what raises ||f*f||_2^2 for a given max."""
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h, R_of(h)
    n = h.size
    best = h
    bestR = R_of(h)
    for frac in (0.9999, 0.999, 0.99, 0.97, 0.95, 0.90):
        if time.process_time() >= deadline - 1.0:
            break
        v = Lf[:n]
        sel = np.flatnonzero(v >= frac * mx)
        if sel.size == 0:
            continue
        active = _dilate(sel, n, 6)
        if active.size > 0.85 * n:
            continue
        cand = best.copy()
        cand[active] *= (1.0 + 0.02 * (frac - 0.5))
        cand = _rescale(cand)
        try:
            cand = _lbfgs_block(cand, active, 200,
                                min(deadline - 0.5,
                                    time.process_time() + 4.0), beta=1e7)
        except Exception:
            continue
        r = R_of(cand)
        if r > bestR + 1e-15:
            best, bestR = cand, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            startR = R_of(best)
        else:
            best, startR = None, 0.0
    else:
        best, startR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        startR = R_of(best)

    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # ---- Phase 1: peak ladder polish ----
    p1_end = t0 + budget_seconds * 0.35
    for pad in (0.15, 0.10, 0.06, 0.04, 0.025):
        if time.process_time() >= p1_end - 1.0:
            break
        win = _peak_window(best, pad_frac=pad, extra=128)
        ht = _lbfgs_block(best, win, 400,
                          min(p1_end - 0.5,
                              time.process_time() + 6.0), beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
        ht = _lbfgs_block(best, win, 400,
                          min(p1_end - 0.5,
                              time.process_time() + 6.0), tie=True)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
        f01, f1, f5 = _nearmax_fracs(best)
        print("peak pad=%.3f R=%.9f near 0.1%%/1%%/5%%=%.3f/%.3f/%.3f"
              % (pad, bestR, f01, f1, f5))

    # ---- Phase 2: plateau flattening ----
    p2_end = t0 + budget_seconds * 0.65
    for it in range(6):
        if time.process_time() >= p2_end - 1.0:
            break
        ht, r = _flatten_plateau(best, min(p2_end - 1.0,
                                           time.process_time() + 8.0))
        if r > bestR + 1e-15:
            best, bestR = ht, r
            print("flatten it=%d R=%.9f" % (it, bestR))
        else:
            break

    # ---- Phase 3: expanded peak window polish (wider) ----
    p3_end = t0 + budget_seconds * 0.85
    for pad in (0.20, 0.12, 0.08, 0.05, 0.03, 0.02):
        if time.process_time() >= p3_end - 1.0:
            break
        win = _peak_window(best, tol=0.99, pad_frac=pad, extra=256)
        if win.size > 0.9 * best.size:
            win = np.arange(best.size)
        ht = _lbfgs_block(best, win, 500,
                          min(p3_end - 0.5,
                              time.process_time() + 7.0), beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
            print("wide pad=%.3f R=%.9f" % (pad, bestR))

    # ---- Phase 4: full-array tie polish ----
    p4_end = t0 + budget_seconds * 0.97
    if time.process_time() < p4_end - 1.0:
        win = np.arange(best.size)
        ht = _lbfgs_block(best, win, 400,
                          min(p4_end - 0.5,
                              time.process_time() + 8.0), beta=1e7)
        r = R_of(ht)
        if r > bestR + 1e-15:
            best, bestR = ht, r
            print("full tie ACCEPT R=%.9f ties=%d" % (bestR, _tie_count(best)))

    f01, f1, f5 = _nearmax_fracs(best)
    print("final R=%.9f (start %.9f, N=%d, ties=%d, near 0.1%%/1%%/5%%=%.3f/%.3f/%.3f)"
          % (bestR, startR, best.size, _tie_count(best), f01, f1, f5))

    result = {"best": best}
    if start is not None and bestR <= startR + 1e-14:
        result["alternative"] = best
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-9))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0, tie=False):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = lambda hh: _fun_grad_beta(hh, beta)
    elif tie:
        fg = _fun_grad_tie
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_beta(hh, beta)) if beta > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _smooth(h, k):
    if k <= 1:
        return h
    ker = np.ones(k) / k
    hs = np.convolve(h, ker, mode='same')
    return np.clip(hs, 0.0, None)


def _perturb(h, rng, scale):
    h2 = h.copy()
    nz = np.flatnonzero(h2 > 0)
    if nz.size == 0:
        return h2
    factors = np.exp(rng.normal(0.0, scale, nz.size))
    h2[nz] *= factors
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.5
    rng = np.random.default_rng(20240607)

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        x = np.linspace(0, 1, 256)
        best = (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)
        best_r = R_of(best)

    cur = _rescale(best.copy())
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r

    print("start R = %.6f, N = %d" % (cur_r, cur.size))

    alt_returned = None

    # Phase 0: tie-aware polish on the current grid (breaks single-knot max)
    if time.process_time() < deadline - 30.0:
        t = _lbfgs_log(cur, maxiter=600, deadline=deadline - 26.0, tie=True)
        rt = R_of(t)
        if rt > best_r:
            best, best_r = t.copy(), rt
            cur, cur_r = t.copy(), rt
        print("tie polish R = %.6f" % rt)

    # Phase 1: refine on finer grid
    if time.process_time() < deadline - 22.0:
        N_up = min(cur.size * 2, 400000)
        up = _rescale(_prolongate(cur, N_up))
        up = _lbfgs_log(up, maxiter=400, deadline=deadline - 18.0, tie=True)
        up2 = _window_polish_peak(up, deadline - 16.0, 0.15, 20, maxiter=300)
        if R_of(up2) > R_of(up):
            up = up2
        up_r = R_of(up)
        print("alt refine fine R = %.6f (N_up=%d)" % (up_r, N_up))
        back = _rescale(_coarsen(up, cur.size))
        back_r = R_of(back)
        if back_r > best_r:
            best, best_r = back.copy(), back_r
            cur, cur_r = back.copy(), back_r
        elif up_r > best_r:
            best, best_r = up.copy(), up_r
            cur, cur_r = up.copy(), up_r
        else:
            alt_returned = up.copy()

    # Phase 2: coarsen-reprolong
    if cur.size >= 16384 and time.process_time() < deadline - 12.0:
        c = _rescale(_coarsen(cur, 16384))
        c = _lbfgs_log(c, maxiter=300, deadline=deadline - 6.0, tie=True)
        c = _rescale(_prolongate(c, cur.size))
        c = _lbfgs_log(c, maxiter=300, deadline=deadline, tie=True)
        rc = R_of(c)
        if rc > best_r:
            best, best_r = c.copy(), rc
            cur, cur_r = c.copy(), rc
        print("coarsen-reprolong R = %.6f" % rc)

    # Phase 3: main loop with continuation + tie polishing
    last_r = cur_r
    no_improve = 0
    restart_tries = 0
    betas = (4, 16, 64, 256)
    bi = 0
    while time.process_time() < deadline - 1.0:
        cand = _lbfgs_log(cur, maxiter=1500, deadline=deadline, tie=True)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 1.0:
            break

        beta = betas[bi % len(betas)]
        bi += 1
        cand = _lbfgs_log(cur, maxiter=400, deadline=deadline, beta=beta)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

        for frac, extra in ((0.05, 4), (0.15, 10), (0.30, 20)):
            if time.process_time() >= deadline - 1.0:
                break
            cand = _window_polish_peak(cur, deadline, frac, extra, maxiter=500)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

        if cur_r <= last_r + 1e-9:
            no_improve += 1
            if no_improve >= 2 and time.process_time() < deadline - 3.0:
                k = 3 if restart_tries % 2 == 0 else 5
                seed = _rescale(_smooth(cur, k))
                seed = _lbfgs_log(seed, maxiter=800, deadline=deadline, tie=True)
                rs = R_of(seed)
                if rs > cur_r:
                    cur, cur_r = seed, rs
                    if cur_r > best_r:
                        best, best_r = cur.copy(), cur_r
                    no_improve = 0
                else:
                    scale = 0.02 * (1 + restart_tries)
                    perturbed = _perturb(best, rng, min(scale, 0.2))
                    cand_p = _lbfgs_log(_rescale(perturbed), maxiter=1000,
                                        deadline=deadline, tie=True)
                    rp = R_of(cand_p)
                    if rp > cur_r:
                        cur, cur_r = cand_p, rp
                        if cur_r > best_r:
                            best, best_r = cur.copy(), cur_r
                        no_improve = 0
                    else:
                        cur = best.copy(); cur_r = best_r
                restart_tries += 1
        else:
            no_improve = 0
        last_r = cur_r

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None:
        out = {"best": best}
        if alt_returned is not None and alt_returned.size != best.size:
            out["alternative"] = alt_returned
        else:
            out["alternative"] = start_arr
        return out
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    Lm = mx
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _window_lbfgs(h0, lo, hi, deadline, maxiter=200):
    n = h0.size
    lo = max(0, lo); hi = min(n, hi)
    if hi - lo < 2:
        return h0
    h = np.clip(h0, 0, None)
    pos = np.arange(lo, hi)[h[lo:hi] > 0]
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _peak_window(h, deadline, bestR, half=None):
    n = h.size
    if n < 8:
        return h, bestR
    if half is None:
        half = max(64, n // 8)
    Lf = _knots(h)
    kmax = int(np.argmax(Lf))
    center = kmax - 1
    lo = max(0, center - half)
    hi = min(n, center + half)
    if hi - lo < 4:
        return h, bestR
    pos = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': 200, 'maxfun': 400,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h, bestR
    if res is None:
        return h, bestR
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    h2 = _rescale(h2)
    r2 = R_of(h2)
    if r2 > bestR + 1e-15:
        return h2, r2
    return h, bestR


def _near_max_fractions(h):
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return 0.0, 0.0, 0.0
    return (np.mean(Lf >= 0.999 * M),
            np.mean(Lf >= 0.99 * M),
            np.mean(Lf >= 0.95 * M))


# ---------------- Block-scale compound moves ----------------

def _runs(h):
    nz = h > 0
    runs = []
    n = h.size
    i = 0
    while i < n:
        if nz[i]:
            j = i
            while j + 1 < n and nz[j + 1]:
                j += 1
            runs.append((i, j))
            i = j + 1
        else:
            i += 1
    return runs


def _zero_gaps(h):
    z = h <= 0
    gaps = []
    n = h.size
    i = 0
    while i < n:
        if z[i]:
            j = i
            while j + 1 < n and z[j + 1]:
                j += 1
            gaps.append((i, j))
            i = j + 1
        else:
            i += 1
    return gaps


def _translate_block(h, a, b, k):
    n = h.size
    L = b - a + 1
    na = a + k
    nb = na + L - 1
    if na < 0 or nb >= n:
        return None
    h2 = h.copy()
    block = h[a:b + 1].copy()
    h2[a:b + 1] = 0.0
    h2[na:nb + 1] = block
    return h2


def _split_block(h, a, b, ratio):
    L = b - a + 1
    if L < 4:
        return None
    mid = a + L // 2
    h2 = h.copy()
    h2[a:mid] *= ratio
    h2[mid:b + 1] /= ratio
    return h2


def _fill_gap(h, ga, gb):
    n = h.size
    hl = h[ga - 1] if ga - 1 >= 0 else 0.0
    hr = h[gb + 1] if gb + 1 < n else 0.0
    if hl <= 0 and hr <= 0:
        return None
    h2 = h.copy()
    L = gb - ga + 2
    for i in range(ga, gb + 1):
        t = (i - ga + 1) / L
        h2[i] = (1 - t) * hl + t * hr
    return h2


def _widen_gap(h, ga, gb):
    n = h.size
    h2 = h.copy()
    if ga - 1 >= 0 and h[ga - 1] > 0:
        h2[ga - 1] = 0.0
    elif gb + 1 < n and h[gb + 1] > 0:
        h2[gb + 1] = 0.0
    else:
        return None
    return h2


# ---------------- Superposition helpers ----------------

def _superpose(h, s, alpha):
    """h_new of length N+s: h_new[:N]=h, h_new[s:s+N]+=alpha*h."""
    N = h.size
    s = int(s)
    if s <= 0 or s >= N:
        return None
    h2 = np.zeros(N + s, dtype=float)
    h2[:N] = h
    h2[s:s + N] += alpha * h
    return h2


def _detect_period(h, max_lag=None):
    N = h.size
    sup = (h > 0).astype(float)
    if max_lag is None:
        max_lag = max(2, N // 4)
    max_lag = min(max_lag, N - 1)
    if max_lag < 2:
        return max(1, N // 32)
    # FFT autocorrelation of support
    n2 = 1
    while n2 < 2 * N:
        n2 *= 2
    F = np.fft.rfft(sup, n2)
    ac = np.fft.irfft(F * np.conj(F), n2)[:N]
    if ac[0] <= 0:
        return max(1, N // 32)
    ac = ac / ac[0]
    lags = np.arange(2, max_lag + 1)
    vals = ac[lags]
    if vals.size == 0:
        return max(1, N // 32)
    mx = vals.max()
    if mx <= 0:
        return max(1, N // 32)
    cand = lags[vals >= 0.95 * mx]
    if cand.size == 0:
        return max(1, N // 32)
    return int(cand[0])


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    f01, f1, f5 = _near_max_fractions(best)
    print("base R=%.12f (N=%d) fracs 0.1%%=%.4f 1%%=%.4f 5%%=%.4f"
          % (bestR, best.size, f01, f1, f5))

    # ---------- Phase 0: superposition search ----------
    phase0_end = min(deadline - 5.0, t0 + 20.0)
    N = h0.size
    p = _detect_period(h0)
    print("detected period p=%d (N=%d)" % (p, N))

    shifts = set()
    for s in (p // 4, p // 3, p // 2, 2 * p // 3, 3 * p // 4, p - 1,
              p // 2 + 137, p // 3 + 991):
        if 1 <= s < N:
            shifts.add(int(s))
    rng = np.random.default_rng(12345)
    for _ in range(200):
        s = int(rng.integers(1, max(2, p + 1)))
        if 1 <= s < N:
            shifts.add(s)
    shifts = sorted(shifts)

    alphas = np.concatenate(([0.02, 0.05, 0.1, 0.15], np.arange(0.2, 2.0001, 0.1)))

    best_sup = None
    best_sup_R = bestR
    best_s = None
    best_alpha = None

    # coarse grid
    for s in shifts:
        if time.process_time() > phase0_end - 8.0:
            break
        for a in alphas:
            if time.process_time() > phase0_end - 8.0:
                break
            h2 = _superpose(h0, s, float(a))
            if h2 is None:
                continue
            h2 = _rescale(h2)
            r = R_of(h2)
            if r > best_sup_R:
                best_sup_R = r
                best_sup = h2
                best_s = s
                best_alpha = float(a)

    print("coarse superpose: best s=%s alpha=%s R_raw=%.12f (base %.12f)"
          % (best_s, best_alpha, best_sup_R, bestR))

    # refine top candidates: 1-D golden on alpha, integer search s +/- 3
    if best_s is not None:
        # collect top 5 by rescoring coarse (cheap: track separately)
        # We do a quick re-scan of top candidates around best_s
        cands = []
        for s in range(max(1, best_s - 3), min(N, best_s + 4)):
            for a in (best_alpha * 0.8, best_alpha, best_alpha * 1.2):
                if a <= 0:
                    continue
                if time.process_time() > phase0_end - 6.0:
                    break
                h2 = _superpose(h0, s, float(a))
                if h2 is None:
                    continue
                h2 = _rescale(h2)
                r = R_of(h2)
                cands.append((r, s, float(a)))
        cands.sort(reverse=True)
        # golden section on alpha for top few
        for (r0, s, a0) in cands[:5]:
            if time.process_time() > phase0_end - 4.0:
                break
            lo = max(1e-3, a0 * 0.5)
            hi = a0 * 2.0
            gr = (np.sqrt(5.0) - 1.0) / 2.0
            c = hi - gr * (hi - lo)
            d = lo + gr * (hi - lo)
            def fR(a):
                h2 = _superpose(h0, s, float(a))
                if h2 is None:
                    return 0.0
                return R_of(_rescale(h2))
            fc = fR(c); fd = fR(d)
            for _ in range(20):
                if time.process_time() > phase0_end - 3.0:
                    break
                if fc > fd:
                    hi = d; d = c; fd = fc
                    c = hi - gr * (hi - lo); fc = fR(c)
                else:
                    lo = c; c = d; fc = fd
                    d = lo + gr * (hi - lo); fd = fR(d)
            a_best = 0.5 * (lo + hi)
            h2 = _superpose(h0, s, float(a_best))
            if h2 is None:
                continue
            h2 = _rescale(h2)
            r = R_of(h2)
            if r > best_sup_R:
                best_sup_R = r
                best_sup = h2
                best_s = s
                best_alpha = float(a_best)

    print("refined superpose: s=%s alpha=%s R_raw=%.12f" % (best_s, best_alpha, best_sup_R))

    # Decide starting point for polish: superposition if it beats base
    if best_sup is not None and best_sup_R > bestR + 1e-12:
        best = best_sup.copy()
        bestR = best_sup_R
        print("superposition beats base, polishing from it")
    else:
        print("superposition did not beat base; polishing from base")

    # ---------- Polish: alternate full L-BFGS and peak window ----------
    while time.process_time() < deadline - 1.0:
        tlim = min(deadline - 0.5, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        gained = False
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("full R=%.12f" % bestR)
            gained = True
        tlim = min(deadline - 0.5, time.process_time() + 3.0)
        hw, rw = _peak_window(best, tlim, bestR)
        if rw > bestR + 1e-15:
            best = hw; bestR = rw
            print("peakwin R=%.12f" % bestR)
            gained = True
        if not gained:
            break

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    f01, f1, f5 = _near_max_fractions(best)
    print("final R=%.12f (start %.12f, N=%d) fracs 0.1%%=%.4f 1%%=%.4f 5%%=%.4f"
          % (bestR, startR, best.size, f01, f1, f5))

    if bestR > startR + 1e-15:
        alt = best_sup if best_sup is not None else h0
        return {"best": best, "alternative": alt}
    # superposition genuinely different from start: return as alternative
    if best_sup is not None and best_sup_R > 0:
        return {"best": h0, "alternative": best_sup}
    return {"best": h0, "alternative": best}

