    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _window_lbfgs(h0, lo, hi, deadline, maxiter=200):
    n = h0.size
    lo = max(0, lo); hi = min(n, hi)
    if hi - lo < 2:
        return h0
    pos = np.arange(lo, hi)
    hmax = h0.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h0[pos], floor, None))

    def f(u):
        hh = h0.copy()
        hh[pos] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h0.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _peak_polish(h, deadline):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    M = Lf.max()
    idx = np.flatnonzero(Lf >= 0.98 * M)
    if idx.size == 0:
        return h
    lo = max(0, idx.min() - 2)
    hi = min(h.size, idx.max() - 1)
    if hi <= lo:
        return h
    return _window_lbfgs(h, lo, hi, deadline, maxiter=100)


# ---------- Coarsening / rasterization helpers ----------

def _coarsen_mass(h, K):
    N = h.size
    c = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.linspace(0, N, K + 1)
    vals = np.empty(K)
    for k in range(K):
        lo = edges[k]; hi = edges[k + 1]
        def cum_at(x):
            if x <= 0:
                return 0.0
            if x >= N:
                return c[-1]
            i = int(np.floor(x))
            frac = x - i
            return c[i] + frac * h[i]
        mass = cum_at(hi) - cum_at(lo)
        vals[k] = mass / (hi - lo)
    return vals


def _rasterize(w, a, M):
    K = w.size
    edges = np.rint(np.cumsum(w) * M).astype(int)
    edges = np.clip(edges, 0, M)
    edges[0] = 0
    edges[-1] = M
    for k in range(1, K + 1):
        if edges[k] <= edges[k - 1]:
            edges[k] = edges[k - 1] + 1
    edges = np.clip(edges, 0, M)
    counts = np.diff(edges)
    counts = np.maximum(counts, 1)
    tot = counts.sum()
    if tot != M:
        counts[-1] += M - tot
        counts = np.maximum(counts, 1)
        tot = counts.sum()
        if tot != M:
            counts[0] += M - tot
            counts = np.maximum(counts, 1)
    return np.repeat(np.exp(a), counts)


def _lift_staircase(w, a, N):
    edges = np.rint(np.cumsum(w) * N).astype(int)
    edges = np.clip(edges, 0, N)
    edges[0] = 0
    edges[-1] = N
    for k in range(1, w.size + 1):
        if edges[k] <= edges[k - 1]:
            edges[k] = edges[k - 1] + 1
    edges = np.clip(edges, 0, N)
    counts = np.diff(edges)
    counts = np.maximum(counts, 1)
    tot = counts.sum()
    if tot != N:
        counts[-1] += N - tot
        counts = np.maximum(counts, 1)
        tot = counts.sum()
        if tot != N:
            counts[0] += N - tot
            counts = np.maximum(counts, 1)
    return np.repeat(np.exp(a), counts)


# ---------- Main ----------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    N = h0.size
    print("base R=%.12f (N=%d)" % (bestR, N))

    # Alternative: try to find a genuinely different construction via
    # free-width staircase optimisation at several K, then lift & polish.
    alt_best = None
    altR = -1.0

    # Try to build a coarse staircase and lift it up to N. This changes the
    # piecewise-constant structure and can escape local optima of the fine grid.
    try:
        M = min(N, 32768)
        K_list = [24, 32, 48, 64, 96]
        prev_w = None
        prev_a = None
        for K in K_list:
            if time.process_time() >= deadline - 8.0:
                break
            if K > N:
                continue
            v = _coarsen_mass(h0, K)
            if prev_w is None or prev_w.size != K:
                w0 = np.full(K, 1.0 / K)
                a0 = np.log(np.clip(v, 1e-12, None))
            else:
                w0 = prev_w.copy(); a0 = prev_a.copy()

            # Local optimisation on the coarse grid via coordinate ascent on R.
            # We use a simple pattern search: perturb each width and log-height.
            w = w0.copy(); a = a0.copy()
            h_cur = _rasterize(w, a, M)
            r_cur = _R_fft(h_cur)

            # A few gradient-free passes (cheap, since M is small)
            steps = [0.05, 0.02, 0.01, 0.005, 0.002, 0.001]
            for step in steps:
                if time.process_time() >= deadline - 6.0:
                    break
                improved = False
                for k in range(K):
                    if time.process_time() >= deadline - 6.0:
                        break
                    for delta in (step, -step):
                        w2 = w.copy()
                        # move width from neighbours
                        if k > 0:
                            dw = min(w[k], delta)
                            w2[k] -= dw; w2[k - 1] += dw
                        else:
                            dw = min(w[k], delta)
                            w2[k] -= dw; w2[k + 1] += dw
                        if np.any(w2 <= 0):
                            continue
                        h2 = _rasterize(w2, a, M)
                        r2 = _R_fft(h2)
                        if r2 > r_cur + 1e-14:
                            w = w2; r_cur = r2; improved = True
                    for da in (step, -step):
                        a2 = a.copy(); a2[k] += da
                        h2 = _rasterize(w, a2, M)
                        r2 = _R_fft(h2)
                        if r2 > r_cur + 1e-14:
                            a = a2; r_cur = r2; improved = True
                if not improved:
                    continue
            prev_w, prev_a = w, a
            print("staircase K=%d R=%.12f" % (K, r_cur))

            # Lift to full N and polish
            if time.process_time() < deadline - 6.0:
                try:
                    h_lift = _lift_staircase(w, a, N)
                    h_lift = _rescale(np.clip(h_lift, 0, None))
                    r_lift = R_of(h_lift)
                    tlim = min(deadline - 1.0, time.process_time() + 4.0)
                    hc = _full_lbfgs(h_lift, tlim, maxiter=150)
                    rc = R_of(hc)
                    if rc > r_lift:
                        h_lift, r_lift = hc, rc
                    if r_lift > altR:
                        alt_best = h_lift.copy(); altR = r_lift
                        print("  lifted K=%d R=%.12f" % (K, altR))
                except Exception as e:
                    print("  lift failed:", e)
    except Exception as e:
        print("staircase pipeline failed:", e)

    # ---- Continue polishing the true objective until deadline ----
    while time.process_time() < deadline - 0.5:
        tlim = min(deadline - 0.2, time.process_time() + 3.0)
        hc = _full_lbfgs(best, tlim, maxiter=200)
        rc = R_of(hc)
        if rc > bestR + 1e-15:
            best = hc; bestR = rc
            print("polish R=%.12f" % bestR)
        else:
            hc2 = _peak_polish(best, tlim)
            rc2 = R_of(hc2)
            if rc2 > bestR + 1e-15:
                best = hc2; bestR = rc2
                print("peak-polish R=%.12f" % bestR)
            else:
                break

    if alt_best is not None and altR > bestR:
        # alternative beats current — use it as the main result too
        # (still report it as best)
        best = alt_best.copy(); bestR = altR

    if bestR < startR:
        best = h0.copy()
        bestR = startR

    alt = alt_best if (alt_best is not None and altR > 0) else best

    print("final R=%.12f (start %.12f, N=%d, altR=%.12f)"
          % (bestR, startR, best.size, altR))

    return {"best": best, "alternative": alt}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad_tie(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    gLf = -dq / num
    idx = np.flatnonzero(Lf >= mx * (1.0 - 1e-10))
    w = 1.0 / idx.size
    gLf[idx] += w / mx
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
    return val, grad


def _fun_grad_cvar(h, alpha):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = max(1, int(round(alpha * Lf.size)))
    if m >= Lf.size:
        S = np.arange(Lf.size)
    else:
        S = np.argpartition(Lf, Lf.size - m)[Lf.size - m:]
    cm = Lf[S].mean()
    if cm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[S] += 1.0 / (m * cm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(cm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_custom(h0, fun_grad, deadline, maxiter=150):
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    pos = np.flatnonzero(h > 0)
    if pos.size == 0:
        return h0
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[pos], floor, None))

    def f(u):
        hh = h.copy()
        hh[pos] = np.exp(u)
        val, g = fun_grad(hh)
        return val, g[pos] * hh[pos]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * pos.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[pos] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _full_lbfgs(h0, deadline, maxiter=150):
    return _lbfgs_custom(h0, _fun_grad_tie, deadline, maxiter=maxiter)


def _peak_window_polish(h, deadline, pad=3, frac=8):
    if time.process_time() >= deadline - 0.5:
        return h
    Lf = _knots(h)
    pk = int(np.argmax(Lf))
    n = h.size
    c = pk / 2.0
    lo = max(0, int(c) - pad - n // frac)
    hi = min(n, int(c) + pad + n // frac)
    if hi - lo < 8:
        return h
    idx = np.arange(lo, hi)
    hmax = h.max()
    floor = 1e-12 * hmax if hmax > 0 else 1e-12
    u0 = np.log(np.clip(h[idx], floor, None))

    def f(u):
        hh = h.copy()
        hh[idx] = np.exp(u)
        val, g = _fun_grad_tie(hh)
        return val, g[idx] * hh[idx]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-40.0, 40.0)] * idx.size,
                       callback=cb,
                       options={'maxiter': 80, 'maxfun': 160,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h
    if res is None:
        return h
    h2 = h.copy()
    h2[idx] = np.exp(np.clip(res.x, -40.0, 40.0))
    return _rescale(h2)


def _smooth(h, sigma):
    if sigma <= 0:
        return h
    n = h.size
    r = int(np.ceil(3 * sigma))
    if r < 1:
        return h
    x = np.arange(-r, r + 1)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    return np.convolve(h, k, mode='same')


def _bin_average(h, m):
    n = h.size
    if m <= 1:
        return h.copy()
    nb = n // m
    if nb < 1:
        return h.copy()
    hb = h[:nb * m].reshape(nb, m).mean(axis=1)
    return hb


def _expand_blocks(v, m, n_target):
    h = np.repeat(v, m)
    if h.size < n_target:
        h = np.concatenate([h, np.zeros(n_target - h.size)])
    return h[:n_target]


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))
        return {"best": h0}

    base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
    if base.size == 0 or base.sum() <= 0:
        return {"best": base}
    h0 = _rescale(base)
    startR = R_of(h0)
    best = h0.copy()
    bestR = startR
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    N = best.size
    alternatives = []

    # Strategy: multi-resolution.  Build block-averaged coarse representations,
    # optimize them (cheap, low-dimensional), then upsample and refine.
    # Try several block counts and pick the best.

    # Try block counts: powers and neighbours
    block_counts = []
    for M in [16, 24, 32, 48, 64, 96, 128]:
        if N % M == 0 or True:
            m = max(1, N // M)
            if m >= 1:
                block_counts.append((M, m))

    # Also try smoothing the start at several scales and re-optimizing.
    # First, refine the start itself with LBFGS (cheap baseline).
    if time.process_time() < deadline - 5.0:
        tlim = min(deadline - 1.0, time.process_time() + 3.0)
        hp = _full_lbfgs(best, tlim, maxiter=120)
        Rp = R_of(hp)
        print("base+full R=%.12f" % Rp)
        if Rp > bestR:
            best = hp
            bestR = Rp

    # Multi-resolution block search
    rng = np.random.RandomState(1234567)

    def eval_blocks(v):
        # exact R for tiled block vector
        s = v.sum()
        if s <= 0:
            return 0.0
        L = np.convolve(v, v)
        a = L[:-1]; b = L[1:]
        num = np.sum(a * a + a * b + b * b) / 3.0
        mx = L.max()
        if mx <= 0:
            return 0.0
        return num / (s * s * mx)

    def polish_blocks(v, deadline_local, maxiter=80):
        vv = np.clip(v, 0, None)
        if vv.sum() <= 0:
            return v
        hmax = vv.max()
        floor = 1e-12 * hmax if hmax > 0 else 1e-12
        u0 = np.log(np.clip(vv, floor, None))

        def f(u):
            vc = np.exp(np.clip(u, -40.0, 40.0))
            s = vc.sum()
            if s <= 0:
                return 1e18, np.zeros_like(vc)
            L = np.convolve(vc, vc)
            a = L[:-1]; b = L[1:]
            num = np.sum(a * a + a * b + b * b) / 3.0
            dq = np.zeros_like(L)
            dq[:-1] += (2 * a + b)
            dq[1:] += (a + 2 * b)
            dq /= 3.0
            mx = L.max()
            if mx <= 0:
                return 1e18, np.zeros_like(vc)
            gL = -dq / num
            idx = np.flatnonzero(L >= mx * (1.0 - 1e-10))
            gL[idx] += 1.0 / (idx.size * mx)
            gv = 2.0 * np.correlate(gL, vc, mode='valid')[:vc.size]
            gv += 2.0 / s
            val = -np.log(num) + 2.0 * np.log(s) + np.log(mx)
            return val, gv * vc

        cb = _make_cb(deadline_local - 0.2)
        try:
            res = minimize(f, u0, jac=True, method='L-BFGS-B',
                           bounds=[(-40.0, 40.0)] * vv.size,
                           callback=cb,
                           options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                    'ftol': 1e-20, 'gtol': 1e-16})
        except (TimeoutError, Exception):
            return v
        if res is None:
            return v
        return np.exp(np.clip(res.x, -40.0, 40.0))

    best_block_v = None
    best_block_R = -1.0
    best_block_m = 1

    for (M, m) in block_counts:
        if time.process_time() > deadline - 8.0:
            break
        # block-average the current best (pad/truncate to multiple of m)
        n_use = (N // m) * m
        hb = best[:n_use].reshape(N // m, m).mean(axis=1)
        # initial candidates: block-averaged best, plus a few jittered versions
        cands = [hb.copy()]
        for _ in range(2):
            jit = np.clip(hb * (1.0 + 0.05 * rng.randn(hb.size)), 1e-30, None)
            cands.append(jit)
        for v in cands:
            if time.process_time() > deadline - 8.0:
                break
            tlim = min(deadline - 6.0, time.process_time() + 2.0)
            vp = polish_blocks(v, tlim, maxiter=100)
            Rp = eval_blocks(vp)
            if Rp > best_block_R:
                best_block_R = Rp
                best_block_v = vp.copy()
                best_block_m = m

    if best_block_v is not None:
        h_tile = np.repeat(best_block_v, best_block_m)
        if h_tile.size < N:
            h_tile = np.concatenate([h_tile, np.zeros(N - h_tile.size)])
        h_tile = h_tile[:N]
        h_tile = _rescale(h_tile)
        Rtile = R_of(h_tile)
        print("block tile R=%.12f m=%d" % (Rtile, best_block_m))
        if time.process_time() < deadline - 2.0:
            tlim = min(deadline - 1.0, time.process_time() + 3.0)
            hp = _full_lbfgs(h_tile, tlim, maxiter=150)
            Rp = R_of(hp)
            print("block tile+full R=%.12f" % Rp)
            if Rp > Rtile:
                h_tile = hp
                Rtile = Rp
        if Rtile > bestR:
            best = h_tile.copy()
            bestR = Rtile
            print("ACCEPT block: %.12f > %.12f" % (Rtile, startR))
        else:
            alternatives.append(h_tile)

    # Smoothing-based perturbations: smooth the best and re-optimize at full res.
    for sigma in [1.0, 2.0, 4.0]:
        if time.process_time() > deadline - 4.0:
            break
        hs = _smooth(best, sigma)
        hs = _rescale(hs)
        tlim = min(deadline - 1.0, time.process_time() + 2.0)
        hp = _full_lbfgs(hs, tlim, maxiter=120)
        Rp = R_of(hp)
        print("smooth sigma=%.1f R=%.12f" % (sigma, Rp))
        if Rp > bestR:
            best = hp
            bestR = Rp
        elif Rp > startR:
            alternatives.append(hp)

    # Remaining budget: alternating cvart + full polish on the best.
    alphas = [0.0001, 0.00003]
    k = 0
    while time.process_time() < deadline - 1.0:
        alpha = alphas[k % 2]
        k += 1
        tlim = min(deadline - 1.0, time.process_time() + 2.5)
        hc = _lbfgs_custom(best, lambda hh: _fun_grad_cvar(hh, alpha),
                           tlim, maxiter=150)
        if time.process_time() < deadline - 1.0:
            tlim2 = min(deadline - 1.0, time.process_time() + 1.5)
            hc = _full_lbfgs(hc, tlim2, maxiter=150)
        if time.process_time() < deadline - 1.0:
            tlim3 = min(deadline - 1.0, time.process_time() + 1.0)
