    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return np.zeros(h.size, dtype=bool)
    idx = np.flatnonzero(L >= mx * (1.0 - frac))
    if idx.size == 0:
        return np.zeros(h.size, dtype=bool)
    lo = max(0, int(idx[0]) - 1 - pad)
    hi = min(h.size, int(idx[-1]) - 1 + pad + 1)
    mask = np.zeros(h.size, dtype=bool)
    mask[lo:hi] = True
    return mask


def _window_lbfgs(h, deadline, frac=0.05, pad=20, maxiter=300):
    mask = _peak_mask(h, frac=frac, pad=pad)
    return _lbfgs_custom(h, _fun_grad_tie, deadline, maxiter=maxiter, mask=mask)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(20240517)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            h0 = _rescale(base)
        else:
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h0 = _rescale(2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i)))

    startR = R_of(h0)
    print("base R=%.12f (N=%d)" % (startR, h0.size))

    best = h0.copy()
    bestR = startR
    alt = None

    # Phase 1: short full descent to break ties on start
    tlim = min(deadline - 0.5, time.process_time() + 2.0)
    cand = _full_lbfgs(best, tlim, maxiter=200)
    rc = R_of(cand)
    if rc > bestR + 1e-15:
        best = cand; bestR = rc
        print("seed full R=%.12f" % bestR)

    # Phase 2: alternate full and multi-window descents
    stall = 0
    pass_idx = 0
    while time.process_time() < deadline - 0.3:
        remaining = deadline - time.process_time()
        prevR = bestR
        if pass_idx % 3 == 0:
            tlim = min(deadline - 0.2, time.process_time() + remaining * 0.55)
            cand = _full_lbfgs(best, tlim, maxiter=400)
            tag = "full"
        else:
            frac = 0.03 if pass_idx % 2 == 1 else 0.08
            pad = 20 + 10 * (pass_idx % 3)
            tlim = min(deadline - 0.2, time.process_time() + remaining * 0.55)
            cand = _window_lbfgs(best, tlim, frac=frac, pad=pad, maxiter=400)
            tag = "win%d" % pass_idx
        rc = R_of(cand)
        if rc > bestR + 1e-15:
            best = cand; bestR = rc
            print("%s R=%.12f (+%.2e)" % (tag, bestR, bestR - prevR))
        if bestR - prevR < 1e-9:
            stall += 1
        else:
            stall = 0
        if stall >= 2:
            # escape via coarsen/prolongate
            n = best.size
            hc = _coarsen(best, 4)
            cand = _prolongate(hc, n)
            tlim = min(deadline - 0.2, time.process_time() + remaining * 0.5)
            cand = _full_lbfgs(cand, tlim, maxiter=300)
            rc = R_of(cand)
            if rc > bestR + 1e-15:
                if alt is None or rc > R_of(alt):
                    alt = best.copy()
                best = cand; bestR = rc
                print("escape R=%.12f" % bestR)
            stall = 0
        pass_idx += 1

    if bestR < startR:
        if alt is None or bestR > R_of(alt):
            alt = best.copy()
        best = h0.copy()
        bestR = startR

    if alt is None:
        n = best.size
        hc = _coarsen(best, 4)
        alt = _prolongate(hc, n)
        if np.array_equal(alt, best):
            alt = h0.copy()

    print("final R=%.12f (start %.12f, N=%d)" % (bestR, startR, best.size))
    return {"best": best, "alternative": alt}

