    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    best = start_best.copy()
    bestR = start_bestR
    origin = 'start'
    print("base R=%.9f (N=%d)" % (bestR, best.size))

    # Phase 1: pnorm sweep to escape single-peak traps (cheap, on current N)
    p_sequence = [3.0, 6.0, 10.0, 16.0, 26.0, 40.0, 60.0, 90.0]
    for p in p_sequence:
        if time.process_time() >= deadline - 6.0:
            break
        ht = _lbfgs(best, 180, deadline - 5.0, mode='pnorm', param=p)
        ht = _lbfgs(ht, 180, deadline - 4.0, mode='exact')
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            origin = origin + '+p%.0f' % p
        print("pnorm p=%.0f: R=%.9f" % (p, bestR))

    # Phase 2: grid refinement to escape fixed-N local optimum
    for factor in [2, 2]:
        if time.process_time() >= deadline - 8.0:
            break
        ht = _refine_grid(best, factor, deadline - 6.0)
        ht = _lbfgs(ht, 300, deadline - 5.0, mode='exact')
        r = R_of(ht)
        if r > bestR + 1e-14:
            best, bestR = ht.copy(), r
            origin = origin + '+g%d' % factor
        print("refine x%d: R=%.9f (N=%d)" % (factor, bestR, best.size))

    # Phase 3: peak-window polish cycles
    cycle_ladder = [(0.05, 64), (0.15, 96), (0.30, 192), (0.50, 384),
                    (0.80, 512)]
    while time.process_time() < deadline - 1.0:
        improved = False
        for frac, extra in cycle_ladder:
            if time.process_time() >= deadline - 0.8:
                break
            win = _peak_window(best, pad_frac=frac, extra=extra)
            ht = _lbfgs(best, 200, deadline - 0.6, mode='exact', free=win)
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht.copy(), r
                origin = origin + '+w'
                improved = True
        if not improved:
            ht = _lbfgs(best, 200, deadline - 0.5, mode='exact')
            r = R_of(ht)
            if r > bestR + 1e-14:
                best, bestR = ht.copy(), r
                origin = origin + '+f'
            else:
                break

    print("final R=%.9f origin=%s (N=%d, zeros %.1f%%, band01 %.2f%%, band1 %.2f%%)" %
          (bestR, origin, best.size, 100.0 * np.mean(best <= 0),
           100.0 * _band_frac(best, 0.001), 100.0 * _band_frac(best, 0.01)))

    if start_best is None or bestR >= start_bestR - 1e-13:
        return best
    return {"best": start_best, "alternative": best}
